"""Extracted operator helpers; historical behavior and command contracts retained."""
from __future__ import annotations
from typing import TYPE_CHECKING
if TYPE_CHECKING:
    from pathlib import Path
    from datetime import datetime


def _check_phase16e_tags(repo_path: Path) -> dict:
    """Check that all Phase 16E+ required tags are present."""
    from trading_agent.cli.operator_common import Path, _PHASE16E_REQUIRED_TAGS
    import subprocess as _sp
    present: list[str] = []
    missing: list[str] = []
    try:
        p = _sp.run(
            ["git", "-C", str(repo_path), "tag"],
            capture_output=True, text=True, timeout=10,
        encoding="utf-8")
        all_tags = set(p.stdout.strip().splitlines())
        for tag in _PHASE16E_REQUIRED_TAGS:
            if tag in all_tags:
                present.append(tag)
            else:
                missing.append(tag)
    except Exception:
        missing = list(_PHASE16E_REQUIRED_TAGS)
        present = []
    return {
        "required_count": len(_PHASE16E_REQUIRED_TAGS),
        "present_count": len(present),
        "missing": missing,
        "present": present,
    }


def _take_stability_sample(
    now_utc: "datetime",
    sample_number: int,
    bridge_reachable: bool,
    bridge_connected: bool,
    bridge_mode: str,
    bridge_read_only: bool,
    bridge_service_active: bool,
    duplicate_bridge_processes: bool,
    endpoints_ok_count: int,
    endpoints_display: str,
    positions_count: int,
    positions_flat: bool,
    active_alerts_count: int,
    autonomy_level: str,
    clean_cycles: int | None,
    env_allow_orders: str,
    rules_enforced: str,
    system_locked: bool,
    guard_daily_trade_count: int,
    guard_trade_date: str,
    canonical_trade_date_val: str,
    guard_trade_date_stale: bool,
    guard_hash: str | None,
) -> dict:
    """Take a single stability sample snapshot."""
    return {
        "sample_number": sample_number,
        "timestamp": now_utc.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "bridge_reachable": bridge_reachable,
        "bridge_connected": bridge_connected,
        "bridge_service_active": bridge_service_active,
        "duplicate_bridge_processes": duplicate_bridge_processes,
        "mode": bridge_mode,
        "read_only": bridge_read_only,
        "endpoints_display": endpoints_display,
        "endpoints_ok": endpoints_ok_count,
        "positions_count": positions_count,
        "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
        "autonomy_level": autonomy_level,
        "clean_cycles": clean_cycles,
        "env_IBKR_ALLOW_ORDERS": env_allow_orders,
        "rules_enforced": rules_enforced,
        "system_locked": system_locked,
        "guard_daily_trade_count": guard_daily_trade_count,
        "guard_trade_date": guard_trade_date,
        "canonical_trade_date": canonical_trade_date_val,
        "guard_trade_date_stale": guard_trade_date_stale,
        "guard_hash": guard_hash,
    }


def _run_level1_post_promotion_stability_drill(
    samples_requested: int = 5,
    interval_seconds: int = 10,
) -> dict:
    """Run Level 1 post-promotion stability drill (Phase 16E).

    Multi-sample read-only drill that proves post-Level-1 stability:
    autonomy remains 1, orders remain disabled, all safety locks intact,
    no drift across samples.
    """
    from trading_agent.cli.operator_common import Any, BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _PHASE16E_DIAGNOSIS, _PHASE16E_EXPLICIT_NON_ACTIONS, _PHASE16E_EXPORT_DIR, _git_metadata, _read_env_safety, _read_rules_enforced, os
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import time as _time
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    ts_file = now_utc.strftime("%Y%m%dT%H%M%SZ")
    drill_id = f"level1-stability-{ts_file}"

    effective_samples = max(2, min(samples_requested, 30))
    effective_interval = max(1, min(interval_seconds, 300))

    # ------------------------------------------------------------------
    # 1. Git / worktree
    # ------------------------------------------------------------------
    git = _git_metadata(BRIDGE_DIR)
    full_commit = git.get("commit_short", "?")
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "rev-parse", "HEAD"],
            capture_output=True, text=True, timeout=5,
        encoding="utf-8")
        if p.stdout.strip():
            full_commit = p.stdout.strip()
    except Exception:
        pass

    worktree = _get_worktree_state(BRIDGE_DIR)
    origin_alignment = _get_origin_master_alignment(BRIDGE_DIR)

    git_section = {
        "branch": git.get("branch", "?"),
        "commit": full_commit if len(full_commit) > 16 else git.get("commit_short", "?"),
        "commit_short": git.get("commit_short", "?"),
        "tag": git.get("tag", "?"),
        "origin_master_commit": origin_alignment.get("origin_master_commit", "?"),
        "origin_master_aligned": origin_alignment.get("aligned"),
        "worktree_clean": worktree.get("clean"),
        "dirty_files": worktree.get("dirty_files", []),
    }

    # ------------------------------------------------------------------
    # 2. Required tags
    # ------------------------------------------------------------------
    required_tags = _check_phase16e_tags(BRIDGE_DIR)
    all_tags_present = len(required_tags["missing"]) == 0
    worktree_clean = git_section.get("worktree_clean", False)

    if not all_tags_present:
        return _phase16e_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16E_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags['missing'])}"],
            effective_samples, effective_interval,
        )

    if not worktree_clean and worktree_clean is not None:
        return _phase16e_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16E_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
            effective_samples, effective_interval,
        )

    # ------------------------------------------------------------------
    # 4. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")

    # ------------------------------------------------------------------
    # 5. Doctor / KPI / Policy (one-time)
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0)
        doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False)
        doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (
            doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1
        )
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status,
            "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") in ("autonomy_level_zero", "system_locked")
                    for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        kpi_section = {"verdict": kpi_verdict, "blockers": [b.get("check", "?") for b in kpi_blockers], "acceptable_hold": kpi_acceptable_hold}
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {"hermes_policy_exists": policy_result["hermes_policy_exists"], "advisory_boundary_ok": policy_result["advisory_boundary_ok"], "execution_path_ok": policy_result["execution_path_ok"]}

    # ------------------------------------------------------------------
    # 6. Multi-sample collection
    # ------------------------------------------------------------------
    samples: list[dict] = []
    guard_hashes: list[str] = []
    all_autonomy_level1 = True
    all_bridge_connected = True
    all_paper = True
    all_read_only = True
    all_endpoints_ok = True
    all_positions_flat = True
    all_alerts_clean = True
    all_guard_count_zero = True
    all_guard_date_current = True
    all_guard_halt_clean = True
    all_safety_locked = True
    env_stable = True
    rules_stable = True
    system_locked_stable = True
    guard_hash_stable = True
    first_env = env_allow_orders
    first_rules = rules_enforced
    first_system_locked: bool | None = None
    first_guard_hash: str | None = None

    try:
        from guard import canonical_trade_date as _canon
    except Exception:
        def _canon(dt):
            return dt.strftime("%Y-%m-%d")

    for sample_num in range(1, effective_samples + 1):
        sample_now = datetime.now(timezone.utc)
        canonical_td = _canon(sample_now)

        br_reachable = False
        br_connected = False
        br_mode = "?"
        br_read_only = False
        br_service_active = False
        dup_bridge = False
        ep_ok = 0
        ep_total = 0
        ep_display = "?"
        pos_count = 0
        pos_flat = True
        alert_count = 0
        sys_locked = True

        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    br_reachable = True
                    hd = _json.loads(resp.read().decode())
                    br_connected = hd.get("connected", False)
                    br_mode = hd.get("mode", "?")
                    br_read_only = br_mode == "paper"
        except Exception:
            pass

        if br_reachable:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
                with urllib.request.urlopen(req, timeout=8) as resp:
                    if resp.status == 200:
                        pd = _json.loads(resp.read().decode())
                        pl = pd.get("positions", [])
                        pos_count = len(pl)
                        pos_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
            except Exception:
                pass

        if br_reachable:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
                with urllib.request.urlopen(req, timeout=8) as resp:
                    if resp.status == 200:
                        ad = _json.loads(resp.read().decode())
                        all_a = ad.get("alerts", [])
                        alert_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
            except Exception:
                pass

        snapshot_used = False
        if br_reachable:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
                with urllib.request.urlopen(req, timeout=8) as resp:
                    if resp.status == 200:
                        snapshot_used = True
                        ep_ok = 7
                        ep_total = 7
                        ep_display = f"{ep_ok}/{ep_total} OK (snapshot)"
            except Exception:
                pass

        if not snapshot_used and br_reachable:
            _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                    "/monitor/alerts", "/monitor/events", "/positions", "/account"]
            ep_total = len(_EPS)
            for ep in _EPS:
                try:
                    req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                    with urllib.request.urlopen(req, timeout=5) as resp:
                        if resp.status == 200:
                            ep_ok += 1
                except Exception:
                    pass
            ep_display = f"{ep_ok}/{ep_total} OK"

        try:
            p = _sp.run(["systemctl", "is-active", "ibkr-bridge.service"],
                       capture_output=True, text=True, timeout=5, encoding="utf-8")
            br_service_active = p.stdout.strip() == "active"
        except Exception:
            pass

        try:
            p = _sp.run(["pgrep", "-c", "-f", "uvicorn bridge:app"],
                       capture_output=True, text=True, timeout=5, encoding="utf-8")
            cs = p.stdout.strip()
            uv_count = int(cs) if cs.isdigit() else 0
            dup_bridge = uv_count > 2
        except Exception:
            pass

        if br_reachable:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        rd = _json.loads(resp.read().decode())
                        sys_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
            except Exception:
                pass

        gs_assessment = _assess_guard_state_cleanliness(sample_now)
        g_count = gs_assessment["daily_trade_count"]
        g_date = gs_assessment["trade_date"]
        g_stale = gs_assessment["trade_date_stale"]
        g_hash = gs_assessment["guard_hash"]
        g_halt = gs_assessment["halt_active"]

        clean_cycles = None
        try:
            ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
            if ledger_path.exists():
                clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
            # else: stays None (unknown, not 0)
        except Exception:
            clean_cycles = None

        sample = _take_stability_sample(
            sample_now, sample_num, br_reachable, br_connected, br_mode,
            br_read_only, br_service_active, dup_bridge, ep_ok, ep_display,
            pos_count, pos_flat, alert_count, autonomy_level, clean_cycles,
            env_allow_orders, rules_enforced, sys_locked,
            g_count, g_date, canonical_td, g_stale, g_hash,
        )
        samples.append(sample)

        if autonomy_level != "1":
            all_autonomy_level1 = False
        if not br_connected:
            all_bridge_connected = False
        if br_mode != "paper":
            all_paper = False
        if not br_read_only:
            all_read_only = False
        if ep_ok < 1:
            all_endpoints_ok = False
        if not pos_flat:
            all_positions_flat = False
        if alert_count > 0:
            all_alerts_clean = False
        if g_count != 0:
            all_guard_count_zero = False
        if g_stale:
            all_guard_date_current = False
        if g_halt is not False:  # only clean when explicitly false
            all_guard_halt_clean = False
        if not sys_locked:
            system_locked_stable = False
        if env_allow_orders != first_env:
            env_stable = False
        if rules_enforced != first_rules:
            rules_stable = False
        if g_hash:
            guard_hashes.append(g_hash)
            if first_guard_hash is None:
                first_guard_hash = g_hash
            elif g_hash != first_guard_hash:
                guard_hash_stable = False

        sample_safety = env_allow_orders in ("false", "?") and rules_enforced in ("false", "?") and sys_locked is True
        if not sample_safety:
            all_safety_locked = False

        if first_system_locked is None:
            first_system_locked = sys_locked
        elif sys_locked != first_system_locked:
            system_locked_stable = False

        if sample_num < effective_samples:
            _time.sleep(effective_interval)

    # ------------------------------------------------------------------
    # 7. Baseline
    # ------------------------------------------------------------------
    first_sample = samples[0] if samples else {}
    baseline = {
        "autonomy_level": first_sample.get("autonomy_level", "?"),
        "clean_cycles": first_sample.get("clean_cycles"),
        "clean_cycles_source": "openclaw_clean_cycle_ledger",
        "bridge_connected": first_sample.get("bridge_connected", False),
        "mode": first_sample.get("mode", "?"),
        "read_only": first_sample.get("read_only", False),
        "positions_count": first_sample.get("positions_count", -1),
        "positions_flat": first_sample.get("positions_flat", False),
        "active_alerts_count": first_sample.get("active_alerts_count", -1),
        "env_IBKR_ALLOW_ORDERS": first_sample.get("env_IBKR_ALLOW_ORDERS", "?"),
        "rules_enforced": first_sample.get("rules_enforced", "?"),
        "system_locked": first_sample.get("system_locked", True),
        "guard_daily_trade_count": first_sample.get("guard_daily_trade_count", -1),
        "guard_trade_date": first_sample.get("guard_trade_date", "?"),
        "canonical_trade_date": first_sample.get("canonical_trade_date", "?"),
        "guard_trade_date_stale": first_sample.get("guard_trade_date_stale", True),
        "guard_hash": first_sample.get("guard_hash"),
    }

    # ------------------------------------------------------------------
    # 8. Stability summary
    # ------------------------------------------------------------------
    stability_summary = {
        "autonomy_level1_all_samples": all_autonomy_level1,
        "bridge_connected_all_samples": all_bridge_connected,
        "paper_all_samples": all_paper,
        "read_only_all_samples": all_read_only,
        "endpoints_ok_all_samples": all_endpoints_ok,
        "positions_flat_all_samples": all_positions_flat,
        "alerts_clean_all_samples": all_alerts_clean,
        "guard_trade_count_zero_all_samples": all_guard_count_zero,
        "guard_trade_date_current_all_samples": all_guard_date_current,
        "guard_halt_clean_all_samples": all_guard_halt_clean,
        "safety_locked_all_samples": all_safety_locked,
        "safety_flags_stable": env_stable and rules_stable and system_locked_stable,
        "guard_hash_stable": guard_hash_stable if len(guard_hashes) > 1 else True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "no_broker_mutation_seen": True,
    }

    # ------------------------------------------------------------------
    # 9. Classification
    # ------------------------------------------------------------------
    all_stable = (
        all_autonomy_level1 and all_bridge_connected and all_paper
        and all_read_only and all_endpoints_ok and all_positions_flat
        and all_alerts_clean and all_guard_count_zero and all_guard_date_current
        and all_guard_halt_clean
        and all_safety_locked and env_stable and rules_stable and system_locked_stable
    )

    run_time_ready = all_bridge_connected and all_paper and all_read_only

    if not all_tags_present:
        diagnosis = _PHASE16E_DIAGNOSIS["missing_required_tags"]
        severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16E_DIAGNOSIS["dirty_worktree"]
        severity = "NO_GO"
    elif not all_positions_flat and first_sample.get("positions_count", 0) > 0:
        diagnosis = _PHASE16E_DIAGNOSIS["positions_not_flat"]
        severity = "NO_GO"
    elif not all_alerts_clean:
        diagnosis = _PHASE16E_DIAGNOSIS["monitor_alerts_active"]
        severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16E_DIAGNOSIS["runtime_not_ready"]
        severity = "HOLD" if not all_bridge_connected else "NO_GO"
    elif not (env_allow_orders in ("false", "?") and rules_enforced in ("false", "?")):
        diagnosis = _PHASE16E_DIAGNOSIS["safety_not_locked"]
        severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16E_DIAGNOSIS["autonomy_not_level1"]
        severity = "NO_GO"
    elif not all_guard_count_zero or not all_guard_date_current or not all_guard_halt_clean:
        diagnosis = _PHASE16E_DIAGNOSIS["guard_state_not_clean"]
        severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16E_DIAGNOSIS["doctor_not_acceptable"]
        severity = "NO_GO"
    elif not kpi_section.get("acceptable_hold", False):
        diagnosis = _PHASE16E_DIAGNOSIS["kpi_not_acceptable"]
        severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16E_DIAGNOSIS["policy_boundary_missing"]
        severity = "NO_GO"
    elif not all_stable:
        diagnosis = _PHASE16E_DIAGNOSIS["stability_failed"]
        severity = "NO_GO"
    elif len(samples) < effective_samples:
        diagnosis = _PHASE16E_DIAGNOSIS["insufficient_samples"]
        severity = "HOLD"
    else:
        diagnosis = _PHASE16E_DIAGNOSIS["ready"]
        severity = "OK"

    drill_ok = diagnosis == _PHASE16E_DIAGNOSIS["ready"]
    operator_action_required = not drill_ok
    suggested_actions: list[str] = []
    if not drill_ok:
        suggested_actions.append(f"Stability drill failed: {diagnosis}")
        if not all_autonomy_level1:
            suggested_actions.append("Autonomy not Level 1 in all samples")
        if not all_bridge_connected:
            suggested_actions.append("Bridge disconnected in one or more samples")
        if not all_positions_flat:
            suggested_actions.append("Positions not flat in one or more samples")

    # ------------------------------------------------------------------
    # 10. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "samples": len(samples), "interval": effective_interval,
        "all_autonomy_level1": all_autonomy_level1,
        "all_bridge_connected": all_bridge_connected,
        "all_safety_locked": all_safety_locked,
        "guard_hash_stable": guard_hash_stable,
        "no_broker_mutation": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 11. Assemble result
    # ------------------------------------------------------------------
    result: dict[str, Any] = {
        "command": "ibkr-operator level1-post-promotion-stability-drill",
        "advisory": (
            "Read-only Level 1 post-promotion stability drill (Phase 16E). "
            f"{effective_samples} samples at {effective_interval}s intervals. "
            "No orders. No mutations. No H1 token. No broker activity. "
            "No autonomy level change."
        ),
        "timestamp": ts_str,
        "drill_id": drill_id,
        "samples_requested": effective_samples,
        "samples_collected": len(samples),
        "interval_seconds": effective_interval,
        "diagnosis": diagnosis,
        "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section,
        "required_tags": required_tags,
        "baseline": baseline,
        "clean_cycles_source": "openclaw_clean_cycle_ledger",
        "samples": samples,
        "stability_summary": stability_summary,
        "doctor_summary": doctor_section,
        "kpi_summary": kpi_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "h1_token_not_used": True,
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16E_EXPLICIT_NON_ACTIONS,
    }

    _PHASE16E_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
    export_path = _PHASE16E_EXPORT_DIR / f"{drill_id}.json"
    try:
        tmp = export_path.with_suffix(".tmp")
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str, ensure_ascii=False)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, export_path)
        result["export_path"] = str(export_path)
        result["_export_path"] = str(export_path)
    except Exception as e:
        result["_export_error"] = str(e)[:200]
        result["export_path"] = None

    return result


def _phase16e_no_go(
    drill_id: str, ts_str: str, git_section: dict, required_tags: dict,
    diagnosis: str, actions: list, samples_req: int, interval: int,
) -> dict:
    """Build a NO_GO result for early-exit prerequisite failures."""
    from trading_agent.cli.operator_common import _PHASE16E_EXPLICIT_NON_ACTIONS
    from trading_agent.cli.operator_workflow_helpers import _compute_evidence_hash
    return {
        "command": "ibkr-operator level1-post-promotion-stability-drill",
        "timestamp": ts_str,
        "drill_id": drill_id,
        "samples_requested": samples_req,
        "samples_collected": 0,
        "interval_seconds": interval,
        "diagnosis": diagnosis,
        "severity": "NO_GO",
        "operator_action_required": True,
        "suggested_operator_actions": actions,
        "git": git_section,
        "required_tags": required_tags,
        "baseline": {},
        "samples": [],
        "stability_summary": {},
        "doctor_summary": {},
        "kpi_summary": {},
        "policy_summary": {},
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "h1_token_not_used": True,
        "evidence_hash": _compute_evidence_hash({"diagnosis": diagnosis}),
        "explicit_non_actions": _PHASE16E_EXPLICIT_NON_ACTIONS,
    }


def _run_level1_evidence_normalization_check() -> dict:
    """Run Level 1 evidence normalization / clean-cycle consistency check (Phase 16F).

    Compares KPI clean_cycles against the canonical clean-cycle ledger source
    used by the Level 1 stability drill. Proves the drill and KPI agree on
    clean_cycles count and source.
    """
    from trading_agent.cli.operator_common import BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _PHASE16F_DIAGNOSIS, _PHASE16F_EXPLICIT_NON_ACTIONS, _PHASE16F_EXPORT_DIR, _PHASE16F_REQUIRED_TAGS, _git_metadata, _read_env_safety, _read_rules_enforced, os
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone
    from typing import Any

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    ts_file = now_utc.strftime("%Y%m%dT%H%M%SZ")
    check_id = f"evidence-normalization-{ts_file}"

    # ------------------------------------------------------------------
    # 1. Git / worktree
    # ------------------------------------------------------------------
    git = _git_metadata(BRIDGE_DIR)
    full_commit = git.get("commit_short", "?")
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "rev-parse", "HEAD"],
            capture_output=True, text=True, timeout=5,
        encoding="utf-8")
        if p.stdout.strip():
            full_commit = p.stdout.strip()
    except Exception:
        pass

    worktree = _get_worktree_state(BRIDGE_DIR)
    origin_alignment = _get_origin_master_alignment(BRIDGE_DIR)

    git_section = {
        "branch": git.get("branch", "?"),
        "commit": full_commit if len(full_commit) > 16 else git.get("commit_short", "?"),
        "commit_short": git.get("commit_short", "?"),
        "tag": git.get("tag", "?"),
        "origin_master_commit": origin_alignment.get("origin_master_commit", "?"),
        "origin_master_aligned": origin_alignment.get("aligned"),
        "worktree_clean": worktree.get("clean"),
        "dirty_files": worktree.get("dirty_files", []),
    }

    # ------------------------------------------------------------------
    # 2. Required tags
    # ------------------------------------------------------------------
    import subprocess as _sp2
    required_tags_present: list[str] = []
    required_tags_missing: list[str] = []
    try:
        p = _sp2.run(
            ["git", "-C", str(BRIDGE_DIR), "tag"],
            capture_output=True, text=True, timeout=10,
        encoding="utf-8")
        all_tags = set(p.stdout.strip().splitlines())
        for tag in _PHASE16F_REQUIRED_TAGS:
            if tag in all_tags:
                required_tags_present.append(tag)
            else:
                required_tags_missing.append(tag)
    except Exception:
        required_tags_missing = list(_PHASE16F_REQUIRED_TAGS)
        required_tags_present = []

    required_tags = {
        "required_count": len(_PHASE16F_REQUIRED_TAGS),
        "present_count": len(required_tags_present),
        "missing": required_tags_missing,
        "present": required_tags_present,
    }

    # Early exit: missing tags
    if len(required_tags_missing) > 0:
        return _phase16f_no_go(
            check_id, ts_str, git_section, required_tags,
            _PHASE16F_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags_missing)}"],
        )

    # Early exit: dirty worktree
    if not git_section.get("worktree_clean", False) and git_section.get("worktree_clean") is not None:
        return _phase16f_no_go(
            check_id, ts_str, git_section, required_tags,
            _PHASE16F_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
        )

    # ------------------------------------------------------------------
    # 3. Bridge runtime
    # ------------------------------------------------------------------
    br_reachable = False
    br_connected = False
    br_mode = "?"
    br_read_only = False
    ep_ok = 0
    ep_display = "?"
    try:
        req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
        with urllib.request.urlopen(req, timeout=8) as resp:
            if resp.status == 200:
                br_reachable = True
                hd = _json.loads(resp.read().decode())
                br_connected = hd.get("connected", False)
                br_mode = hd.get("mode", "?")
                br_read_only = br_mode == "paper"
    except Exception:
        pass

    # Endpoints
    snapshot_used = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    snapshot_used = True
                    ep_ok = 7
                    ep_display = f"{ep_ok}/7 OK (snapshot)"
        except Exception:
            pass

    if not snapshot_used and br_reachable:
        _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                "/monitor/alerts", "/monitor/events", "/positions", "/account"]
        ep_total = len(_EPS)
        for ep in _EPS:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        ep_ok += 1
            except Exception:
                pass
        ep_display = f"{ep_ok}/{len(_EPS)} OK"

    # Positions
    positions_count = 0
    positions_flat = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    pd = _json.loads(resp.read().decode())
                    pl = pd.get("positions", [])
                    positions_count = len(pl)
                    positions_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
        except Exception:
            pass

    # Alerts
    active_alerts_count = 0
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    ad = _json.loads(resp.read().decode())
                    all_a = ad.get("alerts", [])
                    active_alerts_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
        except Exception:
            pass

    runtime_section = {
        "bridge_reachable": br_reachable,
        "bridge_connected": br_connected,
        "mode": br_mode,
        "read_only": br_read_only,
        "endpoints_display": ep_display,
        "endpoints_ok": ep_ok,
        "positions_count": positions_count,
        "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
    }

    # ------------------------------------------------------------------
    # 4. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")
    system_locked = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status == 200:
                    rd = _json.loads(resp.read().decode())
                    system_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
        except Exception:
            pass

    safety_section = {
        "env_IBKR_ALLOW_ORDERS": env_allow_orders,
        "rules_enforced": rules_enforced,
        "system_locked": system_locked,
    }

    # ------------------------------------------------------------------
    # 5. Guard state
    # ------------------------------------------------------------------
    try:
        from guard import canonical_trade_date as _canon
    except Exception:
        def _canon(dt):
            return dt.strftime("%Y-%m-%d")

    gs_assessment = _assess_guard_state_cleanliness(now_utc)
    g_count = gs_assessment["daily_trade_count"]
    g_date = gs_assessment["trade_date"]
    g_stale = gs_assessment["trade_date_stale"]
    g_hash = gs_assessment["guard_hash"]
    guard_section = gs_assessment["guard_section"]

    # ------------------------------------------------------------------
    # 6. Doctor / KPI / Policy
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0)
        doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False)
        doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (
            doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1
        )
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status,
            "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}
    kpi_clean_cycles: int | None = None
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") in ("autonomy_level_zero", "system_locked")
                    for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        # Extract clean_cycles from KPI result
        au = kpi_result.get("autonomy", {})
        if isinstance(au, dict):
            kpi_clean_cycles = au.get("clean_cycles")
            if kpi_clean_cycles is None:
                kpi_clean_cycles = kpi_result.get("clean_cycles")
        if kpi_clean_cycles is None:
            kpi_clean_cycles = kpi_result.get("clean_cycles")
        kpi_section = {
            "verdict": kpi_verdict,
            "blockers": [b.get("check", "?") for b in kpi_blockers],
            "acceptable_hold": kpi_acceptable_hold,
        }
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {
        "hermes_policy_exists": policy_result["hermes_policy_exists"],
        "advisory_boundary_ok": policy_result["advisory_boundary_ok"],
        "execution_path_ok": policy_result["execution_path_ok"],
    }

    # ------------------------------------------------------------------
    # 7. Clean-cycles — canonical source (same as KPI)
    # ------------------------------------------------------------------
    canonical_ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
    clean_cycles_source = "openclaw_clean_cycle_ledger"
    drill_clean_cycles: int | None = None
    clean_cycles_defaulted_to_zero = False
    try:
        if canonical_ledger_path.exists():
            drill_clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
        # else: stays None — explicitly unknown, not defaulted to 0
    except Exception:
        drill_clean_cycles = None

    # Detect if drill previously defaulted to 0 when unknown
    # (the bug: calling non-existent _read_ledger and catching the error)
    # We check if drill_clean_cycles is 0 but the ledger has entries
    if drill_clean_cycles == 0 and canonical_ledger_path.exists():
        # Check if ledger has any lines
        try:
            with open(canonical_ledger_path, "r", encoding="utf-8") as f:
                line_count = sum(1 for line in f if line.strip())
            if line_count > 0:
                clean_cycles_defaulted_to_zero = True
        except Exception:
            pass

    # Compute match
    clean_cycles_matches_kpi = False
    if kpi_clean_cycles is not None and drill_clean_cycles is not None:
        clean_cycles_matches_kpi = (kpi_clean_cycles == drill_clean_cycles)
    elif kpi_clean_cycles is None and drill_clean_cycles is None:
        clean_cycles_matches_kpi = True  # both unknown

    # ------------------------------------------------------------------
    # 8. Normalization summary
    # ------------------------------------------------------------------
    evidence_normalized = clean_cycles_matches_kpi and not clean_cycles_defaulted_to_zero
    clean_cycle_consistency_ok = clean_cycles_matches_kpi
    stability_drill_source_corrected = True  # drill now uses canonical source
    unknown_clean_cycles_reported_as_null = (drill_clean_cycles is None and not canonical_ledger_path.exists())

    normalization_summary = {
        "evidence_normalized": evidence_normalized,
        "clean_cycle_consistency_ok": clean_cycle_consistency_ok,
        "stability_drill_source_corrected": stability_drill_source_corrected,
        "unknown_clean_cycles_reported_as_null": unknown_clean_cycles_reported_as_null,
    }

    autonomy_section = {
        "current_level": autonomy_level,
        "clean_cycles": drill_clean_cycles,
        "clean_cycles_source": clean_cycles_source,
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
        "kpi_clean_cycles": kpi_clean_cycles,
        "drill_clean_cycles": drill_clean_cycles,
    }

    # ------------------------------------------------------------------
    # 9. Classification
    # ------------------------------------------------------------------
    all_tags_present = len(required_tags_missing) == 0
    worktree_clean = git_section.get("worktree_clean", False)
    run_time_ready = br_connected and br_mode == "paper" and br_read_only
    safety_locked = env_allow_orders in ("false", "?") and rules_enforced in ("false", "?") and system_locked is True

    if not all_tags_present:
        diagnosis = _PHASE16F_DIAGNOSIS["missing_required_tags"]
        severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16F_DIAGNOSIS["dirty_worktree"]
        severity = "NO_GO"
    elif not positions_flat and positions_count > 0:
        diagnosis = _PHASE16F_DIAGNOSIS["positions_not_flat"]
        severity = "NO_GO"
    elif active_alerts_count > 0:
        diagnosis = _PHASE16F_DIAGNOSIS["monitor_alerts_active"]
        severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16F_DIAGNOSIS["runtime_not_ready"]
        severity = "HOLD" if not br_connected else "NO_GO"
    elif not safety_locked:
        diagnosis = _PHASE16F_DIAGNOSIS["safety_not_locked"]
        severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16F_DIAGNOSIS["autonomy_not_level1"]
        severity = "NO_GO"
    elif g_count != 0 or g_stale or gs_assessment["halt_active"] is not False:
        diagnosis = _PHASE16F_DIAGNOSIS["guard_state_not_clean"]
        severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16F_DIAGNOSIS["doctor_not_acceptable"]
        severity = "NO_GO"
    elif not kpi_acceptable_hold:
        diagnosis = _PHASE16F_DIAGNOSIS["kpi_not_acceptable"]
        severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16F_DIAGNOSIS["policy_boundary_missing"]
        severity = "NO_GO"
    elif clean_cycles_defaulted_to_zero:
        diagnosis = _PHASE16F_DIAGNOSIS["clean_cycles_defaulted_to_zero"]
        severity = "NO_GO"
    elif not clean_cycles_matches_kpi:
        diagnosis = _PHASE16F_DIAGNOSIS["clean_cycles_mismatch"]
        severity = "NO_GO"
    else:
        diagnosis = _PHASE16F_DIAGNOSIS["ready"]
        severity = "OK"

    check_ok = diagnosis == _PHASE16F_DIAGNOSIS["ready"]
    operator_action_required = not check_ok
    suggested_actions: list[str] = []
    if not check_ok:
        suggested_actions.append(f"Evidence normalization check failed: {diagnosis}")
        if not clean_cycles_matches_kpi:
            suggested_actions.append(f"KPI clean_cycles={kpi_clean_cycles} != drill clean_cycles={drill_clean_cycles}")
        if clean_cycles_defaulted_to_zero:
            suggested_actions.append("Drill clean_cycles defaulted to 0 when ledger has entries — source bug")

    # ------------------------------------------------------------------
    # 10. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
        "kpi_clean_cycles": kpi_clean_cycles,
        "drill_clean_cycles": drill_clean_cycles,
        "no_broker_mutation": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 11. Assemble result
    # ------------------------------------------------------------------
    result: dict[str, Any] = {
        "command": "ibkr-operator level1-evidence-normalization-check",
        "advisory": (
            "Read-only Level 1 evidence normalization / clean-cycle consistency check (Phase 16F). "
            "Compares KPI clean_cycles against the canonical openclaw_clean_cycle_ledger source. "
            "No orders. No mutations. No H1 token. No broker activity. "
            "No autonomy level change."
        ),
        "timestamp": ts_str,
        "check_id": check_id,
        "diagnosis": diagnosis,
        "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": runtime_section,
        "autonomy": autonomy_section,
        "safety": safety_section,
        "guard_state": guard_section,
        "normalization_summary": normalization_summary,
        "kpi_summary": kpi_section,
        "doctor_summary": doctor_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "h1_token_not_used": True,
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16F_EXPLICIT_NON_ACTIONS,
    }

    _PHASE16F_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
    export_path = _PHASE16F_EXPORT_DIR / f"{check_id}.json"
    try:
        tmp = export_path.with_suffix(".tmp")
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str, ensure_ascii=False)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, export_path)
        result["export_path"] = str(export_path)
        result["_export_path"] = str(export_path)
    except Exception as e:
        result["_export_error"] = str(e)[:200]
        result["export_path"] = None

    return result


def _phase16f_no_go(
    check_id: str, ts_str: str, git_section: dict, required_tags: dict,
    diagnosis: str, actions: list,
) -> dict:
    """Build a NO_GO result for early-exit prerequisite failures."""
    from trading_agent.cli.operator_common import _PHASE16F_EXPLICIT_NON_ACTIONS
    from trading_agent.cli.operator_workflow_helpers import _compute_evidence_hash
    return {
        "command": "ibkr-operator level1-evidence-normalization-check",
        "timestamp": ts_str,
        "check_id": check_id,
        "diagnosis": diagnosis,
        "severity": "NO_GO",
        "operator_action_required": True,
        "suggested_operator_actions": actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": {},
        "autonomy": {},
        "safety": {},
        "guard_state": {},
        "normalization_summary": {},
        "kpi_summary": {},
        "doctor_summary": {},
        "policy_summary": {},
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "h1_token_not_used": True,
        "evidence_hash": _compute_evidence_hash({"diagnosis": diagnosis}),
        "explicit_non_actions": _PHASE16F_EXPLICIT_NON_ACTIONS,
    }


def _run_level1_proposal_workflow_drill(
    demo_candidates: int = 2,
    proposal_source: str = "synthetic_readonly_demo",
) -> dict:
    """Run Level 1 proposal-only workflow drill (Phase 16G).

    Read-only drill proving Werner/operator can prepare proposal batches
    for Chris review without enabling orders, opening an order window,
    using H1, or calling any order endpoint.
    """
    from trading_agent.cli.operator_common import BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _PHASE16G_DIAGNOSIS, _PHASE16G_EXPLICIT_NON_ACTIONS, _PHASE16G_EXPORT_DIR, _PHASE16G_REQUIRED_TAGS, _PROPOSAL_SYMBOL_POOL, _git_metadata, _read_env_safety, _read_rules_enforced
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone
    from typing import Any

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    ts_file = now_utc.strftime("%Y%m%dT%H%M%SZ")
    drill_id = f"proposal-drill-{ts_file}"
    effective_candidates = max(0, min(demo_candidates, 5))

    # ------------------------------------------------------------------
    # 1. Git / worktree
    # ------------------------------------------------------------------
    git = _git_metadata(BRIDGE_DIR)
    full_commit = git.get("commit_short", "?")
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "rev-parse", "HEAD"],
            capture_output=True, text=True, timeout=5,
        encoding="utf-8")
        if p.stdout.strip():
            full_commit = p.stdout.strip()
    except Exception:
        pass

    worktree = _get_worktree_state(BRIDGE_DIR)
    origin_alignment = _get_origin_master_alignment(BRIDGE_DIR)

    git_section = {
        "branch": git.get("branch", "?"),
        "commit": full_commit if len(full_commit) > 16 else git.get("commit_short", "?"),
        "commit_short": git.get("commit_short", "?"),
        "tag": git.get("tag", "?"),
        "origin_master_commit": origin_alignment.get("origin_master_commit", "?"),
        "origin_master_aligned": origin_alignment.get("aligned"),
        "worktree_clean": worktree.get("clean"),
        "dirty_files": worktree.get("dirty_files", []),
    }

    # ------------------------------------------------------------------
    # 2. Required tags
    # ------------------------------------------------------------------
    required_tags_present: list[str] = []
    required_tags_missing: list[str] = []
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "tag"],
            capture_output=True, text=True, timeout=10,
        encoding="utf-8")
        all_tags = set(p.stdout.strip().splitlines())
        for tag in _PHASE16G_REQUIRED_TAGS:
            if tag in all_tags:
                required_tags_present.append(tag)
            else:
                required_tags_missing.append(tag)
    except Exception:
        required_tags_missing = list(_PHASE16G_REQUIRED_TAGS)
        required_tags_present = []

    required_tags = {
        "required_count": len(_PHASE16G_REQUIRED_TAGS),
        "present_count": len(required_tags_present),
        "missing": required_tags_missing,
        "present": required_tags_present,
    }

    # Early exit: missing tags
    if len(required_tags_missing) > 0:
        return _phase16g_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16G_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags_missing)}"],
        )

    # Early exit: dirty worktree
    if not git_section.get("worktree_clean", False) and git_section.get("worktree_clean") is not None:
        return _phase16g_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16G_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
        )

    # ------------------------------------------------------------------
    # 3. Bridge runtime
    # ------------------------------------------------------------------
    br_reachable = False
    br_connected = False
    br_mode = "?"
    br_read_only = False
    ep_ok = 0
    ep_display = "?"
    try:
        req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
        with urllib.request.urlopen(req, timeout=8) as resp:
            if resp.status == 200:
                br_reachable = True
                hd = _json.loads(resp.read().decode())
                br_connected = hd.get("connected", False)
                br_mode = hd.get("mode", "?")
                br_read_only = br_mode == "paper"
    except Exception:
        pass

    # Endpoints
    snapshot_used = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    snapshot_used = True
                    ep_ok = 7
                    ep_display = f"{ep_ok}/7 OK (snapshot)"
        except Exception:
            pass

    if not snapshot_used and br_reachable:
        _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                "/monitor/alerts", "/monitor/events", "/positions", "/account"]
        for ep in _EPS:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        ep_ok += 1
            except Exception:
                pass
        ep_display = f"{ep_ok}/{len(_EPS)} OK"

    # Positions
    positions_count = 0
    positions_flat = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    pd = _json.loads(resp.read().decode())
                    pl = pd.get("positions", [])
                    positions_count = len(pl)
                    positions_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
        except Exception:
            pass

    # Alerts
    active_alerts_count = 0
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    ad = _json.loads(resp.read().decode())
                    all_a = ad.get("alerts", [])
                    active_alerts_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
        except Exception:
            pass

    runtime_section = {
        "bridge_reachable": br_reachable,
        "bridge_connected": br_connected,
        "mode": br_mode,
        "read_only": br_read_only,
        "endpoints_display": ep_display,
        "endpoints_ok": ep_ok,
        "positions_count": positions_count,
        "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
    }

    # ------------------------------------------------------------------
    # 4. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")
    system_locked = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status == 200:
                    rd = _json.loads(resp.read().decode())
                    system_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
        except Exception:
            pass

    safety_section = {
        "env_IBKR_ALLOW_ORDERS": env_allow_orders,
        "rules_enforced": rules_enforced,
        "system_locked": system_locked,
    }

    # ------------------------------------------------------------------
    # 5. Guard state — centralized assessor
    # ------------------------------------------------------------------
    gs_assessment = _assess_guard_state_cleanliness(now_utc)
    guard_section = gs_assessment["guard_section"]

    # ------------------------------------------------------------------
    # 6. Doctor / KPI / Policy
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0)
        doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False)
        doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (
            doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1
        )
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status,
            "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}
    kpi_clean_cycles: int | None = None
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") == "system_locked"
                    for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        au = kpi_result.get("autonomy", {})
        if isinstance(au, dict):
            kpi_clean_cycles = au.get("clean_cycles")
            if kpi_clean_cycles is None:
                kpi_clean_cycles = kpi_result.get("clean_cycles")
        if kpi_clean_cycles is None:
            kpi_clean_cycles = kpi_result.get("clean_cycles")
        kpi_section = {
            "verdict": kpi_verdict,
            "blockers": [b.get("check", "?") for b in kpi_blockers],
            "acceptable_hold": kpi_acceptable_hold,
        }
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {
        "hermes_policy_exists": policy_result["hermes_policy_exists"],
        "advisory_boundary_ok": policy_result["advisory_boundary_ok"],
        "execution_path_ok": policy_result["execution_path_ok"],
    }

    # ------------------------------------------------------------------
    # 7. Clean-cycles — canonical source
    # ------------------------------------------------------------------
    canonical_ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
    clean_cycles_source = "openclaw_clean_cycle_ledger"
    drill_clean_cycles: int | None = None
    try:
        if canonical_ledger_path.exists():
            drill_clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
    except Exception:
        drill_clean_cycles = None

    clean_cycles_matches_kpi = False
    if kpi_clean_cycles is not None and drill_clean_cycles is not None:
        clean_cycles_matches_kpi = (kpi_clean_cycles == drill_clean_cycles)
    elif kpi_clean_cycles is None and drill_clean_cycles is None:
        clean_cycles_matches_kpi = True

    autonomy_section = {
        "current_level": autonomy_level,
        "clean_cycles": drill_clean_cycles,
        "clean_cycles_source": clean_cycles_source,
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
    }

    # ------------------------------------------------------------------
    # 8. Generate proposal batch (read-only synthetic demo)
    # ------------------------------------------------------------------
    proposals_created = 0
    proposal_items: list[dict[str, Any]] = []
    proposal_ids: list[str] = []
    import uuid

    for i in range(min(effective_candidates, len(_PROPOSAL_SYMBOL_POOL))):
        candidate = _PROPOSAL_SYMBOL_POOL[i]
        pid = f"proposal-{drill_id}-{i+1:03d}"
        quantity = (i + 1) * 10  # synthetic quantities: 10, 20, 30, ...
        item: dict[str, Any] = {
            "proposal_id": pid,
            "source": proposal_source,
            "symbol": candidate["symbol"],
            "side": candidate["side"],
            "quantity": quantity,
            "rationale": candidate["rationale"],
            "risk_notes": f"Synthetic demo proposal — not executable. Max position size: {quantity} shares. "
                          f"Requires Chris review before any order path.",
            "executable": False,
            "requires_chris_approval": True,
            "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
            "performed": False,
        }
        proposal_items.append(item)
        proposal_ids.append(pid)
        proposals_created += 1

    batch_id = f"proposal-batch-{ts_file}"
    proposal_batch: dict[str, Any] = {
        "batch_id": batch_id,
        "status": "review_only",
        "items": proposal_items,
    }

    proposal_workflow = {
        "proposal_only": True,
        "proposal_source": proposal_source,
        "demo_candidates_requested": effective_candidates,
        "candidates_examined": effective_candidates,
        "proposals_created": proposals_created,
        "proposals_marked_executable": False,
        "proposals_require_chris_review": True,
        "human_approval_required": True,
        "h1_required_for_future_submit": True,
        "order_window_required_for_future_submit": True,
        "order_routing_disallowed": True,
        "broker_submission_performed": False,
        "preflight_performed": False,
        "approval_performed": False,
        "submit_performed": False,
    }

    workflow_summary = {
        "level1_proposal_workflow_ready": True,
        "proposal_batch_created": proposals_created > 0,
        "all_items_non_executable": all(not it.get("executable", True) for it in proposal_items),
        "all_items_require_human_approval": all(it.get("requires_chris_approval", True) for it in proposal_items),
        "no_order_path_called": True,
        "no_broker_submission": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
    }

    # ------------------------------------------------------------------
    # 9. Classification
    # ------------------------------------------------------------------
    all_tags_present = len(required_tags_missing) == 0
    worktree_clean = git_section.get("worktree_clean", False)
    run_time_ready = br_connected and br_mode == "paper" and br_read_only
    safety_locked = env_allow_orders in ("false", "?") and rules_enforced in ("false", "?") and system_locked is True

    if not all_tags_present:
        diagnosis = _PHASE16G_DIAGNOSIS["missing_required_tags"]
        severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16G_DIAGNOSIS["dirty_worktree"]
        severity = "NO_GO"
    elif not positions_flat and positions_count > 0:
        diagnosis = _PHASE16G_DIAGNOSIS["positions_not_flat"]
        severity = "NO_GO"
    elif active_alerts_count > 0:
        diagnosis = _PHASE16G_DIAGNOSIS["monitor_alerts_active"]
        severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16G_DIAGNOSIS["runtime_not_ready"]
        severity = "HOLD" if not br_connected else "NO_GO"
    elif not safety_locked:
        diagnosis = _PHASE16G_DIAGNOSIS["safety_not_locked"]
        severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16G_DIAGNOSIS["autonomy_not_level1"]
        severity = "NO_GO"
    elif not gs_assessment["guard_state_clean"]:
        diagnosis = _PHASE16G_DIAGNOSIS["guard_state_not_clean"]
        severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16G_DIAGNOSIS["doctor_not_acceptable"]
        severity = "NO_GO"
    elif not kpi_acceptable_hold:
        diagnosis = _PHASE16G_DIAGNOSIS["kpi_not_acceptable"]
        severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16G_DIAGNOSIS["policy_boundary_missing"]
        severity = "NO_GO"
    elif not clean_cycles_matches_kpi:
        diagnosis = _PHASE16G_DIAGNOSIS["clean_cycles_mismatch"]
        severity = "NO_GO"
    else:
        diagnosis = _PHASE16G_DIAGNOSIS["ready"]
        severity = "OK"

    drill_ok = diagnosis == _PHASE16G_DIAGNOSIS["ready"]
    operator_action_required = not drill_ok
    suggested_actions: list[str] = []
    if not drill_ok:
        suggested_actions.append(f"Proposal workflow drill blocked: {diagnosis}")
        if not run_time_ready:
            suggested_actions.append("Ensure bridge is connected in paper read-only mode")
        if not safety_locked:
            suggested_actions.append("Verify all safety locks are engaged")
        if not gs_assessment["guard_state_clean"]:
            suggested_actions.append("Run guard-state-reconcile to fix guard state")

    # ------------------------------------------------------------------
    # 10. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "proposals_created": proposals_created,
        "proposal_source": proposal_source,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 11. Assemble result
    # ------------------------------------------------------------------
    result: dict[str, Any] = {
        "command": "ibkr-operator level1-proposal-workflow-drill",
        "advisory": (
            "Read-only Level 1 proposal-only workflow drill (Phase 16G). "
            "Prepares proposal batches for Chris review. "
            "No orders. No mutations. No H1 token. No broker activity. "
            "No autonomy level change. All proposals are non-executable and require human approval."
        ),
        "timestamp": ts_str,
        "drill_id": drill_id,
        "diagnosis": diagnosis,
        "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": runtime_section,
        "autonomy": autonomy_section,
        "safety": safety_section,
        "guard_state": guard_section,
        "proposal_workflow": proposal_workflow,
        "proposal_batch": proposal_batch,
        "workflow_summary": workflow_summary,
        "kpi_summary": kpi_section,
        "doctor_summary": doctor_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16G_EXPLICIT_NON_ACTIONS,
    }

    # ------------------------------------------------------------------
    # 12. Export artifact
    # ------------------------------------------------------------------
    export_path: str | None = None
    try:
        _PHASE16G_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        ep = _PHASE16G_EXPORT_DIR / f"{drill_id}.json"
        with open(ep, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str)
        export_path = str(ep)
    except Exception:
        pass

    result["export_path"] = export_path
    return result


def _phase16g_no_go(
    drill_id: str, ts_str: str, git_section: dict, required_tags: dict,
    diagnosis: str, actions: list,
) -> dict:
    """Build a NO_GO result for early-exit prerequisite failures."""
    from trading_agent.cli.operator_common import _PHASE16G_EXPLICIT_NON_ACTIONS
    from trading_agent.cli.operator_workflow_helpers import _compute_evidence_hash
    return {
        "command": "ibkr-operator level1-proposal-workflow-drill",
        "timestamp": ts_str,
        "drill_id": drill_id,
        "diagnosis": diagnosis,
        "severity": "NO_GO",
        "operator_action_required": True,
        "suggested_operator_actions": actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": {},
        "autonomy": {},
        "safety": {},
        "guard_state": {},
        "proposal_workflow": {},
        "proposal_batch": {"batch_id": drill_id, "status": "blocked", "items": []},
        "workflow_summary": {},
        "kpi_summary": {},
        "doctor_summary": {},
        "policy_summary": {},
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "evidence_hash": _compute_evidence_hash({"diagnosis": diagnosis}),
        "explicit_non_actions": _PHASE16G_EXPLICIT_NON_ACTIONS,
    }


def _run_level1_human_review_package_drill(
    demo_candidates: int = 2,
) -> dict:
    """Run Level 1 human review package drill (Phase 16H).

    Read-only drill that extends 16G by creating a review-only human review
    package/checklist artifact. Proves Werner/operator can prepare complete
    review packages for Chris without enabling orders, opening an order
    window, using H1, or calling any order endpoint.
    """
    from trading_agent.cli.operator_common import BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _PHASE16H_DIAGNOSIS, _PHASE16H_EXPLICIT_NON_ACTIONS, _PHASE16H_EXPORT_DIR, _PHASE16H_REQUIRED_TAGS, _REVIEW_CANDIDATE_POOL, _git_metadata, _read_env_safety, _read_rules_enforced
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone
    from typing import Any

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    ts_file = now_utc.strftime("%Y%m%dT%H%M%SZ")
    drill_id = f"review-package-drill-{ts_file}"
    effective_candidates = max(0, min(demo_candidates, 5))

    # ------------------------------------------------------------------
    # 1. Git / worktree
    # ------------------------------------------------------------------
    git = _git_metadata(BRIDGE_DIR)
    full_commit = git.get("commit_short", "?")
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "rev-parse", "HEAD"],
            capture_output=True, text=True, timeout=5,
        encoding="utf-8")
        if p.stdout.strip():
            full_commit = p.stdout.strip()
    except Exception:
        pass

    worktree = _get_worktree_state(BRIDGE_DIR)
    origin_alignment = _get_origin_master_alignment(BRIDGE_DIR)

    git_section = {
        "branch": git.get("branch", "?"),
        "commit": full_commit if len(full_commit) > 16 else git.get("commit_short", "?"),
        "commit_short": git.get("commit_short", "?"),
        "tag": git.get("tag", "?"),
        "origin_master_commit": origin_alignment.get("origin_master_commit", "?"),
        "origin_master_aligned": origin_alignment.get("aligned"),
        "worktree_clean": worktree.get("clean"),
        "dirty_files": worktree.get("dirty_files", []),
    }

    # ------------------------------------------------------------------
    # 2. Required tags
    # ------------------------------------------------------------------
    required_tags_present: list[str] = []
    required_tags_missing: list[str] = []
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "tag"],
            capture_output=True, text=True, timeout=10,
        encoding="utf-8")
        all_tags = set(p.stdout.strip().splitlines())
        for tag in _PHASE16H_REQUIRED_TAGS:
            if tag in all_tags:
                required_tags_present.append(tag)
            else:
                required_tags_missing.append(tag)
    except Exception:
        required_tags_missing = list(_PHASE16H_REQUIRED_TAGS)
        required_tags_present = []

    required_tags = {
        "required_count": len(_PHASE16H_REQUIRED_TAGS),
        "present_count": len(required_tags_present),
        "missing": required_tags_missing,
        "present": required_tags_present,
    }

    # Early exit: missing tags
    if len(required_tags_missing) > 0:
        return _phase16h_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16H_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags_missing)}"],
        )

    # Early exit: dirty worktree
    if not git_section.get("worktree_clean", False) and git_section.get("worktree_clean") is not None:
        return _phase16h_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16H_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
        )

    # ------------------------------------------------------------------
    # 3. Bridge runtime
    # ------------------------------------------------------------------
    br_reachable = False
    br_connected = False
    br_mode = "?"
    br_read_only = False
    ep_ok = 0
    ep_display = "?"
    try:
        req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
        with urllib.request.urlopen(req, timeout=8) as resp:
            if resp.status == 200:
                br_reachable = True
                hd = _json.loads(resp.read().decode())
                br_connected = hd.get("connected", False)
                br_mode = hd.get("mode", "?")
                br_read_only = br_mode == "paper"
    except Exception:
        pass

    snapshot_used = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    snapshot_used = True
                    ep_ok = 7
                    ep_display = f"{ep_ok}/7 OK (snapshot)"
        except Exception:
            pass

    if not snapshot_used and br_reachable:
        _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                "/monitor/alerts", "/monitor/events", "/positions", "/account"]
        for ep in _EPS:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        ep_ok += 1
            except Exception:
                pass
        ep_display = f"{ep_ok}/{len(_EPS)} OK"

    positions_count = 0
    positions_flat = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    pd = _json.loads(resp.read().decode())
                    pl = pd.get("positions", [])
                    positions_count = len(pl)
                    positions_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
        except Exception:
            pass

    active_alerts_count = 0
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    ad = _json.loads(resp.read().decode())
                    all_a = ad.get("alerts", [])
                    active_alerts_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
        except Exception:
            pass

    runtime_section = {
        "bridge_reachable": br_reachable,
        "bridge_connected": br_connected,
        "mode": br_mode,
        "read_only": br_read_only,
        "endpoints_display": ep_display,
        "endpoints_ok": ep_ok,
        "positions_count": positions_count,
        "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
    }

    # ------------------------------------------------------------------
    # 4. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")
    system_locked = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status == 200:
                    rd = _json.loads(resp.read().decode())
                    system_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
        except Exception:
            pass

    safety_section = {
        "env_IBKR_ALLOW_ORDERS": env_allow_orders,
        "rules_enforced": rules_enforced,
        "system_locked": system_locked,
    }

    # ------------------------------------------------------------------
    # 5. Guard state — centralized assessor
    # ------------------------------------------------------------------
    gs_assessment = _assess_guard_state_cleanliness(now_utc)
    guard_section = gs_assessment["guard_section"]

    # ------------------------------------------------------------------
    # 6. Doctor / KPI / Policy
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0)
        doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False)
        doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (
            doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1
        )
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status,
            "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}
    kpi_clean_cycles: int | None = None
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") == "system_locked"
                    for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        au = kpi_result.get("autonomy", {})
        if isinstance(au, dict):
            kpi_clean_cycles = au.get("clean_cycles")
            if kpi_clean_cycles is None:
                kpi_clean_cycles = kpi_result.get("clean_cycles")
        if kpi_clean_cycles is None:
            kpi_clean_cycles = kpi_result.get("clean_cycles")
        kpi_section = {
            "verdict": kpi_verdict,
            "blockers": [b.get("check", "?") for b in kpi_blockers],
            "acceptable_hold": kpi_acceptable_hold,
        }
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {
        "hermes_policy_exists": policy_result["hermes_policy_exists"],
        "advisory_boundary_ok": policy_result["advisory_boundary_ok"],
        "execution_path_ok": policy_result["execution_path_ok"],
    }

    # ------------------------------------------------------------------
    # 7. Clean-cycles — canonical source
    # ------------------------------------------------------------------
    canonical_ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
    clean_cycles_source = "openclaw_clean_cycle_ledger"
    drill_clean_cycles: int | None = None
    try:
        if canonical_ledger_path.exists():
            drill_clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
    except Exception:
        drill_clean_cycles = None

    clean_cycles_matches_kpi = False
    if kpi_clean_cycles is not None and drill_clean_cycles is not None:
        clean_cycles_matches_kpi = (kpi_clean_cycles == drill_clean_cycles)
    elif kpi_clean_cycles is None and drill_clean_cycles is None:
        clean_cycles_matches_kpi = True

    autonomy_section = {
        "current_level": autonomy_level,
        "clean_cycles": drill_clean_cycles,
        "clean_cycles_source": clean_cycles_source,
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
    }

    # ------------------------------------------------------------------
    # 8. Generate review package items (read-only synthetic)
    # ------------------------------------------------------------------
    items_created = 0
    review_items: list[dict[str, Any]] = []
    has_executable = False

    for i in range(min(effective_candidates, len(_REVIEW_CANDIDATE_POOL))):
        candidate = _REVIEW_CANDIDATE_POOL[i]
        rid = f"review-item-{drill_id}-{i+1:03d}"
        quantity = (i + 1) * 10
        item: dict[str, Any] = {
            "review_id": rid,
            "source": "synthetic_readonly_demo",
            "symbol": candidate["symbol"],
            "side": candidate["side"],
            "quantity": quantity,
            "rationale": candidate["rationale"],
            "risk_notes": (
                f"Synthetic demo review item — not executable. "
                f"Max position size: {quantity} shares. "
                f"Requires Chris review and explicit approval before any order path."
            ),
            "executable": False,
            "requires_chris_approval": True,
            "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
            "performed": False,
            "review_status": "pending_review",
            "review_checklist": [
                {"step": "verify_safety_locks", "description": "Confirm all safety locks engaged", "passed": True},
                {"step": "verify_guard_clean", "description": "Confirm guard-state is clean", "passed": True},
                {"step": "verify_position_sizing", "description": f"Confirm {quantity} shares within risk limits", "passed": None},
                {"step": "verify_market_conditions", "description": "Check market conditions before execution", "passed": None},
                {"step": "chris_approval", "description": "Chris explicitly approves this item", "passed": False},
                {"step": "h1_token_available", "description": "H1 token is available for future submit", "passed": None},
            ],
        }
        review_items.append(item)
        items_created += 1

    review_package_id = f"review-package-{ts_file}"
    review_package = {
        "package_id": review_package_id,
        "status": "review_only",
        "generated_by": "level1-human-review-package-drill (Phase 16H)",
        "requires_human_review": True,
        "review_deadline_hint": "Before any order enablement",
        "items": review_items,
        "summary": {
            "total_items": items_created,
            "executable_items": 0,
            "pending_review_items": items_created,
            "approved_items": 0,
            "rejected_items": 0,
        },
    }

    review_workflow = {
        "review_only": True,
        "demo_candidates_requested": effective_candidates,
        "candidates_examined": effective_candidates,
        "items_created": items_created,
        "items_marked_executable": False,
        "all_items_require_chris_review": True,
        "human_approval_required": True,
        "h1_required_for_future_submit": True,
        "order_window_required_for_future_submit": True,
        "order_routing_disallowed": True,
        "broker_submission_performed": False,
        "preflight_performed": False,
        "approval_performed": False,
        "submit_performed": False,
    }

    workflow_summary = {
        "level1_human_review_package_ready": True,
        "review_package_created": items_created > 0,
        "all_items_non_executable": all(not it.get("executable", True) for it in review_items),
        "all_items_require_human_approval": all(it.get("requires_chris_approval", True) for it in review_items),
        "no_order_path_called": True,
        "no_broker_submission": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
    }

    # ------------------------------------------------------------------
    # 9. Classification
    # ------------------------------------------------------------------
    all_tags_present = len(required_tags_missing) == 0
    worktree_clean = git_section.get("worktree_clean", False)
    run_time_ready = br_connected and br_mode == "paper" and br_read_only
    safety_locked = env_allow_orders in ("false", "?") and rules_enforced in ("false", "?") and system_locked is True

    if not all_tags_present:
        diagnosis = _PHASE16H_DIAGNOSIS["missing_required_tags"]
        severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16H_DIAGNOSIS["dirty_worktree"]
        severity = "NO_GO"
    elif not positions_flat and positions_count > 0:
        diagnosis = _PHASE16H_DIAGNOSIS["positions_not_flat"]
        severity = "NO_GO"
    elif active_alerts_count > 0:
        diagnosis = _PHASE16H_DIAGNOSIS["monitor_alerts_active"]
        severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16H_DIAGNOSIS["runtime_not_ready"]
        severity = "HOLD" if not br_connected else "NO_GO"
    elif not safety_locked:
        diagnosis = _PHASE16H_DIAGNOSIS["safety_not_locked"]
        severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16H_DIAGNOSIS["autonomy_not_level1"]
        severity = "NO_GO"
    elif not gs_assessment["guard_state_clean"]:
        diagnosis = _PHASE16H_DIAGNOSIS["guard_state_not_clean"]
        severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16H_DIAGNOSIS["doctor_not_acceptable"]
        severity = "NO_GO"
    elif not kpi_acceptable_hold:
        diagnosis = _PHASE16H_DIAGNOSIS["kpi_not_acceptable"]
        severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16H_DIAGNOSIS["policy_boundary_missing"]
        severity = "NO_GO"
    elif not clean_cycles_matches_kpi:
        diagnosis = _PHASE16H_DIAGNOSIS["clean_cycles_mismatch"]
        severity = "NO_GO"
    elif has_executable:
        diagnosis = _PHASE16H_DIAGNOSIS["executable_item_present"]
        severity = "NO_GO"
    else:
        diagnosis = _PHASE16H_DIAGNOSIS["ready"]
        severity = "OK"

    drill_ok = diagnosis == _PHASE16H_DIAGNOSIS["ready"]
    operator_action_required = not drill_ok
    suggested_actions: list[str] = []
    if not drill_ok:
        suggested_actions.append(f"Review package drill blocked: {diagnosis}")
        if not run_time_ready:
            suggested_actions.append("Ensure bridge is connected in paper read-only mode")
        if not safety_locked:
            suggested_actions.append("Verify all safety locks are engaged")
        if not gs_assessment["guard_state_clean"]:
            suggested_actions.append("Run guard-state-reconcile to fix guard state")

    # ------------------------------------------------------------------
    # 10. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "items_created": items_created,
        "all_non_executable": not has_executable,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 11. Assemble result
    # ------------------------------------------------------------------
    result: dict[str, Any] = {
        "command": "ibkr-operator level1-human-review-package-drill",
        "advisory": (
            "Read-only Level 1 human review package drill (Phase 16H). "
            "Extends 16G by creating a review-only human review package/checklist artifact. "
            "No orders. No mutations. No H1 token. No broker activity. "
            "No autonomy level change. All items are non-executable and require Chris approval."
        ),
        "timestamp": ts_str,
        "drill_id": drill_id,
        "diagnosis": diagnosis,
        "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": runtime_section,
        "autonomy": autonomy_section,
        "safety": safety_section,
        "guard_state": guard_section,
        "review_workflow": review_workflow,
        "review_package": review_package,
        "workflow_summary": workflow_summary,
        "kpi_summary": kpi_section,
        "doctor_summary": doctor_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16H_EXPLICIT_NON_ACTIONS,
    }

    # ------------------------------------------------------------------
    # 12. Export artifacts (JSON + review package artifact)
    # ------------------------------------------------------------------
    export_path: str | None = None
    review_package_path: str | None = None
    try:
        _PHASE16H_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        # Main JSON export
        ep = _PHASE16H_EXPORT_DIR / f"{drill_id}.json"
        with open(ep, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str)
        export_path = str(ep)
        # Review package artifact (standalone)
        rp_path = _PHASE16H_EXPORT_DIR / f"{review_package_id}.json"
        with open(rp_path, "w", encoding="utf-8") as f:
            _json.dump(review_package, f, indent=2, default=str)
        review_package_path = str(rp_path)
    except Exception:
        pass

    result["export_path"] = export_path
    result["review_package_path"] = review_package_path
    return result


def _phase16h_no_go(
    drill_id: str, ts_str: str, git_section: dict, required_tags: dict,
    diagnosis: str, actions: list,
) -> dict:
    """Build a NO_GO result for early-exit prerequisite failures."""
    from trading_agent.cli.operator_common import _PHASE16H_EXPLICIT_NON_ACTIONS
    from trading_agent.cli.operator_workflow_helpers import _compute_evidence_hash
    return {
        "command": "ibkr-operator level1-human-review-package-drill",
        "timestamp": ts_str,
        "drill_id": drill_id,
        "diagnosis": diagnosis,
        "severity": "NO_GO",
        "operator_action_required": True,
        "suggested_operator_actions": actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": {},
        "autonomy": {},
        "safety": {},
        "guard_state": {},
        "review_workflow": {},
        "review_package": {"package_id": drill_id, "status": "blocked", "items": []},
        "workflow_summary": {},
        "kpi_summary": {},
        "doctor_summary": {},
        "policy_summary": {},
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "evidence_hash": _compute_evidence_hash({"diagnosis": diagnosis}),
        "explicit_non_actions": _PHASE16H_EXPLICIT_NON_ACTIONS,
    }


def _run_level1_review_decision_drill(
    demo_candidates: int = 2,
    decision_mode: str = "mixed_demo",
    review_package_path: str | None = None,
) -> dict:
    """Run Level 1 review decision drill (Phase 16I).

    Read-only drill that applies accept/reject/defer decisions to a review
    package and produces an advisory audit decision artifact. Accepted items
    remain non-executable; no order paths are triggered.
    """
    from trading_agent.cli.operator_common import BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _DECISION_LOGIC, _DECISION_MODE_VALUES, _DECISION_RATIONALE_TEMPLATES, _PHASE16I_DIAGNOSIS, _PHASE16I_EXPLICIT_NON_ACTIONS, _PHASE16I_EXPORT_DIR, _PHASE16I_REQUIRED_TAGS, _REVIEW_CANDIDATE_POOL, _git_metadata, _read_env_safety, _read_rules_enforced
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone
    from typing import Any

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    ts_file = now_utc.strftime("%Y%m%dT%H%M%SZ")
    drill_id = f"review-decision-drill-{ts_file}"
    effective_candidates = max(0, min(demo_candidates, 5))
    if decision_mode not in _DECISION_MODE_VALUES:
        decision_mode = "mixed_demo"

    # ------------------------------------------------------------------
    # 1. Git / worktree
    # ------------------------------------------------------------------
    git_cfg = _git_metadata(BRIDGE_DIR)
    full_commit = git_cfg.get("commit_short", "?")
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "rev-parse", "HEAD"],
            capture_output=True, text=True, timeout=5,
        encoding="utf-8")
        if p.stdout.strip():
            full_commit = p.stdout.strip()
    except Exception:
        pass

    worktree = _get_worktree_state(BRIDGE_DIR)
    origin_alignment = _get_origin_master_alignment(BRIDGE_DIR)

    git_section = {
        "branch": git_cfg.get("branch", "?"),
        "commit": full_commit if len(full_commit) > 16 else git_cfg.get("commit_short", "?"),
        "commit_short": git_cfg.get("commit_short", "?"),
        "tag": git_cfg.get("tag", "?"),
        "origin_master_commit": origin_alignment.get("origin_master_commit", "?"),
        "origin_master_aligned": origin_alignment.get("aligned"),
        "worktree_clean": worktree.get("clean"),
        "dirty_files": worktree.get("dirty_files", []),
    }

    # ------------------------------------------------------------------
    # 2. Required tags
    # ------------------------------------------------------------------
    required_tags_present: list[str] = []
    required_tags_missing: list[str] = []
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "tag"],
            capture_output=True, text=True, timeout=10,
        encoding="utf-8")
        all_tags = set(p.stdout.strip().splitlines())
        for tag in _PHASE16I_REQUIRED_TAGS:
            if tag in all_tags:
                required_tags_present.append(tag)
            else:
                required_tags_missing.append(tag)
    except Exception:
        required_tags_missing = list(_PHASE16I_REQUIRED_TAGS)
        required_tags_present = []

    required_tags = {
        "required_count": len(_PHASE16I_REQUIRED_TAGS),
        "present_count": len(required_tags_present),
        "missing": required_tags_missing,
        "present": required_tags_present,
    }

    if len(required_tags_missing) > 0:
        return _phase16i_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16I_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags_missing)}"],
        )

    if not git_section.get("worktree_clean", False) and git_section.get("worktree_clean") is not None:
        return _phase16i_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16I_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
        )

    # ------------------------------------------------------------------
    # 3. Bridge runtime
    # ------------------------------------------------------------------
    br_reachable = False
    br_connected = False
    br_mode = "?"
    br_read_only = False
    ep_ok = 0
    ep_display = "?"
    try:
        req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
        with urllib.request.urlopen(req, timeout=8) as resp:
            if resp.status == 200:
                br_reachable = True
                hd = _json.loads(resp.read().decode())
                br_connected = hd.get("connected", False)
                br_mode = hd.get("mode", "?")
                br_read_only = br_mode == "paper"
    except Exception:
        pass

    snapshot_used = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    snapshot_used = True
                    ep_ok = 7
                    ep_display = f"{ep_ok}/7 OK (snapshot)"
        except Exception:
            pass

    if not snapshot_used and br_reachable:
        _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                "/monitor/alerts", "/monitor/events", "/positions", "/account"]
        for ep in _EPS:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        ep_ok += 1
            except Exception:
                pass
        ep_display = f"{ep_ok}/{len(_EPS)} OK"

    positions_count = 0
    positions_flat = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    pd = _json.loads(resp.read().decode())
                    pl = pd.get("positions", [])
                    positions_count = len(pl)
                    positions_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
        except Exception:
            pass

    active_alerts_count = 0
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    ad = _json.loads(resp.read().decode())
                    all_a = ad.get("alerts", [])
                    active_alerts_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
        except Exception:
            pass

    runtime_section = {
        "bridge_reachable": br_reachable,
        "bridge_connected": br_connected,
        "mode": br_mode,
        "read_only": br_read_only,
        "endpoints_display": ep_display,
        "endpoints_ok": ep_ok,
        "positions_count": positions_count,
        "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
    }

    # ------------------------------------------------------------------
    # 4. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")
    system_locked = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status == 200:
                    rd = _json.loads(resp.read().decode())
                    system_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
        except Exception:
            pass

    safety_section = {
        "env_IBKR_ALLOW_ORDERS": env_allow_orders,
        "rules_enforced": rules_enforced,
        "system_locked": system_locked,
    }

    # ------------------------------------------------------------------
    # 5. Guard state — centralized assessor
    # ------------------------------------------------------------------
    gs_assessment = _assess_guard_state_cleanliness(now_utc)
    guard_section = gs_assessment["guard_section"]

    # ------------------------------------------------------------------
    # 6. Doctor / KPI / Policy
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0)
        doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False)
        doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (
            doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1
        )
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status,
            "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}
    kpi_clean_cycles: int | None = None
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") == "system_locked"
                    for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        au = kpi_result.get("autonomy", {})
        if isinstance(au, dict):
            kpi_clean_cycles = au.get("clean_cycles")
            if kpi_clean_cycles is None:
                kpi_clean_cycles = kpi_result.get("clean_cycles")
        if kpi_clean_cycles is None:
            kpi_clean_cycles = kpi_result.get("clean_cycles")
        kpi_section = {
            "verdict": kpi_verdict,
            "blockers": [b.get("check", "?") for b in kpi_blockers],
            "acceptable_hold": kpi_acceptable_hold,
        }
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {
        "hermes_policy_exists": policy_result["hermes_policy_exists"],
        "advisory_boundary_ok": policy_result["advisory_boundary_ok"],
        "execution_path_ok": policy_result["execution_path_ok"],
    }

    # ------------------------------------------------------------------
    # 7. Clean-cycles
    # ------------------------------------------------------------------
    canonical_ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
    clean_cycles_source = "openclaw_clean_cycle_ledger"
    drill_clean_cycles: int | None = None
    try:
        if canonical_ledger_path.exists():
            drill_clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
    except Exception:
        drill_clean_cycles = None

    clean_cycles_matches_kpi = False
    if kpi_clean_cycles is not None and drill_clean_cycles is not None:
        clean_cycles_matches_kpi = (kpi_clean_cycles == drill_clean_cycles)
    elif kpi_clean_cycles is None and drill_clean_cycles is None:
        clean_cycles_matches_kpi = True

    autonomy_section = {
        "current_level": autonomy_level,
        "clean_cycles": drill_clean_cycles,
        "clean_cycles_source": clean_cycles_source,
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
    }

    # ------------------------------------------------------------------
    # 8. Load or reject input review package
    # ------------------------------------------------------------------
    review_package_source = "synthesized_internally"
    review_package_path_actual: str | None = None
    review_items: list[dict[str, Any]] = []
    package_id = "synthetic-demo"
    package_is_review_only = True

    if review_package_path:
        rp_path_obj = Path(review_package_path)
        if not rp_path_obj.exists() or not rp_path_obj.is_file():
            return _phase16i_no_go(
                drill_id, ts_str, git_section, required_tags,
                _PHASE16I_DIAGNOSIS["review_package_not_found"],
                [f"Review package not found: {review_package_path}"],
            )
        try:
            with open(rp_path_obj, encoding="utf-8") as f:
                rp_loaded = _json.load(f)
        except Exception:
            return _phase16i_no_go(
                drill_id, ts_str, git_section, required_tags,
                _PHASE16I_DIAGNOSIS["review_package_not_found"],
                [f"Review package unparseable: {review_package_path}"],
            )
        if rp_loaded.get("status") != "review_only":
            return _phase16i_no_go(
                drill_id, ts_str, git_section, required_tags,
                _PHASE16I_DIAGNOSIS["review_package_not_review_only"],
                [f"Review package status is '{rp_loaded.get('status')}', not 'review_only'",
                 "Re-run 16H to generate a valid review package"],
            )
        review_package_source = "loaded_from_prior_16h_artifact"
        review_package_path_actual = str(rp_path_obj.resolve())
        package_id = rp_loaded.get("package_id", "loaded-package")
        package_is_review_only = True
        review_items = rp_loaded.get("items", [])
        # Ensure safe defaults for loaded items
        for it in review_items:
            it.setdefault("executable", False)
            it.setdefault("requires_chris_approval", True)
            it.setdefault("performed", False)

    if not review_items and not review_package_path:
        # Synthesize internally (only when no --review-package given)
        candidate_pool = _REVIEW_CANDIDATE_POOL
        for i in range(min(effective_candidates, len(candidate_pool))):
            candidate = candidate_pool[i]
            rid = f"synthetic-review-item-{drill_id}-{i+1:03d}"
            review_items.append({
                "review_id": rid,
                "source": "synthetic_readonly_demo",
                "symbol": candidate["symbol"],
                "side": candidate["side"],
                "quantity": (i + 1) * 10,
                "rationale": candidate["rationale"],
                "risk_notes": f"Synthetic demo review item — not executable.",
                "executable": False,
                "requires_chris_approval": True,
                "performed": False,
                "review_status": "pending_review",
                "review_checklist": [
                    {"step": "verify_safety_locks", "description": "Confirm all safety locks engaged", "passed": True},
                    {"step": "verify_guard_clean", "description": "Confirm guard-state is clean", "passed": True},
                    {"step": "chris_approval", "description": "Chris explicitly approves this item", "passed": False},
                ],
            })
        package_id = f"synthetic-package-{ts_file}"

    # Package hash for integrity
    package_hashable = {
        "package_id": package_id,
        "items_count": len(review_items),
    }
    package_hash = _compute_evidence_hash(package_hashable)

    input_review_package = {
        "source": review_package_source,
        "package_id": package_id,
        "package_path": review_package_path_actual,
        "status": "review_only",
        "review_only": True,
        "items_count": len(review_items),
        "package_hash": package_hash,
    }

    # ------------------------------------------------------------------
    # 9. Apply decisions
    # ------------------------------------------------------------------
    decision_fn = _DECISION_LOGIC.get(decision_mode, _DECISION_LOGIC["mixed_demo"])
    decision_items: list[dict[str, Any]] = []
    accepted_count = 0
    rejected_count = 0
    deferred_count = 0

    for i, item in enumerate(review_items):
        verdict = decision_fn(i, item)
        reason = _DECISION_RATIONALE_TEMPLATES.get(verdict, "No decision.")
        decision_item: dict[str, Any] = {
            "proposal_id": f"decision-{drill_id}-{i+1:03d}",
            "review_id": item.get("review_id", f"item-{i}"),
            "symbol": item.get("symbol", "?"),
            "side": item.get("side", "?"),
            "quantity": item.get("quantity", 0),
            "original_executable": item.get("executable", False),
            "original_requires_approval": item.get("requires_chris_approval", True),
            "decision": verdict,
            "decision_reason": reason,
            "executable": False,
            "performed": False,
            "requires_chris_approval": True,
            "requires_future_order_window": True,
            "requires_future_h1": True,
            "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        }
        decision_items.append(decision_item)
        if verdict == "accept":
            accepted_count += 1
        elif verdict == "reject":
            rejected_count += 1
        else:
            deferred_count += 1

    decision_id = f"review-decision-{ts_file}"
    review_decision = {
        "decision_id": decision_id,
        "reviewer": "Chris",
        "decision_mode": decision_mode,
        "status": "audit_only",
        "decisions_count": len(decision_items),
        "accepted_count": accepted_count,
        "rejected_count": rejected_count,
        "deferred_count": deferred_count,
        "executable": False,
        "accepted_items_executable": False,
        "requires_future_order_window": True,
        "requires_future_h1": True,
        "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        "decision_items": decision_items,
    }

    # Decision artifact (standalone)
    decision_artifact = {
        "artifact_id": decision_id,
        "drill_id": drill_id,
        "status": "audit_only",
        "generated_by": "level1-review-decision-drill (Phase 16I)",
        "review_package": input_review_package,
        "review_decision": review_decision,
    }
    decision_artifact_hash = _compute_evidence_hash(decision_artifact)

    # ------------------------------------------------------------------
    # 10. Review workflow
    # ------------------------------------------------------------------
    review_workflow = {
        "decision_only": True,
        "demo_candidates_requested": effective_candidates,
        "items_examined": len(review_items),
        "decisions_applied": len(decision_items),
        "accepted_items_executable": False,
        "any_executable_item": False,
        "order_routing_disallowed": True,
        "broker_submission_performed": False,
        "preflight_performed": False,
        "approval_performed": False,
        "submit_performed": False,
    }

    workflow_summary = {
        "review_decision_ready": True,
        "decision_artifact_created": len(decision_items) > 0,
        "all_decisions_audit_only": True,
        "accepted_items_non_executable": accepted_count == 0 or review_decision["accepted_items_executable"] is False,
        "all_items_require_future_order_window": True,
        "all_items_require_future_h1": True,
        "no_order_path_called": True,
        "no_broker_submission": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
    }

    # ------------------------------------------------------------------
    # 11. Classification
    # ------------------------------------------------------------------
    all_tags_present = len(required_tags_missing) == 0
    worktree_clean = git_section.get("worktree_clean", False)
    run_time_ready = br_connected and br_mode == "paper" and br_read_only
    safety_locked = env_allow_orders in ("false", "?") and rules_enforced in ("false", "?") and system_locked is True

    if not all_tags_present:
        diagnosis = _PHASE16I_DIAGNOSIS["missing_required_tags"]
        severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16I_DIAGNOSIS["dirty_worktree"]
        severity = "NO_GO"
    elif not positions_flat and positions_count > 0:
        diagnosis = _PHASE16I_DIAGNOSIS["positions_not_flat"]
        severity = "NO_GO"
    elif active_alerts_count > 0:
        diagnosis = _PHASE16I_DIAGNOSIS["monitor_alerts_active"]
        severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16I_DIAGNOSIS["runtime_not_ready"]
        severity = "HOLD" if not br_connected else "NO_GO"
    elif not safety_locked:
        diagnosis = _PHASE16I_DIAGNOSIS["safety_not_locked"]
        severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16I_DIAGNOSIS["autonomy_not_level1"]
        severity = "NO_GO"
    elif not gs_assessment["guard_state_clean"]:
        diagnosis = _PHASE16I_DIAGNOSIS["guard_state_not_clean"]
        severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16I_DIAGNOSIS["doctor_not_acceptable"]
        severity = "NO_GO"
    elif not kpi_acceptable_hold:
        diagnosis = _PHASE16I_DIAGNOSIS["kpi_not_acceptable"]
        severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16I_DIAGNOSIS["policy_boundary_missing"]
        severity = "NO_GO"
    elif not clean_cycles_matches_kpi:
        diagnosis = _PHASE16I_DIAGNOSIS["clean_cycles_mismatch"]
        severity = "NO_GO"
    else:
        diagnosis = _PHASE16I_DIAGNOSIS["ready"]
        severity = "OK"

    drill_ok = diagnosis == _PHASE16I_DIAGNOSIS["ready"]
    operator_action_required = not drill_ok
    suggested_actions: list[str] = []
    if not drill_ok:
        suggested_actions.append(f"Review decision drill blocked: {diagnosis}")
        if not run_time_ready:
            suggested_actions.append("Ensure bridge is connected in paper read-only mode")
        if not safety_locked:
            suggested_actions.append("Verify all safety locks are engaged")
        if not gs_assessment["guard_state_clean"]:
            suggested_actions.append("Run guard-state-reconcile to fix guard state")

    # ------------------------------------------------------------------
    # 12. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "decisions_count": len(decision_items),
        "accepted_count": accepted_count,
        "rejected_count": rejected_count,
        "deferred_count": deferred_count,
        "accepted_items_executable": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 13. Assemble result
    # ------------------------------------------------------------------
    result: dict[str, Any] = {
        "command": "ibkr-operator level1-review-decision-drill",
        "advisory": (
            "Read-only Level 1 review decision drill (Phase 16I). "
            "Applies accept/reject/defer decisions to a review package. "
            "Accepted items remain advisory/audit only — NOT executable. "
            "No orders. No mutations. No H1 token. No broker activity. "
            "No autonomy level change."
        ),
        "timestamp": ts_str,
        "drill_id": drill_id,
        "diagnosis": diagnosis,
        "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": runtime_section,
        "autonomy": autonomy_section,
        "safety": safety_section,
        "guard_state": guard_section,
        "input_review_package": input_review_package,
        "review_decision": review_decision,
        "decision_artifact": decision_artifact,
        "decision_artifact_hash": decision_artifact_hash,
        "review_workflow": review_workflow,
        "workflow_summary": workflow_summary,
        "kpi_summary": kpi_section,
        "doctor_summary": doctor_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16I_EXPLICIT_NON_ACTIONS,
    }

    # ------------------------------------------------------------------
    # 14. Export artifacts
    # ------------------------------------------------------------------
    export_path: str | None = None
    decision_artifact_path: str | None = None
    try:
        _PHASE16I_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        ep = _PHASE16I_EXPORT_DIR / f"{drill_id}.json"
        with open(ep, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str)
        export_path = str(ep)
        da_path = _PHASE16I_EXPORT_DIR / f"{decision_id}.json"
        with open(da_path, "w", encoding="utf-8") as f:
            _json.dump(decision_artifact, f, indent=2, default=str)
        decision_artifact_path = str(da_path)
    except Exception:
        pass

    result["export_path"] = export_path
    result["decision_artifact_path"] = decision_artifact_path
    return result


def _phase16i_no_go(
    drill_id: str, ts_str: str, git_section: dict, required_tags: dict,
    diagnosis: str, actions: list,
) -> dict:
    """Build a NO_GO result for early-exit prerequisite failures."""
    from trading_agent.cli.operator_common import _PHASE16I_EXPLICIT_NON_ACTIONS
    from trading_agent.cli.operator_workflow_helpers import _compute_evidence_hash
    empty_decision = {"decisions_count": 0, "accepted_count": 0, "rejected_count": 0, "deferred_count": 0}
    empty_da = {"status": "blocked", "artifact_id": drill_id}
    return {
        "command": "ibkr-operator level1-review-decision-drill",
        "timestamp": ts_str,
        "drill_id": drill_id,
        "diagnosis": diagnosis,
        "severity": "NO_GO",
        "operator_action_required": True,
        "suggested_operator_actions": actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": {},
        "autonomy": {},
        "safety": {},
        "guard_state": {},
        "input_review_package": {},
        "review_decision": {**empty_decision, "decision_items": []},
        "decision_artifact": empty_da,
        "decision_artifact_hash": _compute_evidence_hash(empty_da),
        "review_workflow": {},
        "workflow_summary": {},
        "kpi_summary": {},
        "doctor_summary": {},
        "policy_summary": {},
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "evidence_hash": _compute_evidence_hash({"diagnosis": diagnosis}),
        "explicit_non_actions": _PHASE16I_EXPLICIT_NON_ACTIONS,
    }


def _run_level1_order_plan_draft_drill(
    demo_candidates: int = 3,
    decision_mode: str = "mixed_demo",
    decision_artifact_path: str | None = None,
) -> dict:
    """Run Level 1 order-plan draft drill (Phase 16J).

    Read-only drill that converts accepted audit-only review decisions into
    a non-executable order-plan draft artifact.  No order paths are triggered.
    """
    from trading_agent.cli.operator_common import BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _DECISION_LOGIC, _DECISION_MODE_VALUES, _DECISION_RATIONALE_TEMPLATES, _DRAFT_ITEM_TEMPLATE, _PHASE16J_DIAGNOSIS, _PHASE16J_EXPLICIT_NON_ACTIONS, _PHASE16J_EXPORT_DIR, _PHASE16J_REQUIRED_TAGS, _REVIEW_CANDIDATE_POOL, _git_metadata, _read_env_safety, _read_rules_enforced
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone
    from typing import Any

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    ts_file = now_utc.strftime("%Y%m%dT%H%M%SZ")
    drill_id = f"order-plan-draft-drill-{ts_file}"
    effective_candidates = max(0, min(demo_candidates, 5))
    if decision_mode not in _DECISION_MODE_VALUES:
        decision_mode = "mixed_demo"

    # ------------------------------------------------------------------
    # 1. Git / worktree
    # ------------------------------------------------------------------
    git_cfg = _git_metadata(BRIDGE_DIR)
    full_commit = git_cfg.get("commit_short", "?")
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "rev-parse", "HEAD"],
            capture_output=True, text=True, timeout=5,
        encoding="utf-8")
        if p.stdout.strip():
            full_commit = p.stdout.strip()
    except Exception:
        pass

    worktree = _get_worktree_state(BRIDGE_DIR)
    origin_alignment = _get_origin_master_alignment(BRIDGE_DIR)

    git_section = {
        "branch": git_cfg.get("branch", "?"),
        "commit": full_commit if len(full_commit) > 16 else git_cfg.get("commit_short", "?"),
        "commit_short": git_cfg.get("commit_short", "?"),
        "tag": git_cfg.get("tag", "?"),
        "origin_master_commit": origin_alignment.get("origin_master_commit", "?"),
        "origin_master_aligned": origin_alignment.get("aligned"),
        "worktree_clean": worktree.get("clean"),
        "dirty_files": worktree.get("dirty_files", []),
    }

    # ------------------------------------------------------------------
    # 2. Required tags
    # ------------------------------------------------------------------
    required_tags_present: list[str] = []
    required_tags_missing: list[str] = []
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "tag"],
            capture_output=True, text=True, timeout=10,
        encoding="utf-8")
        all_tags = set(p.stdout.strip().splitlines())
        for tag in _PHASE16J_REQUIRED_TAGS:
            if tag in all_tags:
                required_tags_present.append(tag)
            else:
                required_tags_missing.append(tag)
    except Exception:
        required_tags_missing = list(_PHASE16J_REQUIRED_TAGS)
        required_tags_present = []

    required_tags = {
        "required_count": len(_PHASE16J_REQUIRED_TAGS),
        "present_count": len(required_tags_present),
        "missing": required_tags_missing,
        "present": required_tags_present,
    }

    if len(required_tags_missing) > 0:
        return _phase16j_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16J_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags_missing)}"],
        )

    if not git_section.get("worktree_clean", False) and git_section.get("worktree_clean") is not None:
        return _phase16j_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16J_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
        )

    # ------------------------------------------------------------------
    # 3. Bridge runtime
    # ------------------------------------------------------------------
    br_reachable = False
    br_connected = False
    br_mode = "?"
    br_read_only = False
    ep_ok = 0
    ep_display = "?"
    try:
        req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
        with urllib.request.urlopen(req, timeout=8) as resp:
            if resp.status == 200:
                br_reachable = True
                hd = _json.loads(resp.read().decode())
                br_connected = hd.get("connected", False)
                br_mode = hd.get("mode", "?")
                br_read_only = br_mode == "paper"
    except Exception:
        pass

    snapshot_used = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    snapshot_used = True
                    ep_ok = 7
                    ep_display = f"{ep_ok}/7 OK (snapshot)"
        except Exception:
            pass

    if not snapshot_used and br_reachable:
        _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                "/monitor/alerts", "/monitor/events", "/positions", "/account"]
        for ep in _EPS:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        ep_ok += 1
            except Exception:
                pass
        ep_display = f"{ep_ok}/{len(_EPS)} OK"

    positions_count = 0
    positions_flat = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    pd = _json.loads(resp.read().decode())
                    pl = pd.get("positions", [])
                    positions_count = len(pl)
                    positions_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
        except Exception:
            pass

    active_alerts_count = 0
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    ad = _json.loads(resp.read().decode())
                    all_a = ad.get("alerts", [])
                    active_alerts_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
        except Exception:
            pass

    runtime_section = {
        "bridge_reachable": br_reachable,
        "bridge_connected": br_connected,
        "mode": br_mode,
        "read_only": br_read_only,
        "endpoints_display": ep_display,
        "endpoints_ok": ep_ok,
        "positions_count": positions_count,
        "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
    }

    # ------------------------------------------------------------------
    # 4. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")
    system_locked = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status == 200:
                    rd = _json.loads(resp.read().decode())
                    system_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
        except Exception:
            pass

    safety_section = {
        "env_IBKR_ALLOW_ORDERS": env_allow_orders,
        "rules_enforced": rules_enforced,
        "system_locked": system_locked,
    }

    # ------------------------------------------------------------------
    # 5. Guard state — centralized assessor
    # ------------------------------------------------------------------
    gs_assessment = _assess_guard_state_cleanliness(now_utc)
    guard_section = gs_assessment["guard_section"]

    # ------------------------------------------------------------------
    # 6. Doctor / KPI / Policy
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0)
        doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False)
        doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (
            doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1
        )
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status,
            "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}
    kpi_clean_cycles: int | None = None
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") == "system_locked"
                    for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        au = kpi_result.get("autonomy", {})
        if isinstance(au, dict):
            kpi_clean_cycles = au.get("clean_cycles")
            if kpi_clean_cycles is None:
                kpi_clean_cycles = kpi_result.get("clean_cycles")
        if kpi_clean_cycles is None:
            kpi_clean_cycles = kpi_result.get("clean_cycles")
        kpi_section = {
            "verdict": kpi_verdict,
            "blockers": [b.get("check", "?") for b in kpi_blockers],
            "acceptable_hold": kpi_acceptable_hold,
        }
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {
        "hermes_policy_exists": policy_result["hermes_policy_exists"],
        "advisory_boundary_ok": policy_result["advisory_boundary_ok"],
        "execution_path_ok": policy_result["execution_path_ok"],
    }

    # ------------------------------------------------------------------
    # 7. Clean-cycles
    # ------------------------------------------------------------------
    canonical_ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
    clean_cycles_source = "openclaw_clean_cycle_ledger"
    drill_clean_cycles: int | None = None
    try:
        if canonical_ledger_path.exists():
            drill_clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
    except Exception:
        drill_clean_cycles = None

    clean_cycles_matches_kpi = False
    if kpi_clean_cycles is not None and drill_clean_cycles is not None:
        clean_cycles_matches_kpi = (kpi_clean_cycles == drill_clean_cycles)
    elif kpi_clean_cycles is None and drill_clean_cycles is None:
        clean_cycles_matches_kpi = True

    autonomy_section = {
        "current_level": autonomy_level,
        "clean_cycles": drill_clean_cycles,
        "clean_cycles_source": clean_cycles_source,
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
    }

    # ------------------------------------------------------------------
    # 8. Load or synthesize decision artifact
    # ------------------------------------------------------------------
    decision_artifact_source = "synthesized_internally"
    decision_artifact_path_actual: str | None = None
    decisions_list: list[dict[str, Any]] = []
    da_decision_id = "synthetic-demo"
    da_is_audit_only = True

    if decision_artifact_path:
        da_path_obj = Path(decision_artifact_path)
        if not da_path_obj.exists() or not da_path_obj.is_file():
            return _phase16j_no_go(
                drill_id, ts_str, git_section, required_tags,
                _PHASE16J_DIAGNOSIS["decision_artifact_not_found"],
                [f"Decision artifact not found: {decision_artifact_path}"],
            )
        try:
            with open(da_path_obj, encoding="utf-8") as f:
                da_loaded = _json.load(f)
        except Exception:
            return _phase16j_no_go(
                drill_id, ts_str, git_section, required_tags,
                _PHASE16J_DIAGNOSIS["decision_artifact_not_found"],
                [f"Decision artifact unparseable: {decision_artifact_path}"],
            )
        if da_loaded.get("status") != "audit_only":
            return _phase16j_no_go(
                drill_id, ts_str, git_section, required_tags,
                _PHASE16J_DIAGNOSIS["decision_artifact_not_audit_only"],
                [f"Decision artifact status is '{da_loaded.get('status')}', not 'audit_only'",
                 "Re-run 16I to generate a valid decision artifact"],
            )
        decision_artifact_source = "loaded_from_prior_16i_artifact"
        decision_artifact_path_actual = str(da_path_obj.resolve())
        da_decision_id = da_loaded.get("artifact_id", da_loaded.get("decision_id", "loaded-decision"))
        da_rd = da_loaded.get("review_decision", {})
        decisions_list = da_rd.get("decision_items", da_rd.get("decisions", []))
        da_is_audit_only = True

    if not decisions_list and not decision_artifact_path:
        # Synthesize internally: run the same decision logic as 16I
        from typing import Any as _Any
        candidate_pool = _REVIEW_CANDIDATE_POOL
        decision_fn = _DECISION_LOGIC.get(decision_mode, _DECISION_LOGIC["mixed_demo"])
        for i in range(min(effective_candidates, len(candidate_pool))):
            candidate = candidate_pool[i]
            verdict = decision_fn(i, candidate)
            reason = _DECISION_RATIONALE_TEMPLATES.get(verdict, "No decision.")
            decisions_list.append({
                "proposal_id": f"synth-decision-{drill_id}-{i+1:03d}",
                "review_id": f"synth-review-{drill_id}-{i+1:03d}",
                "symbol": candidate["symbol"],
                "side": candidate["side"],
                "quantity": (i + 1) * 10,
                "decision": verdict,
                "decision_reason": reason,
                "executable": False,
                "performed": False,
                "requires_chris_approval": True,
                "requires_future_order_window": True,
                "requires_future_h1": True,
                "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
            })
        da_decision_id = f"synthetic-decision-{ts_file}"

    # Sanity: ensure safe defaults on loaded decisions
    for d in decisions_list:
        d.setdefault("executable", False)
        d.setdefault("performed", False)
        d.setdefault("requires_chris_approval", True)

    # Count totals from decision list
    all_decisions_count = len(decisions_list)
    all_accepted = [d for d in decisions_list if d.get("decision") == "accept"]
    all_rejected = [d for d in decisions_list if d.get("decision") == "reject"]
    all_deferred = [d for d in decisions_list if d.get("decision") == "defer"]

    # Artifact hash
    da_hashable = {
        "decision_id": da_decision_id,
        "decisions_count": all_decisions_count,
        "accepted": len(all_accepted),
    }
    artifact_hash = _compute_evidence_hash(da_hashable)

    input_decision_artifact = {
        "source": decision_artifact_source,
        "decision_id": da_decision_id,
        "decision_artifact_path": decision_artifact_path_actual,
        "status": "audit_only",
        "audit_only": da_is_audit_only,
        "decisions_count": all_decisions_count,
        "accepted_count": len(all_accepted),
        "rejected_count": len(all_rejected),
        "deferred_count": len(all_deferred),
        "artifact_hash": artifact_hash,
    }

    # ------------------------------------------------------------------
    # 9. Build order-plan draft — only accepted items
    # ------------------------------------------------------------------
    draft_items: list[dict[str, Any]] = []
    skipped_items: list[dict[str, Any]] = []
    has_executable = False
    has_broker_order = False
    rejected_or_deferred_in_draft = False
    for i, d in enumerate(all_accepted):
        if d.get("executable") is True:
            has_executable = True
        if d.get("broker_order_created") is True:
            has_broker_order = True
        src_proposal = d.get("proposal_id", d.get("review_id", f"item-{i}"))
        di: dict[str, Any] = {
            "plan_item_id": f"draft-{drill_id}-{i+1:03d}",
            "source_decision_id": d.get("proposal_id", d.get("review_id", "")),
            "source_proposal_id": src_proposal,
            "symbol": d.get("symbol", "?"),
            "side": d.get("side", "?"),
            "quantity": d.get("quantity", 0),
            "order_type": "LMT",
            "time_in_force": "DAY",
            "limit_price": None,
            "rationale": d.get("decision_reason", ""),
            "risk_notes": f"Draft item — non-executable. Requires Chris approval before any order path.",
            "original_decision": d.get("decision", "accept"),
            "original_decision_reason": d.get("decision_reason", ""),
            **_DRAFT_ITEM_TEMPLATE,
        }
        draft_items.append(di)

    # Sanity: rejected/deferred MUST NOT appear in draft
    rejected_ids = {d.get("proposal_id", d.get("review_id", "")) for d in all_rejected}
    deferred_ids = {d.get("proposal_id", d.get("review_id", "")) for d in all_deferred}
    for di in draft_items:
        src = di.get("source_proposal_id", di.get("source_decision_id", ""))
        if src in rejected_ids or src in deferred_ids:
            rejected_or_deferred_in_draft = True

    # Build skipped_items[]
    for d in all_rejected:
        skipped_items.append({
            "source_proposal_id": d.get("proposal_id", d.get("review_id", "")),
            "decision": d.get("decision", "reject"),
            "skip_reason": d.get("decision_reason", "Rejected — will not proceed to order plan."),
        })
    for d in all_deferred:
        skipped_items.append({
            "source_proposal_id": d.get("proposal_id", d.get("review_id", "")),
            "decision": d.get("decision", "defer"),
            "skip_reason": d.get("decision_reason", "Deferred — requires additional review before order plan."),
        })

    plan_id = f"order-plan-draft-{ts_file}"
    order_plan_draft = {
        "plan_id": plan_id,
        "status": "draft_only",
        "plan_source": "synthetic_readonly_demo",
        "executable": False,
        "broker_order_created": has_broker_order,
        "broker_submission_performed": False,
        "preflight_performed": False,
        "approval_performed": False,
        "submit_performed": False,
        "requires_future_order_window": True,
        "requires_future_h1": True,
        "requires_future_chris_approval": True,
        "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        "draft_items_count": len(draft_items),
        "skipped_rejected_count": len(all_rejected),
        "skipped_deferred_count": len(all_deferred),
        "draft_items": draft_items,
        "skipped_items": skipped_items,
    }

    # Plan artifact (standalone)
    plan_artifact = {
        "artifact_id": plan_id,
        "drill_id": drill_id,
        "status": "draft_only",
        "generated_by": "level1-order-plan-draft-drill (Phase 16J)",
        "input_decision_artifact": input_decision_artifact,
        "order_plan_draft": order_plan_draft,
    }
    plan_artifact_hash = _compute_evidence_hash(plan_artifact)
    plan_id_slug = plan_id

    # ------------------------------------------------------------------
    # 10. Plan workflow
    # ------------------------------------------------------------------
    plan_workflow = {
        "draft_only": True,
        "demo_candidates_requested": effective_candidates,
        "decisions_examined": all_decisions_count,
        "accepted_items": len(all_accepted),
        "draft_items_created": len(draft_items),
        "rejected_items_skipped": len(all_rejected),
        "deferred_items_skipped": len(all_deferred),
        "skipped_items_count": len(skipped_items),
        "any_executable_item": has_executable,
        "any_broker_order_created": has_broker_order,
        "rejected_or_deferred_in_draft": rejected_or_deferred_in_draft,
        "order_routing_disallowed": True,
        "broker_submission_performed": False,
        "preflight_performed": False,
        "approval_performed": False,
        "submit_performed": False,
    }

    workflow_summary = {
        "order_plan_draft_ready": True,
        "order_plan_draft_created": len(draft_items) > 0,
        "accepted_items_converted_to_draft": len(all_accepted) > 0 and len(draft_items) == len(all_accepted),
        "rejected_items_skipped": len(all_rejected) > 0 or (len(all_rejected) == 0 and True),
        "deferred_items_skipped": len(all_deferred) > 0 or (len(all_deferred) == 0 and True),
        "all_draft_items_non_executable": not has_executable,
        "no_broker_order_created": not has_broker_order,
        "all_items_require_future_order_window": True,
        "all_items_require_future_h1": True,
        "all_items_require_future_chris_approval": True,
        "no_order_path_called": True,
        "no_preflight_performed": True,
        "no_approval_performed": True,
        "no_submit_performed": True,
        "no_broker_submission": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
    }

    # ------------------------------------------------------------------
    # 11. Classification
    # ------------------------------------------------------------------
    all_tags_present = len(required_tags_missing) == 0
    worktree_clean = git_section.get("worktree_clean", False)
    run_time_ready = br_connected and br_mode == "paper" and br_read_only
    safety_locked = env_allow_orders in ("false", "?") and rules_enforced in ("false", "?") and system_locked is True

    if not all_tags_present:
        diagnosis = _PHASE16J_DIAGNOSIS["missing_required_tags"]
        severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16J_DIAGNOSIS["dirty_worktree"]
        severity = "NO_GO"
    elif not positions_flat and positions_count > 0:
        diagnosis = _PHASE16J_DIAGNOSIS["positions_not_flat"]
        severity = "NO_GO"
    elif active_alerts_count > 0:
        diagnosis = _PHASE16J_DIAGNOSIS["monitor_alerts_active"]
        severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16J_DIAGNOSIS["runtime_not_ready"]
        severity = "HOLD" if not br_connected else "NO_GO"
    elif not safety_locked:
        diagnosis = _PHASE16J_DIAGNOSIS["safety_not_locked"]
        severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16J_DIAGNOSIS["autonomy_not_level1"]
        severity = "NO_GO"
    elif not gs_assessment["guard_state_clean"]:
        diagnosis = _PHASE16J_DIAGNOSIS["guard_state_not_clean"]
        severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16J_DIAGNOSIS["doctor_not_acceptable"]
        severity = "NO_GO"
    elif not kpi_acceptable_hold:
        diagnosis = _PHASE16J_DIAGNOSIS["kpi_not_acceptable"]
        severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16J_DIAGNOSIS["policy_boundary_missing"]
        severity = "NO_GO"
    elif not clean_cycles_matches_kpi:
        diagnosis = _PHASE16J_DIAGNOSIS["clean_cycles_mismatch"]
        severity = "NO_GO"
    elif has_executable:
        diagnosis = _PHASE16J_DIAGNOSIS["executable_item_present"]
        severity = "NO_GO"
    elif has_broker_order:
        diagnosis = _PHASE16J_DIAGNOSIS["broker_order_created"]
        severity = "NO_GO"
    elif rejected_or_deferred_in_draft:
        diagnosis = _PHASE16J_DIAGNOSIS["executable_item_present"]
        severity = "NO_GO"
    else:
        diagnosis = _PHASE16J_DIAGNOSIS["ready"]
        severity = "OK"

    drill_ok = diagnosis == _PHASE16J_DIAGNOSIS["ready"]
    operator_action_required = not drill_ok
    suggested_actions: list[str] = []
    if not drill_ok:
        suggested_actions.append(f"Order-plan draft drill blocked: {diagnosis}")
        if not run_time_ready:
            suggested_actions.append("Ensure bridge is connected in paper read-only mode")
        if not safety_locked:
            suggested_actions.append("Verify all safety locks are engaged")
        if not gs_assessment["guard_state_clean"]:
            suggested_actions.append("Run guard-state-reconcile to fix guard state")

    # ------------------------------------------------------------------
    # 12. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "draft_items_count": len(draft_items),
        "accepted_from_decisions": len(all_accepted),
        "has_executable": has_executable,
        "has_broker_order": has_broker_order,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 13. Assemble result
    # ------------------------------------------------------------------
    result: dict[str, Any] = {
        "command": "ibkr-operator level1-order-plan-draft-drill",
        "advisory": (
            "Read-only Level 1 order-plan draft drill (Phase 16J). "
            "Converts accepted audit-only review decisions into a non-executable "
            "order-plan draft artifact. No orders. No mutations. No H1 token. "
            "No broker activity. No autonomy level change."
        ),
        "timestamp": ts_str,
        "drill_id": drill_id,
        "diagnosis": diagnosis,
        "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": runtime_section,
        "autonomy": autonomy_section,
        "safety": safety_section,
        "guard_state": guard_section,
        "input_decision_artifact": input_decision_artifact,
        "order_plan_draft": order_plan_draft,
        "plan_artifact": plan_artifact,
        "plan_artifact_hash": plan_artifact_hash,
        "plan_workflow": plan_workflow,
        "workflow_summary": workflow_summary,
        "kpi_summary": kpi_section,
        "doctor_summary": doctor_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16J_EXPLICIT_NON_ACTIONS,
    }

    # ------------------------------------------------------------------
    # 14. Export artifacts
    # ------------------------------------------------------------------
    export_path: str | None = None
    plan_artifact_path: str | None = None
    order_plan_path: str | None = None
    try:
        _PHASE16J_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        ep = _PHASE16J_EXPORT_DIR / f"{drill_id}.json"
        with open(ep, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str)
        export_path = str(ep)
        pa_path = _PHASE16J_EXPORT_DIR / f"{plan_id}.json"
        with open(pa_path, "w", encoding="utf-8") as f:
            _json.dump(plan_artifact, f, indent=2, default=str)
        plan_artifact_path = str(pa_path)
        order_plan_path = str(pa_path)  # alias for clarity
    except Exception:
        pass

    result["export_path"] = export_path
    result["plan_artifact_path"] = plan_artifact_path
    result["order_plan_path"] = order_plan_path
    result["order_plan_hash"] = plan_artifact_hash
    result["plan_artifact_path"] = plan_artifact_path
    return result


def _phase16j_no_go(
    drill_id: str, ts_str: str, git_section: dict, required_tags: dict,
    diagnosis: str, actions: list,
) -> dict:
    """Build a NO_GO result for early-exit prerequisite failures."""
    from trading_agent.cli.operator_common import _PHASE16J_EXPLICIT_NON_ACTIONS
    from trading_agent.cli.operator_workflow_helpers import _compute_evidence_hash
    empty_plan = {"plan_id": drill_id, "status": "blocked", "draft_items": [], "skipped_items": []}
    empty_pa = {"artifact_id": drill_id, "status": "blocked"}
    return {
        "command": "ibkr-operator level1-order-plan-draft-drill",
        "timestamp": ts_str,
        "drill_id": drill_id,
        "diagnosis": diagnosis,
        "severity": "NO_GO",
        "operator_action_required": True,
        "suggested_operator_actions": actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": {},
        "autonomy": {},
        "safety": {},
        "guard_state": {},
        "input_decision_artifact": {},
        "order_plan_draft": empty_plan,
        "plan_artifact": empty_pa,
        "plan_artifact_hash": _compute_evidence_hash(empty_pa),
        "order_plan_path": None,
        "order_plan_hash": _compute_evidence_hash(empty_pa),
        "plan_workflow": {},
        "workflow_summary": {},
        "kpi_summary": {},
        "doctor_summary": {},
        "policy_summary": {},
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "evidence_hash": _compute_evidence_hash({"diagnosis": diagnosis}),
        "explicit_non_actions": _PHASE16J_EXPLICIT_NON_ACTIONS,
    }


def _run_level1_preflight_simulation_dossier(
    demo_candidates: int = 3,
    decision_mode: str = "mixed_demo",
    order_plan_path: str | None = None,
    simulation_source: str = "synthetic_readonly_demo",
) -> dict:
    """Run Level 1 preflight simulation dossier drill (Phase 16K).

    Read-only drill that transforms a non-executable order-plan draft into a
    simulated preflight dossier.  /order/preflight is NEVER called.  Every
    dossier item is tagged simulated_preflight_only=true.
    """
    from trading_agent.cli.operator_common import BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _DECISION_LOGIC, _DECISION_MODE_VALUES, _DECISION_RATIONALE_TEMPLATES, _PHASE16K_DIAGNOSIS, _PHASE16K_EXPLICIT_NON_ACTIONS, _PHASE16K_EXPORT_DIR, _PHASE16K_REQUIRED_TAGS, _REVIEW_CANDIDATE_POOL, _SIMULATION_DOSSIER_ITEM_TEMPLATE, _git_metadata, _read_env_safety, _read_rules_enforced
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone
    from typing import Any

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    ts_file = now_utc.strftime("%Y%m%dT%H%M%SZ")
    dossier_id = f"preflight-simulation-dossier-{ts_file}"
    effective_candidates = max(0, min(demo_candidates, 5))
    if decision_mode not in _DECISION_MODE_VALUES:
        decision_mode = "mixed_demo"

    # ------------------------------------------------------------------
    # 1. Git / worktree
    # ------------------------------------------------------------------
    git_cfg = _git_metadata(BRIDGE_DIR)
    full_commit = git_cfg.get("commit_short", "?")
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "rev-parse", "HEAD"],
            capture_output=True, text=True, timeout=5,
        encoding="utf-8")
        if p.stdout.strip():
            full_commit = p.stdout.strip()
    except Exception:
        pass

    worktree = _get_worktree_state(BRIDGE_DIR)
    origin_alignment = _get_origin_master_alignment(BRIDGE_DIR)

    git_section = {
        "branch": git_cfg.get("branch", "?"),
        "commit": full_commit if len(full_commit) > 16 else git_cfg.get("commit_short", "?"),
        "commit_short": git_cfg.get("commit_short", "?"),
        "tag": git_cfg.get("tag", "?"),
        "origin_master_commit": origin_alignment.get("origin_master_commit", "?"),
        "origin_master_aligned": origin_alignment.get("aligned"),
        "worktree_clean": worktree.get("clean"),
        "dirty_files": worktree.get("dirty_files", []),
    }

    # ------------------------------------------------------------------
    # 2. Required tags
    # ------------------------------------------------------------------
    required_tags_present: list[str] = []
    required_tags_missing: list[str] = []
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "tag"],
            capture_output=True, text=True, timeout=10,
        encoding="utf-8")
        all_tags = set(p.stdout.strip().splitlines())
        for tag in _PHASE16K_REQUIRED_TAGS:
            if tag in all_tags:
                required_tags_present.append(tag)
            else:
                required_tags_missing.append(tag)
    except Exception:
        required_tags_missing = list(_PHASE16K_REQUIRED_TAGS)
        required_tags_present = []

    required_tags = {
        "required_count": len(_PHASE16K_REQUIRED_TAGS),
        "present_count": len(required_tags_present),
        "missing": required_tags_missing,
        "present": required_tags_present,
    }

    if len(required_tags_missing) > 0:
        return _phase16k_no_go(
            dossier_id, ts_str, git_section, required_tags,
            _PHASE16K_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags_missing)}"],
        )

    if not git_section.get("worktree_clean", False) and git_section.get("worktree_clean") is not None:
        return _phase16k_no_go(
            dossier_id, ts_str, git_section, required_tags,
            _PHASE16K_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
        )

    # ------------------------------------------------------------------
    # 3. Bridge runtime
    # ------------------------------------------------------------------
    br_reachable = False
    br_connected = False
    br_mode = "?"
    br_read_only = False
    ep_ok = 0
    ep_display = "?"
    try:
        req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
        with urllib.request.urlopen(req, timeout=8) as resp:
            if resp.status == 200:
                br_reachable = True
                hd = _json.loads(resp.read().decode())
                br_connected = hd.get("connected", False)
                br_mode = hd.get("mode", "?")
                br_read_only = br_mode == "paper"
    except Exception:
        pass

    snapshot_used = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    snapshot_used = True
                    ep_ok = 7
                    ep_display = f"{ep_ok}/7 OK (snapshot)"
        except Exception:
            pass

    if not snapshot_used and br_reachable:
        _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                "/monitor/alerts", "/monitor/events", "/positions", "/account"]
        for ep in _EPS:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        ep_ok += 1
            except Exception:
                pass
        ep_display = f"{ep_ok}/{len(_EPS)} OK"

    positions_count = 0
    positions_flat = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    pd = _json.loads(resp.read().decode())
                    pl = pd.get("positions", [])
                    positions_count = len(pl)
                    positions_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
        except Exception:
            pass

    active_alerts_count = 0
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    ad = _json.loads(resp.read().decode())
                    all_a = ad.get("alerts", [])
                    active_alerts_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
        except Exception:
            pass

    runtime_section = {
        "bridge_reachable": br_reachable,
        "bridge_connected": br_connected,
        "mode": br_mode,
        "read_only": br_read_only,
        "endpoints_display": ep_display,
        "endpoints_ok": ep_ok,
        "positions_count": positions_count,
        "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
    }

    # ------------------------------------------------------------------
    # 4. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")
    system_locked = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status == 200:
                    rd = _json.loads(resp.read().decode())
                    system_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
        except Exception:
            pass

    safety_section = {
        "env_IBKR_ALLOW_ORDERS": env_allow_orders,
        "rules_enforced": rules_enforced,
        "system_locked": system_locked,
    }

    # ------------------------------------------------------------------
    # 5. Guard state — centralized assessor
    # ------------------------------------------------------------------
    gs_assessment = _assess_guard_state_cleanliness(now_utc)
    guard_section = gs_assessment["guard_section"]

    # ------------------------------------------------------------------
    # 6. Doctor / KPI / Policy
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    doc_acceptable = False
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0)
        doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False)
        doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (
            doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1
        )
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status,
            "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}
    kpi_acceptable_hold = False
    kpi_clean_cycles: int | None = None
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") == "system_locked"
                    for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        au = kpi_result.get("autonomy", {})
        if isinstance(au, dict):
            kpi_clean_cycles = au.get("clean_cycles")
            if kpi_clean_cycles is None:
                kpi_clean_cycles = kpi_result.get("clean_cycles")
        if kpi_clean_cycles is None:
            kpi_clean_cycles = kpi_result.get("clean_cycles")
        kpi_section = {
            "verdict": kpi_verdict,
            "blockers": [b.get("check", "?") for b in kpi_blockers],
            "acceptable_hold": kpi_acceptable_hold,
        }
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {
        "hermes_policy_exists": policy_result["hermes_policy_exists"],
        "advisory_boundary_ok": policy_result["advisory_boundary_ok"],
        "execution_path_ok": policy_result["execution_path_ok"],
    }

    # ------------------------------------------------------------------
    # 7. Clean-cycles
    # ------------------------------------------------------------------
    canonical_ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
    clean_cycles_source = "openclaw_clean_cycle_ledger"
    drill_clean_cycles: int | None = None
    try:
        if canonical_ledger_path.exists():
            drill_clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
    except Exception:
        drill_clean_cycles = None

    clean_cycles_matches_kpi = False
    if kpi_clean_cycles is not None and drill_clean_cycles is not None:
        clean_cycles_matches_kpi = (kpi_clean_cycles == drill_clean_cycles)
    elif kpi_clean_cycles is None and drill_clean_cycles is None:
        clean_cycles_matches_kpi = True

    autonomy_section = {
        "current_level": autonomy_level,
        "clean_cycles": drill_clean_cycles,
        "clean_cycles_source": clean_cycles_source,
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
    }

    # ------------------------------------------------------------------
    # 8. Load or synthesize order-plan draft
    # ------------------------------------------------------------------
    order_plan_source = "synthesized_internally"
    order_plan_path_actual: str | None = None
    draft_items: list[dict[str, Any]] = []
    plan_id = "synthetic-plan"
    op_status = "draft_only"
    op_executable = False
    op_has_broker_orders = False
    op_artifact_hash = ""

    if order_plan_path:
        op_path_obj = Path(order_plan_path)
        if not op_path_obj.exists() or not op_path_obj.is_file():
            return _phase16k_no_go(
                dossier_id, ts_str, git_section, required_tags,
                _PHASE16K_DIAGNOSIS["order_plan_not_found"],
                [f"Order-plan artifact not found: {order_plan_path}"],
            )
        try:
            with open(op_path_obj, encoding="utf-8") as f:
                op_loaded = _json.load(f)
        except Exception:
            return _phase16k_no_go(
                dossier_id, ts_str, git_section, required_tags,
                _PHASE16K_DIAGNOSIS["order_plan_not_found"],
                [f"Order-plan artifact unparseable: {order_plan_path}"],
            )
        if op_loaded.get("status") != "draft_only":
            return _phase16k_no_go(
                dossier_id, ts_str, git_section, required_tags,
                _PHASE16K_DIAGNOSIS["order_plan_not_draft_only"],
                [f"Order-plan status is '{op_loaded.get('status')}', not 'draft_only'",
                 "Re-run 16J to generate a valid order-plan draft"],
            )
        order_plan_source = "loaded_from_prior_16j_artifact"
        order_plan_path_actual = str(op_path_obj.resolve())
        plan_id = op_loaded.get("artifact_id", op_loaded.get("plan_id", "loaded-plan"))
        opd = op_loaded.get("order_plan_draft", {})
        op_status = opd.get("status", "draft_only")
        op_executable = opd.get("executable", False)
        op_has_broker_orders = opd.get("broker_order_created", False)
        draft_items = opd.get("draft_items", [])
        op_artifact_hash = _compute_evidence_hash(opd)

    if not draft_items and not order_plan_path:
        # Synthesize internally: build a demo order-plan in memory
        candidate_pool = _REVIEW_CANDIDATE_POOL
        decision_fn = _DECISION_LOGIC.get(decision_mode, _DECISION_LOGIC["mixed_demo"])
        synth_decisions: list[dict[str, Any]] = []
        for i in range(min(effective_candidates, len(candidate_pool))):
            candidate = candidate_pool[i]
            verdict = decision_fn(i, candidate)
            reason = _DECISION_RATIONALE_TEMPLATES.get(verdict, "No decision.")
            synth_decisions.append({
                "proposal_id": f"synth-decision-{dossier_id}-{i+1:03d}",
                "symbol": candidate["symbol"],
                "side": candidate["side"],
                "quantity": (i + 1) * 10,
                "decision": verdict,
                "decision_reason": reason,
                "executable": False,
                "performed": False,
                "requires_chris_approval": True,
            })
        # Only accepted items become draft items
        all_accepted = [d for d in synth_decisions if d.get("decision") == "accept"]
        for i, d in enumerate(all_accepted):
            draft_items.append({
                "plan_item_id": f"draft-{dossier_id}-{i+1:03d}",
                "source_proposal_id": d.get("proposal_id", ""),
                "symbol": d.get("symbol", "?"),
                "side": d.get("side", "?"),
                "quantity": d.get("quantity", 0),
                "order_type": "LMT",
                "time_in_force": "DAY",
                "limit_price": None,
                "rationale": d.get("decision_reason", ""),
                "risk_notes": "Draft item — non-executable.",
                "executable": False,
                "performed": False,
                "broker_order_created": False,
                "broker_order_id": None,
            })
        plan_id = f"synthetic-order-plan-{ts_file}"
        op_status = "draft_only"
        op_executable = False
        op_has_broker_orders = False
        op_artifact_hash = _compute_evidence_hash({"plan_id": plan_id, "draft_items_count": len(draft_items)})

    # Sanity checks on loaded/synthesized items
    draft_items_count = len(draft_items)
    has_executable_in_draft = any(d.get("executable") is True for d in draft_items)
    has_broker_order_in_draft = any(d.get("broker_order_created") is True for d in draft_items)

    input_order_plan = {
        "source": order_plan_source,
        "plan_id": plan_id,
        "order_plan_path": order_plan_path_actual,
        "status": op_status,
        "draft_only": op_status == "draft_only",
        "executable": op_executable,
        "broker_order_created": op_has_broker_orders,
        "requires_future_order_window": True,
        "requires_future_h1": True,
        "requires_future_chris_approval": True,
        "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        "draft_items_count": draft_items_count,
        "artifact_hash": op_artifact_hash,
    }

    # ------------------------------------------------------------------
    # 9. Build preflight simulation dossier — deterministic local sim
    # ------------------------------------------------------------------
    simulation_id = f"preflight-sim-{ts_file}"
    simulated_items: list[dict[str, Any]] = []
    for i, di in enumerate(draft_items):
        sim_item: dict[str, Any] = {
            "simulation_item_id": f"sim-{dossier_id}-{i+1:03d}",
            "source_plan_item_id": di.get("plan_item_id", f"draft-item-{i}"),
            "source_proposal_id": di.get("source_proposal_id", "?"),
            "symbol": di.get("symbol", "?"),
            "side": di.get("side", "?"),
            "quantity": di.get("quantity", 0),
            "order_type": di.get("order_type", "LMT"),
            "time_in_force": di.get("time_in_force", "DAY"),
            "limit_price": di.get("limit_price"),
            "rationale": di.get("rationale", di.get("risk_notes", "")),
            "risk_notes": di.get("risk_notes", di.get("rationale", "Draft item — non-executable. Requires Chris approval before any order path.")),
            **_SIMULATION_DOSSIER_ITEM_TEMPLATE,
        }
        simulated_items.append(sim_item)

    blocked_items_count = 0
    pass_items_count = len(simulated_items)
    warn_items_count = len(simulated_items)  # every simulated item has a warning

    # Build skipped_items from the input order plan (items that were rejected/deferred)
    skipped_items: list[dict[str, Any]] = []
    # If we loaded from a 16J artifact, try to extract skipped items
    if order_plan_path and order_plan_path_actual:
        try:
            opd = op_loaded.get("order_plan_draft", {}) if order_plan_path else {}
            skipped_items = opd.get("skipped_items", [])
        except Exception:
            pass

    preflight_simulation = {
        "simulation_id": simulation_id,
        "status": "simulation_only",
        "simulation_source": simulation_source,
        "simulated_preflight_only": True,
        "real_preflight_performed": False,
        "preflight_endpoint_called": False,
        "broker_validation_performed": False,
        "simulated_items_count": len(simulated_items),
        "blocked_items_count": blocked_items_count,
        "pass_items_count": pass_items_count,
        "warn_items_count": warn_items_count,
        "any_preflight_blockers": False,
        "total_preflight_warnings": len(simulated_items),
        "simulated_items": simulated_items,
        "skipped_items": skipped_items,
    }

    # Dossier artifact (standalone)
    dossier_artifact = {
        "artifact_id": simulation_id,
        "dossier_id": dossier_id,
        "status": "simulation_only",
        "generated_by": "level1-preflight-simulation-dossier (Phase 16K)",
        "input_order_plan": input_order_plan,
        "preflight_simulation": preflight_simulation,
    }
    dossier_artifact_hash = _compute_evidence_hash(dossier_artifact)

    # ------------------------------------------------------------------
    # 10. Simulation workflow
    # ------------------------------------------------------------------
    simulation_workflow = {
        "simulation_only": True,
        "demo_candidates_requested": effective_candidates,
        "draft_items_received": draft_items_count,
        "simulated_items_produced": len(simulated_items),
        "real_preflight_performed": False,
        "preflight_endpoint_called": False,
        "broker_validation_performed": False,
        "any_real_broker_activity": False,
        "all_items_simulated_preflight_only": len(simulated_items) > 0,
        "any_executable_item_simulated": has_executable_in_draft,
        "any_broker_order_in_source": has_broker_order_in_draft,
    }

    workflow_summary = {
        "preflight_simulation_dossier_ready": True,
        "simulation_dossier_created": len(simulated_items) > 0,
        "all_items_simulated_only": True,
        "no_real_preflight_performed": True,
        "no_preflight_endpoint_called": True,
        "no_order_path_called": True,
        "no_broker_validation": True,
        "no_broker_order_created": True,
        "no_broker_submission": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
        "all_items_non_executable": True,
    }

    # ------------------------------------------------------------------
    # 11. Classification
    # ------------------------------------------------------------------
    all_tags_present = len(required_tags_missing) == 0
    worktree_clean = git_section.get("worktree_clean", False)
    run_time_ready = br_connected and br_mode == "paper" and br_read_only
    safety_locked = env_allow_orders in ("false", "?") and rules_enforced in ("false", "?") and system_locked is True

    if not all_tags_present:
        diagnosis = _PHASE16K_DIAGNOSIS["missing_required_tags"]
        severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16K_DIAGNOSIS["dirty_worktree"]
        severity = "NO_GO"
    elif not positions_flat and positions_count > 0:
        diagnosis = _PHASE16K_DIAGNOSIS["positions_not_flat"]
        severity = "NO_GO"
    elif active_alerts_count > 0:
        diagnosis = _PHASE16K_DIAGNOSIS["monitor_alerts_active"]
        severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16K_DIAGNOSIS["runtime_not_ready"]
        severity = "HOLD" if not br_connected else "NO_GO"
    elif not safety_locked:
        diagnosis = _PHASE16K_DIAGNOSIS["safety_not_locked"]
        severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16K_DIAGNOSIS["autonomy_not_level1"]
        severity = "NO_GO"
    elif not gs_assessment["guard_state_clean"]:
        diagnosis = _PHASE16K_DIAGNOSIS["guard_state_not_clean"]
        severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16K_DIAGNOSIS["doctor_not_acceptable"]
        severity = "NO_GO"
    elif not kpi_acceptable_hold:
        diagnosis = _PHASE16K_DIAGNOSIS["kpi_not_acceptable"]
        severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16K_DIAGNOSIS["policy_boundary_missing"]
        severity = "NO_GO"
    elif not clean_cycles_matches_kpi:
        diagnosis = _PHASE16K_DIAGNOSIS["clean_cycles_mismatch"]
        severity = "NO_GO"
    elif has_executable_in_draft:
        diagnosis = _PHASE16K_DIAGNOSIS["order_plan_has_executable_items"]
        severity = "NO_GO"
    elif has_broker_order_in_draft:
        diagnosis = _PHASE16K_DIAGNOSIS["order_plan_has_broker_orders"]
        severity = "NO_GO"
    elif draft_items_count == 0:
        diagnosis = _PHASE16K_DIAGNOSIS["no_draft_items_to_simulate"]
        severity = "OK"  # Empty but still valid
    else:
        diagnosis = _PHASE16K_DIAGNOSIS["ready"]
        severity = "OK"

    drill_ok = diagnosis in (_PHASE16K_DIAGNOSIS["ready"], _PHASE16K_DIAGNOSIS["no_draft_items_to_simulate"])
    operator_action_required = not drill_ok
    suggested_actions: list[str] = []
    if not drill_ok:
        suggested_actions.append(f"Preflight simulation dossier blocked: {diagnosis}")
        if not run_time_ready:
            suggested_actions.append("Ensure bridge is connected in paper read-only mode")
        if not safety_locked:
            suggested_actions.append("Verify all safety locks are engaged")
        if not gs_assessment["guard_state_clean"]:
            suggested_actions.append("Run guard-state-reconcile to fix guard state")

    # ------------------------------------------------------------------
    # 12. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "simulated_items_count": len(simulated_items),
        "draft_items_count": draft_items_count,
        "simulated_preflight_only": True,
        "real_preflight_performed": False,
        "preflight_endpoint_called": False,
        "broker_validation_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 13. Assemble result
    # ------------------------------------------------------------------
    result: dict[str, Any] = {
        "command": "ibkr-operator level1-preflight-simulation-dossier",
        "advisory": (
            "Read-only Level 1 preflight simulation dossier drill (Phase 16K). "
            "Transforms a non-executable order-plan draft into a deterministic "
            "local preflight simulation dossier. /order/preflight is NEVER called. "
            "Every dossier item is tagged simulated_preflight_only=true. "
            "No orders. No mutations. No H1 token. No broker activity. "
            "No autonomy level change."
        ),
        "timestamp": ts_str,
        "dossier_id": dossier_id,
        "diagnosis": diagnosis,
        "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": runtime_section,
        "autonomy": autonomy_section,
        "safety": safety_section,
        "guard_state": guard_section,
        "input_order_plan": input_order_plan,
        "preflight_simulation": preflight_simulation,
        "dossier_artifact": dossier_artifact,
        "dossier_artifact_hash": dossier_artifact_hash,
        "simulation_workflow": simulation_workflow,
        "workflow_summary": workflow_summary,
        "kpi_summary": kpi_section,
        "doctor_summary": doctor_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "no_preflight_endpoint_called": True,
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16K_EXPLICIT_NON_ACTIONS,
    }

    # ------------------------------------------------------------------
    # 14. Export artifacts
    # ------------------------------------------------------------------
    export_path: str | None = None
    dossier_artifact_path: str | None = None
    try:
        _PHASE16K_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        ep = _PHASE16K_EXPORT_DIR / f"{dossier_id}.json"
        with open(ep, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str)
        export_path = str(ep)
        da_path = _PHASE16K_EXPORT_DIR / f"{simulation_id}.json"
        with open(da_path, "w", encoding="utf-8") as f:
            _json.dump(dossier_artifact, f, indent=2, default=str)
        dossier_artifact_path = str(da_path)
    except Exception:
        pass

    result["export_path"] = export_path
    result["dossier_artifact_path"] = dossier_artifact_path
    result["dossier_path"] = dossier_artifact_path
    result["dossier_hash"] = dossier_artifact_hash
    # Also place dossier_path/hash on preflight_simulation for inline access
    preflight_simulation["dossier_path"] = dossier_artifact_path
    preflight_simulation["dossier_hash"] = dossier_artifact_hash
    return result


def _phase16k_no_go(
    dossier_id: str, ts_str: str, git_section: dict, required_tags: dict,
    diagnosis: str, actions: list,
) -> dict:
    """Build a NO_GO result for early-exit prerequisite failures."""
    from trading_agent.cli.operator_common import _PHASE16K_EXPLICIT_NON_ACTIONS
    from trading_agent.cli.operator_workflow_helpers import _compute_evidence_hash
    empty_sim = {"simulation_id": dossier_id, "status": "blocked", "simulated_items": []}
    empty_da = {"artifact_id": dossier_id, "status": "blocked"}
    return {
        "command": "ibkr-operator level1-preflight-simulation-dossier",
        "timestamp": ts_str,
        "dossier_id": dossier_id,
        "diagnosis": diagnosis,
        "severity": "NO_GO",
        "operator_action_required": True,
        "suggested_operator_actions": actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": {},
        "autonomy": {},
        "safety": {},
        "guard_state": {},
        "input_order_plan": {},
        "preflight_simulation": empty_sim,
        "dossier_artifact": empty_da,
        "dossier_artifact_hash": _compute_evidence_hash(empty_da),
        "simulation_workflow": {},
        "workflow_summary": {},
        "kpi_summary": {},
        "doctor_summary": {},
        "policy_summary": {},
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "no_preflight_endpoint_called": True,
        "evidence_hash": _compute_evidence_hash({"diagnosis": diagnosis}),
        "explicit_non_actions": _PHASE16K_EXPLICIT_NON_ACTIONS,
    }


def _run_level1_human_approval_packet_drill(
    demo_candidates: int = 3,
    decision_mode: str = "mixed_demo",
    preflight_dossier_path: str | None = None,
    packet_source: str = "synthetic_readonly_demo",
    reviewer: str = "Chris",
) -> dict:
    """Run Level 1 human approval packet drill (Phase 16L).

    Read-only drill that converts a simulated preflight dossier into a
    Chris-facing human approval packet.  /order/approve is NEVER called.
    Every packet item is tagged human_packet_only=true.
    """
    from trading_agent.cli.operator_common import BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _DECISION_LOGIC, _DECISION_MODE_VALUES, _DECISION_RATIONALE_TEMPLATES, _PACKET_ITEM_TEMPLATE, _PHASE16L_DIAGNOSIS, _PHASE16L_EXPLICIT_NON_ACTIONS, _PHASE16L_EXPORT_DIR, _PHASE16L_REQUIRED_TAGS, _REVIEW_CANDIDATE_POOL, _git_metadata, _read_env_safety, _read_rules_enforced
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone
    from typing import Any

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    ts_file = now_utc.strftime("%Y%m%dT%H%M%SZ")
    packet_id = f"human-approval-packet-{ts_file}"
    effective_candidates = max(0, min(demo_candidates, 5))
    if decision_mode not in _DECISION_MODE_VALUES:
        decision_mode = "mixed_demo"

    # ------------------------------------------------------------------
    # 1. Git / worktree
    # ------------------------------------------------------------------
    git_cfg = _git_metadata(BRIDGE_DIR)
    full_commit = git_cfg.get("commit_short", "?")
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "rev-parse", "HEAD"],
            capture_output=True, text=True, timeout=5,
        encoding="utf-8")
        if p.stdout.strip():
            full_commit = p.stdout.strip()
    except Exception:
        pass

    worktree = _get_worktree_state(BRIDGE_DIR)
    origin_alignment = _get_origin_master_alignment(BRIDGE_DIR)

    git_section = {
        "branch": git_cfg.get("branch", "?"),
        "commit": full_commit if len(full_commit) > 16 else git_cfg.get("commit_short", "?"),
        "commit_short": git_cfg.get("commit_short", "?"),
        "tag": git_cfg.get("tag", "?"),
        "origin_master_commit": origin_alignment.get("origin_master_commit", "?"),
        "origin_master_aligned": origin_alignment.get("aligned"),
        "worktree_clean": worktree.get("clean"),
        "dirty_files": worktree.get("dirty_files", []),
    }

    # ------------------------------------------------------------------
    # 2. Required tags
    # ------------------------------------------------------------------
    required_tags_present: list[str] = []
    required_tags_missing: list[str] = []
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "tag"],
            capture_output=True, text=True, timeout=10,
        encoding="utf-8")
        all_tags = set(p.stdout.strip().splitlines())
        for tag in _PHASE16L_REQUIRED_TAGS:
            if tag in all_tags:
                required_tags_present.append(tag)
            else:
                required_tags_missing.append(tag)
    except Exception:
        required_tags_missing = list(_PHASE16L_REQUIRED_TAGS)
        required_tags_present = []

    required_tags = {
        "required_count": len(_PHASE16L_REQUIRED_TAGS),
        "present_count": len(required_tags_present),
        "missing": required_tags_missing,
        "present": required_tags_present,
    }

    if len(required_tags_missing) > 0:
        return _phase16l_no_go(
            packet_id, ts_str, git_section, required_tags,
            _PHASE16L_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags_missing)}"],
        )

    if not git_section.get("worktree_clean", False) and git_section.get("worktree_clean") is not None:
        return _phase16l_no_go(
            packet_id, ts_str, git_section, required_tags,
            _PHASE16L_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
        )

    # ------------------------------------------------------------------
    # 3. Bridge runtime
    # ------------------------------------------------------------------
    br_reachable = False
    br_connected = False
    br_mode = "?"
    br_read_only = False
    ep_ok = 0
    ep_display = "?"
    try:
        req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
        with urllib.request.urlopen(req, timeout=8) as resp:
            if resp.status == 200:
                br_reachable = True
                hd = _json.loads(resp.read().decode())
                br_connected = hd.get("connected", False)
                br_mode = hd.get("mode", "?")
                br_read_only = br_mode == "paper"
    except Exception:
        pass

    snapshot_used = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    snapshot_used = True
                    ep_ok = 7
                    ep_display = f"{ep_ok}/7 OK (snapshot)"
        except Exception:
            pass

    if not snapshot_used and br_reachable:
        _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                "/monitor/alerts", "/monitor/events", "/positions", "/account"]
        for ep in _EPS:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        ep_ok += 1
            except Exception:
                pass
        ep_display = f"{ep_ok}/{len(_EPS)} OK"

    positions_count = 0
    positions_flat = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    pd = _json.loads(resp.read().decode())
                    pl = pd.get("positions", [])
                    positions_count = len(pl)
                    positions_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
        except Exception:
            pass

    active_alerts_count = 0
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    ad = _json.loads(resp.read().decode())
                    all_a = ad.get("alerts", [])
                    active_alerts_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
        except Exception:
            pass

    runtime_section = {
        "bridge_reachable": br_reachable,
        "bridge_connected": br_connected,
        "mode": br_mode,
        "read_only": br_read_only,
        "endpoints_display": ep_display,
        "endpoints_ok": ep_ok,
        "positions_count": positions_count,
        "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
    }

    # ------------------------------------------------------------------
    # 4. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")
    system_locked = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status == 200:
                    rd = _json.loads(resp.read().decode())
                    system_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
        except Exception:
            pass

    safety_section = {
        "env_IBKR_ALLOW_ORDERS": env_allow_orders,
        "rules_enforced": rules_enforced,
        "system_locked": system_locked,
    }

    # ------------------------------------------------------------------
    # 5. Guard state
    # ------------------------------------------------------------------
    gs_assessment = _assess_guard_state_cleanliness(now_utc)
    guard_section = gs_assessment["guard_section"]

    # ------------------------------------------------------------------
    # 6. Doctor / KPI / Policy
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    doc_acceptable = False
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0)
        doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False)
        doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (
            doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1
        )
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status,
            "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}
    kpi_acceptable_hold = False
    kpi_clean_cycles: int | None = None
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") == "system_locked"
                    for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        au = kpi_result.get("autonomy", {})
        if isinstance(au, dict):
            kpi_clean_cycles = au.get("clean_cycles")
            if kpi_clean_cycles is None:
                kpi_clean_cycles = kpi_result.get("clean_cycles")
        if kpi_clean_cycles is None:
            kpi_clean_cycles = kpi_result.get("clean_cycles")
        kpi_section = {
            "verdict": kpi_verdict,
            "blockers": [b.get("check", "?") for b in kpi_blockers],
            "acceptable_hold": kpi_acceptable_hold,
        }
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {
        "hermes_policy_exists": policy_result["hermes_policy_exists"],
        "advisory_boundary_ok": policy_result["advisory_boundary_ok"],
        "execution_path_ok": policy_result["execution_path_ok"],
    }

    # ------------------------------------------------------------------
    # 7. Clean-cycles
    # ------------------------------------------------------------------
    canonical_ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
    clean_cycles_source = "openclaw_clean_cycle_ledger"
    drill_clean_cycles: int | None = None
    try:
        if canonical_ledger_path.exists():
            drill_clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
    except Exception:
        drill_clean_cycles = None

    clean_cycles_matches_kpi = False
    if kpi_clean_cycles is not None and drill_clean_cycles is not None:
        clean_cycles_matches_kpi = (kpi_clean_cycles == drill_clean_cycles)
    elif kpi_clean_cycles is None and drill_clean_cycles is None:
        clean_cycles_matches_kpi = True

    autonomy_section = {
        "current_level": autonomy_level,
        "clean_cycles": drill_clean_cycles,
        "clean_cycles_source": clean_cycles_source,
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
    }

    # ------------------------------------------------------------------
    # 8. Load or synthesize preflight dossier
    # ------------------------------------------------------------------
    dossier_source = "synthesized_internally"
    dossier_path_actual: str | None = None
    simulated_items: list[dict[str, Any]] = []
    dossier_id_input = "synthetic-dossier"
    dossier_status = "simulation_only"
    dossier_sim_only = True
    dossier_real_pf = False
    dossier_endpoint_called = False
    dossier_artifact_hash = ""

    if preflight_dossier_path:
        dp_path_obj = Path(preflight_dossier_path)
        if not dp_path_obj.exists() or not dp_path_obj.is_file():
            return _phase16l_no_go(
                packet_id, ts_str, git_section, required_tags,
                _PHASE16L_DIAGNOSIS["dossier_not_found"],
                [f"Preflight dossier not found: {preflight_dossier_path}"],
            )
        try:
            with open(dp_path_obj, encoding="utf-8") as f:
                ds_loaded = _json.load(f)
        except Exception:
            return _phase16l_no_go(
                packet_id, ts_str, git_section, required_tags,
                _PHASE16L_DIAGNOSIS["dossier_not_found"],
                [f"Preflight dossier unparseable: {preflight_dossier_path}"],
            )
        if ds_loaded.get("status") != "simulation_only":
            return _phase16l_no_go(
                packet_id, ts_str, git_section, required_tags,
                _PHASE16L_DIAGNOSIS["dossier_not_simulation_only"],
                [f"Dossier status is '{ds_loaded.get('status')}', not 'simulation_only'",
                 "Re-run 16K to generate a valid simulation dossier"],
            )
        dossier_source = "loaded_from_prior_16k_artifact"
        dossier_path_actual = str(dp_path_obj.resolve())
        dossier_id_input = ds_loaded.get("artifact_id", ds_loaded.get("dossier_id", "loaded-dossier"))
        ps = ds_loaded.get("preflight_simulation", {})
        dossier_status = ps.get("status", "simulation_only")
        dossier_sim_only = ps.get("simulated_preflight_only", True)
        dossier_real_pf = ps.get("real_preflight_performed", False)
        dossier_endpoint_called = ps.get("preflight_endpoint_called", False)
        simulated_items = ps.get("simulated_items", [])
        dossier_artifact_hash = _compute_evidence_hash(ps)

    if not simulated_items and not preflight_dossier_path:
        # Synthesize internally: build a demo preflight dossier in memory
        candidate_pool = _REVIEW_CANDIDATE_POOL
        decision_fn = _DECISION_LOGIC.get(decision_mode, _DECISION_LOGIC["mixed_demo"])
        for i in range(min(effective_candidates, len(candidate_pool))):
            candidate = candidate_pool[i]
            verdict = decision_fn(i, candidate)
            if verdict != "accept":
                continue
            reason = _DECISION_RATIONALE_TEMPLATES.get(verdict, "No decision.")
            simulated_items.append({
                "simulation_item_id": f"sim-synth-{packet_id}-{i+1:03d}",
                "source_plan_item_id": f"draft-synth-{packet_id}-{i+1:03d}",
                "source_proposal_id": f"synth-proposal-{i+1:03d}",
                "symbol": candidate["symbol"],
                "side": candidate["side"],
                "quantity": (i + 1) * 10,
                "order_type": "LMT",
                "time_in_force": "DAY",
                "limit_price": None,
                "rationale": reason,
                "risk_notes": "Synthesized demo — non-executable.",
                "simulated_preflight_only": True,
                "real_preflight_performed": False,
                "simulated_preflight_status": "PASS (simulated)",
                "simulated_checks": [
                    {"check": "margin", "status": "PASS", "detail": "Deterministic local simulation"},
                    {"check": "contract", "status": "PASS", "detail": "Deterministic local simulation"},
                    {"check": "risk", "status": "PASS", "detail": "Deterministic local simulation"},
                    {"check": "compliance", "status": "PASS", "detail": "Deterministic local simulation"},
                ],
                "executable": False,
            })
        dossier_id_input = f"synthetic-dossier-{ts_file}"
        dossier_status = "simulation_only"
        dossier_sim_only = True
        dossier_real_pf = False
        dossier_endpoint_called = False
        dossier_artifact_hash = _compute_evidence_hash({"dossier_id": dossier_id_input, "simulated_items_count": len(simulated_items)})

    simulated_items_count = len(simulated_items)
    has_real_pf_in_dossier = dossier_real_pf is True
    has_executable_in_dossier = any(s.get("executable") is True for s in simulated_items)

    input_preflight_dossier = {
        "source": dossier_source,
        "dossier_id": dossier_id_input,
        "preflight_dossier_path": dossier_path_actual,
        "status": dossier_status,
        "simulation_only": dossier_sim_only,
        "simulated_preflight_only": dossier_sim_only,
        "real_preflight_performed": dossier_real_pf,
        "preflight_endpoint_called": dossier_endpoint_called,
        "simulated_items_count": simulated_items_count,
        "artifact_hash": dossier_artifact_hash,
    }

    # ------------------------------------------------------------------
    # 9. Build human approval packet
    # ------------------------------------------------------------------
    packet_items: list[dict[str, Any]] = []
    for i, si in enumerate(simulated_items):
        pi: dict[str, Any] = {
            "packet_item_id": f"packet-{packet_id}-{i+1:03d}",
            "source_simulation_item_id": si.get("simulation_item_id", f"sim-item-{i}"),
            "source_plan_item_id": si.get("source_plan_item_id", "?"),
            "source_proposal_id": si.get("source_proposal_id", "?"),
            "source_dossier_id": dossier_id_input,
            "symbol": si.get("symbol", "?"),
            "side": si.get("side", "?"),
            "quantity": si.get("quantity", 0),
            "order_type": si.get("order_type", "LMT"),
            "time_in_force": si.get("time_in_force", "DAY"),
            "limit_price": si.get("limit_price"),
            "simulated_preflight_status": si.get("simulated_preflight_status", "PASS (simulated)"),
            "approval_question": f"Do you approve {si.get('symbol', '?')} {si.get('side', '?')} x{si.get('quantity', 0)} at Level 1?",
            "operator_notes": f"Simulated preflight passed for {si.get('symbol', '?')}. Requires Chris manual approval before any order path.",
            "rationale": si.get("rationale", ""),
            "risk_notes": si.get("risk_notes", "Requires Chris approval before any order path."),
            **_PACKET_ITEM_TEMPLATE,
        }
        packet_items.append(pi)

    # Build skipped_items from input dossier — items not simulated
    skipped_items: list[dict[str, Any]] = []
    if preflight_dossier_path and dossier_path_actual:
        try:
            ps = ds_loaded.get("preflight_simulation", {}) if preflight_dossier_path else {}
            skipped_items = ps.get("skipped_items", [])
        except Exception:
            pass

    approval_packet_id = f"approval-packet-{ts_file}"
    human_approval_packet = {
        "packet_id": approval_packet_id,
        "status": "packet_only",
        "packet_source": packet_source,
        "reviewer": reviewer,
        "human_packet_only": True,
        "broker_approval_performed": False,
        "approval_endpoint_called": False,
        "h1_token_used": False,
        "executable": False,
        "requires_future_order_window": True,
        "requires_future_h1": True,
        "requires_future_chris_approval": True,
        "future_real_preflight_required": True,
        "future_real_approval_required": True,
        "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        "packet_items_count": len(packet_items),
        "blocked_items_count": 0,
        "approval_packet_path": None,
        "approval_packet_hash": None,
        "signature_required": True,
        "packet_items": packet_items,
        "skipped_items": skipped_items,
        "approval_checklist": {
            "confirms_level1_only": True,
            "confirms_packet_only": True,
            "confirms_not_broker_approval": True,
            "confirms_orders_disabled": True,
            "confirms_system_locked": True,
            "confirms_no_h1_used": True,
            "confirms_no_order_window_opened": True,
            "confirms_no_approval_endpoint_called": True,
            "confirms_no_submit_endpoint_called": True,
            "confirms_no_broker_order_created": True,
            "confirms_future_real_preflight_required": True,
            "confirms_future_h1_required": True,
            "confirms_future_order_window_required": True,
            "requires_chris_accept_or_reject": True,
        },
    }

    # Packet artifact (standalone)
    packet_artifact = {
        "artifact_id": approval_packet_id,
        "packet_id": packet_id,
        "status": "packet_only",
        "generated_by": "level1-human-approval-packet-drill (Phase 16L)",
        "input_preflight_dossier": input_preflight_dossier,
        "human_approval_packet": human_approval_packet,
    }
    packet_artifact_hash = _compute_evidence_hash(packet_artifact)

    # ------------------------------------------------------------------
    # 10. Approval workflow
    # ------------------------------------------------------------------
    approval_workflow = {
        "human_packet_only": True,
        "demo_candidates_requested": effective_candidates,
        "simulated_items_received": simulated_items_count,
        "packet_items_produced": len(packet_items),
        "broker_approval_performed": False,
        "approval_endpoint_called": False,
        "h1_token_used": False,
        "any_real_broker_activity": False,
        "all_items_packet_only": len(packet_items) > 0,
        "any_executable_item": has_executable_in_dossier,
    }

    workflow_summary = {
        "human_approval_packet_ready": True,
        "approval_packet_created": len(packet_items) > 0,
        "all_items_packet_only": True,
        "all_items_non_executable": True,
        "no_real_preflight_performed": True,
        "no_approval_endpoint_called": True,
        "no_order_path_called": True,
        "no_broker_approval": True,
        "no_broker_order_created": True,
        "no_broker_submission": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
        "checklist_complete": True,
    }

    # ------------------------------------------------------------------
    # 11. Classification
    # ------------------------------------------------------------------
    all_tags_present = len(required_tags_missing) == 0
    worktree_clean = git_section.get("worktree_clean", False)
    run_time_ready = br_connected and br_mode == "paper" and br_read_only
    safety_locked = env_allow_orders in ("false", "?") and rules_enforced in ("false", "?") and system_locked is True

    if not all_tags_present:
        diagnosis = _PHASE16L_DIAGNOSIS["missing_required_tags"]
        severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16L_DIAGNOSIS["dirty_worktree"]
        severity = "NO_GO"
    elif not positions_flat and positions_count > 0:
        diagnosis = _PHASE16L_DIAGNOSIS["positions_not_flat"]
        severity = "NO_GO"
    elif active_alerts_count > 0:
        diagnosis = _PHASE16L_DIAGNOSIS["monitor_alerts_active"]
        severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16L_DIAGNOSIS["runtime_not_ready"]
        severity = "HOLD" if not br_connected else "NO_GO"
    elif not safety_locked:
        diagnosis = _PHASE16L_DIAGNOSIS["safety_not_locked"]
        severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16L_DIAGNOSIS["autonomy_not_level1"]
        severity = "NO_GO"
    elif not gs_assessment["guard_state_clean"]:
        diagnosis = _PHASE16L_DIAGNOSIS["guard_state_not_clean"]
        severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16L_DIAGNOSIS["doctor_not_acceptable"]
        severity = "NO_GO"
    elif not kpi_acceptable_hold:
        diagnosis = _PHASE16L_DIAGNOSIS["kpi_not_acceptable"]
        severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16L_DIAGNOSIS["policy_boundary_missing"]
        severity = "NO_GO"
    elif not clean_cycles_matches_kpi:
        diagnosis = _PHASE16L_DIAGNOSIS["clean_cycles_mismatch"]
        severity = "NO_GO"
    elif has_executable_in_dossier:
        diagnosis = _PHASE16L_DIAGNOSIS["dossier_has_executable_items"]
        severity = "NO_GO"
    elif has_real_pf_in_dossier:
        diagnosis = _PHASE16L_DIAGNOSIS["dossier_has_real_preflight"]
        severity = "NO_GO"
    elif dossier_endpoint_called:
        diagnosis = _PHASE16L_DIAGNOSIS["dossier_has_real_preflight"]
        severity = "NO_GO"
    elif simulated_items_count == 0:
        diagnosis = _PHASE16L_DIAGNOSIS["no_items_to_approve"]
        severity = "OK"
    else:
        diagnosis = _PHASE16L_DIAGNOSIS["ready"]
        severity = "OK"

    drill_ok = diagnosis in (_PHASE16L_DIAGNOSIS["ready"], _PHASE16L_DIAGNOSIS["no_items_to_approve"])
    operator_action_required = not drill_ok
    suggested_actions: list[str] = []
    if not drill_ok:
        suggested_actions.append(f"Human approval packet drill blocked: {diagnosis}")
        if not run_time_ready:
            suggested_actions.append("Ensure bridge is connected in paper read-only mode")
        if not safety_locked:
            suggested_actions.append("Verify all safety locks are engaged")
        if not gs_assessment["guard_state_clean"]:
            suggested_actions.append("Run guard-state-reconcile to fix guard state")

    # ------------------------------------------------------------------
    # 12. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "packet_items_count": len(packet_items),
        "human_packet_only": True,
        "broker_approval_performed": False,
        "approval_endpoint_called": False,
        "h1_token_used": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 13. Assemble result
    # ------------------------------------------------------------------
    result: dict[str, Any] = {
        "command": "ibkr-operator level1-human-approval-packet-drill",
        "advisory": (
            "Read-only Level 1 human approval packet drill (Phase 16L). "
            "Converts a simulated preflight dossier into a Chris-facing "
            "human approval packet. /order/approve is NEVER called. "
            "Every packet item is tagged human_packet_only=true. "
            "No orders. No mutations. No H1 token. No broker activity. "
            "No autonomy level change. Chris must manually sign and approve."
        ),
        "timestamp": ts_str,
        "packet_id": packet_id,
        "diagnosis": diagnosis,
        "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": runtime_section,
        "autonomy": autonomy_section,
        "safety": safety_section,
        "guard_state": guard_section,
        "input_preflight_dossier": input_preflight_dossier,
        "human_approval_packet": human_approval_packet,
        "packet_artifact": packet_artifact,
        "packet_artifact_hash": packet_artifact_hash,
        "approval_workflow": approval_workflow,
        "workflow_summary": workflow_summary,
        "kpi_summary": kpi_section,
        "doctor_summary": doctor_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "no_approval_endpoint_called": True,
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16L_EXPLICIT_NON_ACTIONS,
    }

    # ------------------------------------------------------------------
    # 14. Export artifacts
    # ------------------------------------------------------------------
    export_path: str | None = None
    packet_artifact_path: str | None = None
    try:
        _PHASE16L_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        ep = _PHASE16L_EXPORT_DIR / f"{packet_id}.json"
        with open(ep, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str)
        export_path = str(ep)
        pa_path = _PHASE16L_EXPORT_DIR / f"{approval_packet_id}.json"
        with open(pa_path, "w", encoding="utf-8") as f:
            _json.dump(packet_artifact, f, indent=2, default=str)
        packet_artifact_path = str(pa_path)
    except Exception:
        pass

    result["export_path"] = export_path
    result["packet_artifact_path"] = packet_artifact_path
    result["packet_path"] = packet_artifact_path
    result["packet_hash"] = packet_artifact_hash
    # Also place on human_approval_packet for inline access
    human_approval_packet["approval_packet_path"] = packet_artifact_path
    human_approval_packet["approval_packet_hash"] = packet_artifact_hash
    return result


def _phase16l_no_go(
    packet_id: str, ts_str: str, git_section: dict, required_tags: dict,
    diagnosis: str, actions: list,
) -> dict:
    """Build a NO_GO result for early-exit prerequisite failures."""
    from trading_agent.cli.operator_common import _PHASE16L_EXPLICIT_NON_ACTIONS
    from trading_agent.cli.operator_workflow_helpers import _compute_evidence_hash
    empty_pkt = {"packet_id": packet_id, "status": "blocked", "packet_items": [], "skipped_items": [], "approval_checklist": {}}
    empty_pa = {"artifact_id": packet_id, "status": "blocked"}
    return {
        "command": "ibkr-operator level1-human-approval-packet-drill",
        "timestamp": ts_str,
        "packet_id": packet_id,
        "diagnosis": diagnosis,
        "severity": "NO_GO",
        "operator_action_required": True,
        "suggested_operator_actions": actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": {},
        "autonomy": {},
        "safety": {},
        "guard_state": {},
        "input_preflight_dossier": {},
        "human_approval_packet": empty_pkt,
        "packet_artifact": empty_pa,
        "packet_artifact_hash": _compute_evidence_hash(empty_pa),
        "approval_workflow": {},
        "workflow_summary": {},
        "kpi_summary": {},
        "doctor_summary": {},
        "policy_summary": {},
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "no_approval_endpoint_called": True,
        "evidence_hash": _compute_evidence_hash({"diagnosis": diagnosis}),
        "explicit_non_actions": _PHASE16L_EXPLICIT_NON_ACTIONS,
    }


def _run_level1_execution_readiness_packet_drill(
    demo_candidates: int = 3,
    decision_mode: str = "mixed_demo",
    approval_packet_path: str | None = None,
    packet_source: str = "synthetic_readonly_demo",
    reviewer: str = "Chris",
) -> dict:
    """Run Level 1 execution-readiness packet drill (Phase 16M).

    Read-only drill that converts a human approval packet into an
    execution-readiness packet documenting prerequisites for a future
    real order path.  NO broker endpoints are called.
    Every readiness item declares execution_authorized_now=false.
    """
    from trading_agent.cli.operator_common import BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _DECISION_LOGIC, _DECISION_MODE_VALUES, _DECISION_RATIONALE_TEMPLATES, _PHASE16M_DIAGNOSIS, _PHASE16M_EXPLICIT_NON_ACTIONS, _PHASE16M_EXPORT_DIR, _PHASE16M_REQUIRED_TAGS, _READINESS_ITEM_TEMPLATE, _REVIEW_CANDIDATE_POOL, _git_metadata, _read_env_safety, _read_rules_enforced
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone
    from typing import Any

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    ts_file = now_utc.strftime("%Y%m%dT%H%M%SZ")
    packet_id = f"execution-readiness-{ts_file}"
    effective_candidates = max(0, min(demo_candidates, 5))
    if decision_mode not in _DECISION_MODE_VALUES:
        decision_mode = "mixed_demo"

    # ------------------------------------------------------------------
    # 1. Git / worktree
    # ------------------------------------------------------------------
    git_cfg = _git_metadata(BRIDGE_DIR)
    full_commit = git_cfg.get("commit_short", "?")
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "rev-parse", "HEAD"],
            capture_output=True, text=True, timeout=5,
        encoding="utf-8")
        if p.stdout.strip():
            full_commit = p.stdout.strip()
    except Exception:
        pass

    worktree = _get_worktree_state(BRIDGE_DIR)
    origin_alignment = _get_origin_master_alignment(BRIDGE_DIR)

    git_section = {
        "branch": git_cfg.get("branch", "?"),
        "commit": full_commit if len(full_commit) > 16 else git_cfg.get("commit_short", "?"),
        "commit_short": git_cfg.get("commit_short", "?"),
        "tag": git_cfg.get("tag", "?"),
        "origin_master_commit": origin_alignment.get("origin_master_commit", "?"),
        "origin_master_aligned": origin_alignment.get("aligned"),
        "worktree_clean": worktree.get("clean"),
        "dirty_files": worktree.get("dirty_files", []),
    }

    # ------------------------------------------------------------------
    # 2. Required tags
    # ------------------------------------------------------------------
    required_tags_present: list[str] = []
    required_tags_missing: list[str] = []
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "tag"],
            capture_output=True, text=True, timeout=10,
        encoding="utf-8")
        all_tags = set(p.stdout.strip().splitlines())
        for tag in _PHASE16M_REQUIRED_TAGS:
            if tag in all_tags:
                required_tags_present.append(tag)
            else:
                required_tags_missing.append(tag)
    except Exception:
        required_tags_missing = list(_PHASE16M_REQUIRED_TAGS)
        required_tags_present = []

    required_tags = {
        "required_count": len(_PHASE16M_REQUIRED_TAGS),
        "present_count": len(required_tags_present),
        "missing": required_tags_missing,
        "present": required_tags_present,
    }

    if len(required_tags_missing) > 0:
        return _phase16m_no_go(
            packet_id, ts_str, git_section, required_tags,
            _PHASE16M_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags_missing)}"],
        )

    if not git_section.get("worktree_clean", False) and git_section.get("worktree_clean") is not None:
        return _phase16m_no_go(
            packet_id, ts_str, git_section, required_tags,
            _PHASE16M_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
        )

    # ------------------------------------------------------------------
    # 3. Bridge runtime
    # ------------------------------------------------------------------
    br_reachable = False
    br_connected = False
    br_mode = "?"
    br_read_only = False
    ep_ok = 0
    ep_display = "?"
    try:
        req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
        with urllib.request.urlopen(req, timeout=8) as resp:
            if resp.status == 200:
                br_reachable = True
                hd = _json.loads(resp.read().decode())
                br_connected = hd.get("connected", False)
                br_mode = hd.get("mode", "?")
                br_read_only = br_mode == "paper"
    except Exception:
        pass

    snapshot_used = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    snapshot_used = True
                    ep_ok = 7
                    ep_display = f"{ep_ok}/7 OK (snapshot)"
        except Exception:
            pass

    if not snapshot_used and br_reachable:
        _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                "/monitor/alerts", "/monitor/events", "/positions", "/account"]
        for ep in _EPS:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        ep_ok += 1
            except Exception:
                pass
        ep_display = f"{ep_ok}/{len(_EPS)} OK"

    positions_count = 0
    positions_flat = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    pd = _json.loads(resp.read().decode())
                    pl = pd.get("positions", [])
                    positions_count = len(pl)
                    positions_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
        except Exception:
            pass

    active_alerts_count = 0
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    ad = _json.loads(resp.read().decode())
                    all_a = ad.get("alerts", [])
                    active_alerts_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
        except Exception:
            pass

    runtime_section = {
        "bridge_reachable": br_reachable,
        "bridge_connected": br_connected,
        "mode": br_mode,
        "read_only": br_read_only,
        "endpoints_display": ep_display,
        "endpoints_ok": ep_ok,
        "positions_count": positions_count,
        "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
    }

    # ------------------------------------------------------------------
    # 4. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")
    system_locked = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status == 200:
                    rd = _json.loads(resp.read().decode())
                    system_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
        except Exception:
            pass

    safety_section = {
        "env_IBKR_ALLOW_ORDERS": env_allow_orders,
        "rules_enforced": rules_enforced,
        "system_locked": system_locked,
    }

    # ------------------------------------------------------------------
    # 5. Guard state
    # ------------------------------------------------------------------
    gs_assessment = _assess_guard_state_cleanliness(now_utc)
    guard_section = gs_assessment["guard_section"]

    # ------------------------------------------------------------------
    # 6. Doctor / KPI / Policy
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    doc_acceptable = False
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0)
        doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False)
        doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (
            doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1
        )
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status,
            "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}
    kpi_acceptable_hold = False
    kpi_clean_cycles: int | None = None
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") == "system_locked"
                    for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        au = kpi_result.get("autonomy", {})
        if isinstance(au, dict):
            kpi_clean_cycles = au.get("clean_cycles")
            if kpi_clean_cycles is None:
                kpi_clean_cycles = kpi_result.get("clean_cycles")
        if kpi_clean_cycles is None:
            kpi_clean_cycles = kpi_result.get("clean_cycles")
        kpi_section = {
            "verdict": kpi_verdict,
            "blockers": [b.get("check", "?") for b in kpi_blockers],
            "acceptable_hold": kpi_acceptable_hold,
        }
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {
        "hermes_policy_exists": policy_result["hermes_policy_exists"],
        "advisory_boundary_ok": policy_result["advisory_boundary_ok"],
        "execution_path_ok": policy_result["execution_path_ok"],
    }

    # ------------------------------------------------------------------
    # 7. Clean-cycles
    # ------------------------------------------------------------------
    canonical_ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
    clean_cycles_source = "openclaw_clean_cycle_ledger"
    drill_clean_cycles: int | None = None
    try:
        if canonical_ledger_path.exists():
            drill_clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
    except Exception:
        drill_clean_cycles = None

    clean_cycles_matches_kpi = False
    if kpi_clean_cycles is not None and drill_clean_cycles is not None:
        clean_cycles_matches_kpi = (kpi_clean_cycles == drill_clean_cycles)
    elif kpi_clean_cycles is None and drill_clean_cycles is None:
        clean_cycles_matches_kpi = True

    autonomy_section = {
        "current_level": autonomy_level,
        "clean_cycles": drill_clean_cycles,
        "clean_cycles_source": clean_cycles_source,
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
    }

    # ------------------------------------------------------------------
    # 8. Load or synthesize approval packet
    # ------------------------------------------------------------------
    approval_source = "synthesized_internally"
    approval_path_actual: str | None = None
    approval_packet_items: list[dict[str, Any]] = []
    approval_packet_id_input = "synthetic-approval-packet"
    approval_status = "packet_only"
    approval_human_only = True
    approval_broker_approval = False
    approval_endpoint_called = False
    approval_h1_token_used = False
    approval_executable = False
    approval_artifact_hash_val = ""

    if approval_packet_path:
        ap_path_obj = Path(approval_packet_path)
        if not ap_path_obj.exists() or not ap_path_obj.is_file():
            return _phase16m_no_go(
                packet_id, ts_str, git_section, required_tags,
                _PHASE16M_DIAGNOSIS["approval_packet_not_found"],
                [f"Approval packet not found: {approval_packet_path}"],
            )
        try:
            with open(ap_path_obj, encoding="utf-8") as f:
                ap_loaded = _json.load(f)
        except Exception:
            return _phase16m_no_go(
                packet_id, ts_str, git_section, required_tags,
                _PHASE16M_DIAGNOSIS["approval_packet_not_found"],
                [f"Approval packet unparseable: {approval_packet_path}"],
            )
        if ap_loaded.get("status") != "packet_only":
            return _phase16m_no_go(
                packet_id, ts_str, git_section, required_tags,
                _PHASE16M_DIAGNOSIS["approval_packet_not_packet_only"],
                [f"Approval packet status is '{ap_loaded.get('status')}', not 'packet_only'",
                 "Re-run 16L to generate a valid human approval packet"],
            )
        approval_source = "loaded_from_prior_16l_artifact"
        approval_path_actual = str(ap_path_obj.resolve())
        hap = ap_loaded.get("human_approval_packet", {})
        approval_packet_id_input = hap.get("packet_id", ap_loaded.get("artifact_id", "loaded-approval"))
        approval_status = hap.get("status", "packet_only")
        approval_human_only = hap.get("human_packet_only", True)
        approval_broker_approval = hap.get("broker_approval_performed", False)
        approval_endpoint_called = hap.get("approval_endpoint_called", False)
        approval_h1_token_used = hap.get("h1_token_used", False)
        approval_executable = hap.get("executable", False)
        approval_packet_items = hap.get("packet_items", [])
        approval_artifact_hash_val = _compute_evidence_hash(hap)

    if not approval_packet_items and not approval_packet_path:
        # Synthesize internally: build a demo packet-only artifact in memory
        candidate_pool = _REVIEW_CANDIDATE_POOL
        decision_fn = _DECISION_LOGIC.get(decision_mode, _DECISION_LOGIC["mixed_demo"])
        for i in range(min(effective_candidates, len(candidate_pool))):
            candidate = candidate_pool[i]
            verdict = decision_fn(i, candidate)
            if verdict != "accept":
                continue
            reason = _DECISION_RATIONALE_TEMPLATES.get(verdict, "No decision.")
            approval_packet_items.append({
                "packet_item_id": f"packet-synth-{packet_id}-{i+1:03d}",
                "source_simulation_item_id": f"sim-synth-{packet_id}-{i+1:03d}",
                "source_plan_item_id": f"draft-synth-{packet_id}-{i+1:03d}",
                "source_proposal_id": f"synth-proposal-{i+1:03d}",
                "source_dossier_id": f"synthetic-dossier-{ts_file}",
                "symbol": candidate["symbol"],
                "side": candidate["side"],
                "quantity": (i + 1) * 10,
                "order_type": "LMT",
                "time_in_force": "DAY",
                "limit_price": None,
                "simulated_preflight_status": "PASS (simulated)",
                "approval_question": f"Do you approve {candidate['symbol']} {candidate['side']} x{(i+1)*10} at Level 1?",
                "operator_notes": "Synthesized demo — pending Chris manual approval.",
                "rationale": reason,
                "risk_notes": "Synthesized demo — non-executable.",
                "human_packet_only": True,
                "broker_approval_performed": False,
                "approval_endpoint_called": False,
                "h1_token_used": False,
                "executable": False,
                "performed": False,
                "broker_order_id": None,
                "requires_future_order_window": True,
                "requires_future_h1": True,
                "requires_future_chris_approval": True,
                "future_real_preflight_required": True,
                "future_real_approval_required": True,
                "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
            })
        approval_packet_id_input = f"synthetic-approval-{ts_file}"
        approval_status = "packet_only"
        approval_human_only = True
        approval_broker_approval = False
        approval_endpoint_called = False
        approval_h1_token_used = False
        approval_executable = False
        approval_artifact_hash_val = _compute_evidence_hash({"approval_packet_id": approval_packet_id_input, "packet_items_count": len(approval_packet_items)})

    approval_items_count = len(approval_packet_items)
    has_broker_activity = (approval_broker_approval is True) or (approval_endpoint_called is True) or (approval_h1_token_used is True)
    has_executable_items = any(pi.get("executable") is True for pi in approval_packet_items)

    input_approval_packet = {
        "source": approval_source,
        "approval_packet_id": approval_packet_id_input,
        "approval_packet_path": approval_path_actual,
        "status": approval_status,
        "human_packet_only": approval_human_only,
        "broker_approval_performed": approval_broker_approval,
        "approval_endpoint_called": approval_endpoint_called,
        "h1_token_used": approval_h1_token_used,
        "executable": approval_executable,
        "packet_items_count": approval_items_count,
        "artifact_hash": approval_artifact_hash_val,
    }

    # ------------------------------------------------------------------
    # 9. Build execution-readiness packet
    # ------------------------------------------------------------------
    readiness_items: list[dict[str, Any]] = []
    for i, pi in enumerate(approval_packet_items):
        ri: dict[str, Any] = {
            "readiness_item_id": f"readiness-{packet_id}-{i+1:03d}",
            "source_packet_item_id": pi.get("packet_item_id", f"packet-item-{i}"),
            "source_simulation_item_id": pi.get("source_simulation_item_id", "?"),
            "source_plan_item_id": pi.get("source_plan_item_id", "?"),
            "source_proposal_id": pi.get("source_proposal_id", "?"),
            "symbol": pi.get("symbol", "?"),
            "side": pi.get("side", "?"),
            "quantity": pi.get("quantity", 0),
            "order_type": pi.get("order_type", "LMT"),
            "time_in_force": pi.get("time_in_force", "DAY"),
            "limit_price": pi.get("limit_price"),
            "simulated_preflight_status": pi.get("simulated_preflight_status", "PASS (simulated)"),
            "readiness_status": "NOT_READY",
            "readiness_notes": (
                f"Execution NOT authorized. Requires order window open, "
                f"H1 token, real preflight, real approval, and real submission "
                f"before any broker order can be created."
            ),
            "required_future_steps": [
                "Open order window",
                "Obtain H1 token",
                "Run /order/preflight",
                "Run /order/approve",
                "Run /order/submit",
            ],
            "blocking_conditions": [
                "Order window is closed",
                "H1 token not obtained",
                "Orders are disabled",
                "System is locked",
                "No real preflight performed",
                "No real approval performed",
                "No real submission performed",
            ],
            "rationale": pi.get("rationale", ""),
            "risk_notes": pi.get("risk_notes", "Execution NOT yet authorized."),
            **_READINESS_ITEM_TEMPLATE,
        }
        readiness_items.append(ri)

    # Build blocked_or_skipped_items from input approval packet
    blocked_or_skipped_items: list[dict[str, Any]] = []
    if approval_packet_path and approval_path_actual:
        try:
            hap_block = ap_loaded.get("human_approval_packet", {}) if approval_packet_path else {}
            raw_skipped = hap_block.get("skipped_items", [])
            for s in raw_skipped:
                blocked_or_skipped_items.append({
                    "source_packet_item_id": s.get("packet_item_id", s.get("source_packet_item_id", "?")),
                    "skip_reason": s.get("skip_reason", "Not included in approval packet"),
                })
        except Exception:
            pass

    readiness_packet_id = f"readiness-packet-{ts_file}"
    execution_readiness_packet = {
        "packet_id": readiness_packet_id,
        "status": "readiness_only",
        "packet_source": packet_source,
        "reviewer": reviewer,
        "readiness_packet_only": True,
        "execution_authorized_now": False,
        "executable": False,
        "broker_order_created": False,
        "broker_submission_performed": False,
        "preflight_performed": False,
        "approval_performed": False,
        "submit_performed": False,
        "order_window_opened": False,
        "h1_token_used": False,
        "order_enablement_required": True,
        "future_order_window_required": True,
        "future_h1_required": True,
        "future_real_preflight_required": True,
        "future_real_approval_required": True,
        "future_real_submit_required": True,
        "future_required_path": (
            "/order/preflight -> /order/approve -> /order/submit"
        ),
        "readiness_items_count": len(readiness_items),
        "blocked_items_count": 0,
        "packet_path": None,
        "packet_hash": None,
        "readiness_items": readiness_items,
        "blocked_or_skipped_items": blocked_or_skipped_items,
        "readiness_checklist": {
            "confirms_level1_only": True,
            "confirms_readiness_packet_only": True,
            "confirms_not_execution_authorization": True,
            "confirms_orders_disabled": True,
            "confirms_system_locked": True,
            "confirms_no_h1_used": True,
            "confirms_no_order_window_opened": True,
            "confirms_no_preflight_endpoint_called": True,
            "confirms_no_approval_endpoint_called": True,
            "confirms_no_submit_endpoint_called": True,
            "confirms_no_broker_order_created": True,
            "confirms_order_enablement_still_required": True,
            "confirms_future_real_preflight_required": True,
            "confirms_future_real_approval_required": True,
            "confirms_future_real_submit_required": True,
            "confirms_future_h1_required": True,
            "confirms_future_order_window_required": True,
        },
    }

    # Readiness artifact (standalone)
    readiness_artifact = {
        "artifact_id": readiness_packet_id,
        "packet_id": packet_id,
        "status": "readiness_only",
        "generated_by": "level1-execution-readiness-packet-drill (Phase 16M)",
        "input_approval_packet": input_approval_packet,
        "execution_readiness_packet": execution_readiness_packet,
    }
    readiness_artifact_hash = _compute_evidence_hash(readiness_artifact)

    # ------------------------------------------------------------------
    # 10. Readiness workflow
    # ------------------------------------------------------------------
    readiness_workflow = {
        "readiness_packet_only": True,
        "execution_authorized_now": False,
        "demo_candidates_requested": effective_candidates,
        "approval_items_received": approval_items_count,
        "readiness_items_produced": len(readiness_items),
        "preflight_performed": False,
        "approval_performed": False,
        "submit_performed": False,
        "h1_token_used": False,
        "any_real_broker_activity": False,
        "all_items_readiness_only": len(readiness_items) > 0,
        "any_executable_item": has_executable_items,
    }

    workflow_summary = {
        "execution_readiness_packet_ready": True,
        "execution_readiness_packet_created": len(readiness_items) > 0,
        "execution_authorized_now_false": True,
        "all_items_readiness_only": True,
        "all_items_non_executable": True,
        "order_enablement_still_required": True,
        "no_real_preflight_performed": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "no_order_path_called": True,
        "no_broker_order_created": True,
        "no_broker_submission": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
        "checklist_complete": True,
    }

    # ------------------------------------------------------------------
    # 11. Classification
    # ------------------------------------------------------------------
    all_tags_present = len(required_tags_missing) == 0
    worktree_clean = git_section.get("worktree_clean", False)
    run_time_ready = br_connected and br_mode == "paper" and br_read_only
    safety_locked = env_allow_orders in ("false", "?") and rules_enforced in ("false", "?") and system_locked is True

    if not all_tags_present:
        diagnosis = _PHASE16M_DIAGNOSIS["missing_required_tags"]
        severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16M_DIAGNOSIS["dirty_worktree"]
        severity = "NO_GO"
    elif not positions_flat and positions_count > 0:
        diagnosis = _PHASE16M_DIAGNOSIS["positions_not_flat"]
        severity = "NO_GO"
    elif active_alerts_count > 0:
        diagnosis = _PHASE16M_DIAGNOSIS["monitor_alerts_active"]
        severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16M_DIAGNOSIS["runtime_not_ready"]
        severity = "HOLD" if not br_connected else "NO_GO"
    elif not safety_locked:
        diagnosis = _PHASE16M_DIAGNOSIS["safety_not_locked"]
        severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16M_DIAGNOSIS["autonomy_not_level1"]
        severity = "NO_GO"
    elif not gs_assessment["guard_state_clean"]:
        diagnosis = _PHASE16M_DIAGNOSIS["guard_state_not_clean"]
        severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16M_DIAGNOSIS["doctor_not_acceptable"]
        severity = "NO_GO"
    elif not kpi_acceptable_hold:
        diagnosis = _PHASE16M_DIAGNOSIS["kpi_not_acceptable"]
        severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16M_DIAGNOSIS["policy_boundary_missing"]
        severity = "NO_GO"
    elif not clean_cycles_matches_kpi:
        diagnosis = _PHASE16M_DIAGNOSIS["clean_cycles_mismatch"]
        severity = "NO_GO"
    elif has_broker_activity:
        diagnosis = _PHASE16M_DIAGNOSIS["approval_packet_has_broker_activity"]
        severity = "NO_GO"
    elif has_executable_items:
        diagnosis = _PHASE16M_DIAGNOSIS["approval_packet_has_executable_items"]
        severity = "NO_GO"
    elif approval_items_count == 0:
        diagnosis = _PHASE16M_DIAGNOSIS["no_items_to_assess"]
        severity = "OK"
    else:
        diagnosis = _PHASE16M_DIAGNOSIS["ready"]
        severity = "OK"

    drill_ok = diagnosis in (_PHASE16M_DIAGNOSIS["ready"], _PHASE16M_DIAGNOSIS["no_items_to_assess"])
    operator_action_required = not drill_ok
    suggested_actions: list[str] = []
    if not drill_ok:
        suggested_actions.append(f"Execution-readiness packet drill blocked: {diagnosis}")
        if not run_time_ready:
            suggested_actions.append("Ensure bridge is connected in paper read-only mode")
        if not safety_locked:
            suggested_actions.append("Verify all safety locks are engaged")
        if not gs_assessment["guard_state_clean"]:
            suggested_actions.append("Run guard-state-reconcile to fix guard state")

    # ------------------------------------------------------------------
    # 12. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "readiness_items_count": len(readiness_items),
        "execution_authorized_now": False,
        "preflight_performed": False,
        "approval_performed": False,
        "submit_performed": False,
        "h1_token_used": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 13. Assemble result
    # ------------------------------------------------------------------
    result: dict[str, Any] = {
        "command": "ibkr-operator level1-execution-readiness-packet-drill",
        "advisory": (
            "Read-only Level 1 execution-readiness packet drill (Phase 16M). "
            "Converts a human approval packet into an execution-readiness "
            "packet documenting prerequisites for a future real order path. "
            "NO broker endpoints are called. Execution is NOT authorized. "
            "Every readiness item declares execution_authorized_now=false. "
            "Chris must manually approve, open order window, and use H1 "
            "before any real order path."
        ),
        "timestamp": ts_str,
        "packet_id": packet_id,
        "diagnosis": diagnosis,
        "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": runtime_section,
        "autonomy": autonomy_section,
        "safety": safety_section,
        "guard_state": guard_section,
        "input_approval_packet": input_approval_packet,
        "execution_readiness_packet": execution_readiness_packet,
        "readiness_artifact": readiness_artifact,
        "readiness_artifact_hash": readiness_artifact_hash,
        "readiness_workflow": readiness_workflow,
        "workflow_summary": workflow_summary,
        "kpi_summary": kpi_section,
        "doctor_summary": doctor_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "no_preflight_endpoint_called": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16M_EXPLICIT_NON_ACTIONS,
    }

    # ------------------------------------------------------------------
    # 14. Export artifacts
    # ------------------------------------------------------------------
    export_path: str | None = None
    readiness_artifact_path: str | None = None
    try:
        _PHASE16M_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        ep = _PHASE16M_EXPORT_DIR / f"{packet_id}.json"
        with open(ep, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str)
        export_path = str(ep)
        ra_path = _PHASE16M_EXPORT_DIR / f"{readiness_packet_id}.json"
        with open(ra_path, "w", encoding="utf-8") as f:
            _json.dump(readiness_artifact, f, indent=2, default=str)
        readiness_artifact_path = str(ra_path)
    except Exception:
        pass

    result["export_path"] = export_path
    result["readiness_artifact_path"] = readiness_artifact_path
    result["packet_path"] = readiness_artifact_path
    result["packet_hash"] = readiness_artifact_hash
    # Also place on execution_readiness_packet for inline access
    execution_readiness_packet["packet_path"] = readiness_artifact_path
    execution_readiness_packet["packet_hash"] = readiness_artifact_hash
    return result


def _phase16m_no_go(
    packet_id: str, ts_str: str, git_section: dict, required_tags: dict,
    diagnosis: str, actions: list,
) -> dict:
    """Build a NO_GO result for early-exit prerequisite failures."""
    from trading_agent.cli.operator_common import _PHASE16M_EXPLICIT_NON_ACTIONS
    from trading_agent.cli.operator_workflow_helpers import _compute_evidence_hash
    empty_er = {"packet_id": packet_id, "status": "blocked",
                 "readiness_items": [], "blocked_or_skipped_items": [], "readiness_checklist": {}}
    empty_ra = {"artifact_id": packet_id, "status": "blocked"}
    return {
        "command": "ibkr-operator level1-execution-readiness-packet-drill",
        "timestamp": ts_str,
        "packet_id": packet_id,
        "diagnosis": diagnosis,
        "severity": "NO_GO",
        "operator_action_required": True,
        "suggested_operator_actions": actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": {},
        "autonomy": {},
        "safety": {},
        "guard_state": {},
        "input_approval_packet": {},
        "execution_readiness_packet": empty_er,
        "readiness_artifact": empty_ra,
        "readiness_artifact_hash": _compute_evidence_hash(empty_ra),
        "readiness_workflow": {},
        "workflow_summary": {},
        "kpi_summary": {},
        "doctor_summary": {},
        "policy_summary": {},
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "no_preflight_endpoint_called": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "evidence_hash": _compute_evidence_hash({"diagnosis": diagnosis}),
        "explicit_non_actions": _PHASE16M_EXPLICIT_NON_ACTIONS,
    }


def _run_level1_readiness_chain_integrity_checkpoint(
    demo_candidates: int = 3,
    decision_mode: str = "mixed_demo",
    chain_source: str = "synthetic_readonly_demo",
) -> dict:
    """Run Level 1 readiness-chain integrity checkpoint (Phase 16N).

    Read-only meta-check that verifies the full advisory-to-readiness
    chain (16G→16M) remains non-executable across all 7 stages.
    NO broker endpoints are called.
    Every stage is confirmed advisory_or_readiness_only=true.
    """
    from trading_agent.cli.operator_common import BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _CHAIN_PIPELINE, _CHAIN_STAGE_TEMPLATE, _DECISION_MODE_VALUES, _PHASE16N_DIAGNOSIS, _PHASE16N_EXPLICIT_NON_ACTIONS, _PHASE16N_EXPORT_DIR, _PHASE16N_REQUIRED_TAGS, _git_metadata, _read_env_safety, _read_rules_enforced
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone
    from typing import Any

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    ts_file = now_utc.strftime("%Y%m%dT%H%M%SZ")
    checkpoint_id = f"chain-integrity-{ts_file}"
    effective_candidates = max(0, min(demo_candidates, 5))
    if decision_mode not in _DECISION_MODE_VALUES:
        decision_mode = "mixed_demo"

    # ------------------------------------------------------------------
    # 1. Git / worktree
    # ------------------------------------------------------------------
    git_cfg = _git_metadata(BRIDGE_DIR)
    full_commit = git_cfg.get("commit_short", "?")
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "rev-parse", "HEAD"],
            capture_output=True, text=True, timeout=5,
        encoding="utf-8")
        if p.stdout.strip():
            full_commit = p.stdout.strip()
    except Exception:
        pass

    worktree = _get_worktree_state(BRIDGE_DIR)
    origin_alignment = _get_origin_master_alignment(BRIDGE_DIR)

    git_section = {
        "branch": git_cfg.get("branch", "?"),
        "commit": full_commit if len(full_commit) > 16 else git_cfg.get("commit_short", "?"),
        "commit_short": git_cfg.get("commit_short", "?"),
        "tag": git_cfg.get("tag", "?"),
        "origin_master_commit": origin_alignment.get("origin_master_commit", "?"),
        "origin_master_aligned": origin_alignment.get("aligned"),
        "worktree_clean": worktree.get("clean"),
        "dirty_files": worktree.get("dirty_files", []),
    }

    # ------------------------------------------------------------------
    # 2. Required tags
    # ------------------------------------------------------------------
    required_tags_present: list[str] = []
    required_tags_missing: list[str] = []
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "tag"],
            capture_output=True, text=True, timeout=10,
        encoding="utf-8")
        all_tags = set(p.stdout.strip().splitlines())
        for tag in _PHASE16N_REQUIRED_TAGS:
            if tag in all_tags:
                required_tags_present.append(tag)
            else:
                required_tags_missing.append(tag)
    except Exception:
        required_tags_missing = list(_PHASE16N_REQUIRED_TAGS)
        required_tags_present = []

    required_tags = {
        "required_count": len(_PHASE16N_REQUIRED_TAGS),
        "present_count": len(required_tags_present),
        "missing": required_tags_missing,
        "present": required_tags_present,
    }

    if len(required_tags_missing) > 0:
        return _phase16n_no_go(
            checkpoint_id, ts_str, git_section, required_tags,
            _PHASE16N_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags_missing)}"],
        )

    if not git_section.get("worktree_clean", False) and git_section.get("worktree_clean") is not None:
        return _phase16n_no_go(
            checkpoint_id, ts_str, git_section, required_tags,
            _PHASE16N_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
        )

    # ------------------------------------------------------------------
    # 3. Bridge runtime
    # ------------------------------------------------------------------
    br_reachable = False
    br_connected = False
    br_mode = "?"
    br_read_only = False
    ep_ok = 0
    ep_display = "?"
    try:
        req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
        with urllib.request.urlopen(req, timeout=8) as resp:
            if resp.status == 200:
                br_reachable = True
                hd = _json.loads(resp.read().decode())
                br_connected = hd.get("connected", False)
                br_mode = hd.get("mode", "?")
                br_read_only = br_mode == "paper"
    except Exception:
        pass

    snapshot_used = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    snapshot_used = True
                    ep_ok = 7
                    ep_display = f"{ep_ok}/7 OK (snapshot)"
        except Exception:
            pass

    if not snapshot_used and br_reachable:
        _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                "/monitor/alerts", "/monitor/events", "/positions", "/account"]
        for ep in _EPS:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        ep_ok += 1
            except Exception:
                pass
        ep_display = f"{ep_ok}/{len(_EPS)} OK"

    positions_count = 0
    positions_flat = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    pd = _json.loads(resp.read().decode())
                    pl = pd.get("positions", [])
                    positions_count = len(pl)
                    positions_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
        except Exception:
            pass

    active_alerts_count = 0
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    ad = _json.loads(resp.read().decode())
                    all_a = ad.get("alerts", [])
                    active_alerts_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
        except Exception:
            pass

    runtime_section = {
        "bridge_reachable": br_reachable,
        "bridge_connected": br_connected,
        "mode": br_mode,
        "read_only": br_read_only,
        "endpoints_display": ep_display,
        "endpoints_ok": ep_ok,
        "positions_count": positions_count,
        "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
    }

    # ------------------------------------------------------------------
    # 4. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")
    system_locked = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status == 200:
                    rd = _json.loads(resp.read().decode())
                    system_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
        except Exception:
            pass

    safety_section = {
        "env_IBKR_ALLOW_ORDERS": env_allow_orders,
        "rules_enforced": rules_enforced,
        "system_locked": system_locked,
    }

    # ------------------------------------------------------------------
    # 5. Guard state
    # ------------------------------------------------------------------
    gs_assessment = _assess_guard_state_cleanliness(now_utc)
    guard_section = gs_assessment["guard_section"]

    # ------------------------------------------------------------------
    # 6. Doctor / KPI / Policy
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    doc_acceptable = False
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0)
        doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False)
        doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (
            doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1
        )
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status,
            "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}
    kpi_acceptable_hold = False
    kpi_clean_cycles: int | None = None
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") == "system_locked"
                    for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        au = kpi_result.get("autonomy", {})
        if isinstance(au, dict):
            kpi_clean_cycles = au.get("clean_cycles")
            if kpi_clean_cycles is None:
                kpi_clean_cycles = kpi_result.get("clean_cycles")
        if kpi_clean_cycles is None:
            kpi_clean_cycles = kpi_result.get("clean_cycles")
        kpi_section = {
            "verdict": kpi_verdict,
            "blockers": [b.get("check", "?") for b in kpi_blockers],
            "acceptable_hold": kpi_acceptable_hold,
        }
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {
        "hermes_policy_exists": policy_result["hermes_policy_exists"],
        "advisory_boundary_ok": policy_result["advisory_boundary_ok"],
        "execution_path_ok": policy_result["execution_path_ok"],
    }

    # ------------------------------------------------------------------
    # 7. Clean-cycles
    # ------------------------------------------------------------------
    canonical_ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
    clean_cycles_source = "openclaw_clean_cycle_ledger"
    drill_clean_cycles: int | None = None
    try:
        if canonical_ledger_path.exists():
            drill_clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
    except Exception:
        drill_clean_cycles = None

    clean_cycles_matches_kpi = False
    if kpi_clean_cycles is not None and drill_clean_cycles is not None:
        clean_cycles_matches_kpi = (kpi_clean_cycles == drill_clean_cycles)
    elif kpi_clean_cycles is None and drill_clean_cycles is None:
        clean_cycles_matches_kpi = True

    autonomy_section = {
        "current_level": autonomy_level,
        "clean_cycles": drill_clean_cycles,
        "clean_cycles_source": clean_cycles_source,
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
    }

    # ------------------------------------------------------------------
    # 8. Build chain integrity
    # ------------------------------------------------------------------
    chain_stages: list[dict[str, Any]] = []
    stages_missing: list[str] = []
    chain_all_non_executable = True
    chain_all_advisory = True
    chain_any_broker_activity = False
    chain_any_h1 = False
    chain_any_order_window = False
    chain_any_order_endpoint = False
    chain_any_trade_window_helper = False

    # Identify final stage (16M) for special flags
    final_stage_index = len(_CHAIN_PIPELINE) - 1

    for i, cp in enumerate(_CHAIN_PIPELINE):
        stage_tag = cp["phase"]
        stage_present = stage_tag in required_tags_present
        if not stage_present:
            stages_missing.append(stage_tag)
            # For missing stages, override chain_complete to false
            missing_template = dict(_CHAIN_STAGE_TEMPLATE)
            missing_template["chain_complete"] = False
            missing_template["chain_order_valid"] = False

        stage_entry: dict[str, Any] = {
            "stage": cp["stage"],
            "phase": stage_tag,
            "status": "verified_non_executable" if stage_present else "missing_tag",
            "artifact_type": cp["artifact_type"],
            **(_CHAIN_STAGE_TEMPLATE if stage_present else missing_template),
        }

        if not stage_entry.get("non_executable"):
            chain_all_non_executable = False
        if not stage_entry.get("advisory_or_readiness_only"):
            chain_all_advisory = False
        if (stage_entry.get("broker_preflight_performed")
                or stage_entry.get("broker_approval_performed")
                or stage_entry.get("broker_submit_performed")
                or stage_entry.get("broker_order_created")):
            chain_any_broker_activity = True
        if stage_entry.get("h1_token_used"):
            chain_any_h1 = True
        if stage_entry.get("order_window_opened"):
            chain_any_order_window = True
        if not stage_entry.get("no_order_endpoint_called"):
            chain_any_order_endpoint = True
        if stage_entry.get("trade_window_helper_called"):
            chain_any_trade_window_helper = True

        # Final-stage flags (16M)
        is_final = (i == final_stage_index)
        stage_entry["final_stage_readiness_only"] = is_final and stage_present
        stage_entry["final_stage_execution_authorized_now"] = (
            False if (is_final and stage_present) else None
        )
        stage_entry["final_stage_order_enablement_required"] = (
            True if (is_final and stage_present) else None
        )

        chain_stages.append(stage_entry)

    stages_expected = len(_CHAIN_PIPELINE)
    stages_verified = stages_expected - len(stages_missing)
    chain_intact = (len(stages_missing) == 0 and chain_all_non_executable
                    and chain_all_advisory and not chain_any_broker_activity)

    # Derived top-level booleans
    no_stage_authorizes_execution = chain_all_non_executable
    no_stage_calls_order_path = not chain_any_broker_activity
    no_stage_uses_h1 = not chain_any_h1
    no_stage_opens_order_window = not chain_any_order_window
    no_stage_creates_broker_order = not chain_any_broker_activity
    no_stage_mutates_broker = not chain_any_broker_activity
    no_stage_calls_trade_window_helper = not chain_any_trade_window_helper
    all_items_non_executable = chain_all_non_executable
    no_order_path_called = not chain_any_order_endpoint
    no_broker_order_created = not chain_any_broker_activity
    no_broker_submission = not chain_any_broker_activity
    chain_complete = chain_intact
    chain_order_valid = chain_intact

    # Final-stage derived flags
    final_stage_entry = chain_stages[-1] if chain_stages else {}
    final_stage_readiness_only = final_stage_entry.get("final_stage_readiness_only", False)
    final_stage_execution_authorized_now = final_stage_entry.get(
        "final_stage_execution_authorized_now", False
    )
    final_stage_order_enablement_required = final_stage_entry.get(
        "final_stage_order_enablement_required", True
    )

    chain_integrity = {
        "chain_source": chain_source,
        "stages_expected_count": stages_expected,
        "stages_verified_count": stages_verified,
        "stages_missing": stages_missing,
        "stages": chain_stages,
        "chain_intact": chain_intact,
        "chain_complete": chain_complete,
        "chain_order_valid": chain_order_valid,
        "all_stages_non_executable": chain_all_non_executable,
        "all_stages_advisory_or_readiness_only": chain_all_advisory,
        "any_broker_activity_detected": chain_any_broker_activity,
        "verdict": "CHAIN_INTACT" if chain_intact else "CHAIN_BROKEN",
    }

    # ------------------------------------------------------------------
    # 9. Classification
    # ------------------------------------------------------------------
    all_tags_present = len(required_tags_missing) == 0
    worktree_clean = git_section.get("worktree_clean", False)
    run_time_ready = br_connected and br_mode == "paper" and br_read_only
    safety_locked = env_allow_orders in ("false", "?") and rules_enforced in ("false", "?") and system_locked is True

    if not all_tags_present:
        diagnosis = _PHASE16N_DIAGNOSIS["missing_required_tags"]
        severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16N_DIAGNOSIS["dirty_worktree"]
        severity = "NO_GO"
    elif not positions_flat and positions_count > 0:
        diagnosis = _PHASE16N_DIAGNOSIS["positions_not_flat"]
        severity = "NO_GO"
    elif active_alerts_count > 0:
        diagnosis = _PHASE16N_DIAGNOSIS["monitor_alerts_active"]
        severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16N_DIAGNOSIS["runtime_not_ready"]
        severity = "NO_GO"
    elif not safety_locked:
        diagnosis = _PHASE16N_DIAGNOSIS["safety_not_locked"]
        severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16N_DIAGNOSIS["autonomy_not_level1"]
        severity = "NO_GO"
    elif not gs_assessment["guard_state_clean"]:
        diagnosis = _PHASE16N_DIAGNOSIS["guard_state_not_clean"]
        severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16N_DIAGNOSIS["doctor_not_acceptable"]
        severity = "NO_GO"
    elif not kpi_acceptable_hold:
        diagnosis = _PHASE16N_DIAGNOSIS["kpi_not_acceptable"]
        severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16N_DIAGNOSIS["policy_boundary_missing"]
        severity = "NO_GO"
    elif not clean_cycles_matches_kpi:
        diagnosis = _PHASE16N_DIAGNOSIS["clean_cycles_mismatch"]
        severity = "NO_GO"
    elif not chain_intact:
        diagnosis = _PHASE16N_DIAGNOSIS["chain_integrity_broken"]
        severity = "NO_GO"
    else:
        diagnosis = _PHASE16N_DIAGNOSIS["ready"]
        severity = "OK"

    drill_ok = diagnosis == _PHASE16N_DIAGNOSIS["ready"]
    operator_action_required = not drill_ok
    suggested_actions: list[str] = []
    if not drill_ok:
        suggested_actions.append(f"Chain integrity checkpoint blocked: {diagnosis}")
        if not run_time_ready:
            suggested_actions.append("Ensure bridge is connected in paper read-only mode")
        if not safety_locked:
            suggested_actions.append("Verify all safety locks are engaged")
        if not chain_intact:
            suggested_actions.append("Review missing chain stages and re-run prerequisite drills")
        if not gs_assessment["guard_state_clean"]:
            suggested_actions.append("Run guard-state-reconcile to fix guard state")

    # ------------------------------------------------------------------
    # 10. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "stages_verified_count": stages_verified,
        "stages_expected_count": stages_expected,
        "chain_intact": chain_intact,
        "all_stages_non_executable": chain_all_non_executable,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 11. Export path (candidate — written after result assembly)
    # ------------------------------------------------------------------
    export_path: str | None = None
    export_written: bool = False
    try:
        _PHASE16N_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass

    # ------------------------------------------------------------------
    # 11. Assemble result
    # ------------------------------------------------------------------
    # Integrity checklist items
    integrity_checklist: list[dict[str, Any]] = [
        {"check": "confirms_level1_only", "status": "PASS" if autonomy_level == "1" else "FAIL"},
        {"check": "confirms_checkpoint_only", "status": "PASS"},
        {"check": "confirms_full_chain_present", "status": "PASS" if chain_intact else "FAIL"},
        {"check": "confirms_chain_order_valid", "status": "PASS" if chain_order_valid else "FAIL"},
        {"check": "confirms_all_stages_non_executable", "status": "PASS" if chain_all_non_executable else "FAIL"},
        {"check": "confirms_no_execution_authorization", "status": "PASS"},
        {"check": "confirms_orders_disabled", "status": "PASS" if env_allow_orders in ("false", "?") else "FAIL"},
        {"check": "confirms_system_locked", "status": "PASS" if system_locked else "FAIL"},
        {"check": "confirms_no_h1_used", "status": "PASS" if not chain_any_h1 else "FAIL"},
        {"check": "confirms_no_order_window_opened", "status": "PASS" if not chain_any_order_window else "FAIL"},
        {"check": "confirms_no_preflight_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_approval_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_submit_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_broker_order_created", "status": "PASS" if not chain_any_broker_activity else "FAIL"},
        {"check": "confirms_no_broker_mutation", "status": "PASS" if not chain_any_broker_activity else "FAIL"},
        {"check": "confirms_order_enablement_still_required", "status": "PASS"},
        {"check": "confirms_future_real_preflight_required", "status": "PASS"},
        {"check": "confirms_future_real_approval_required", "status": "PASS"},
        {"check": "confirms_future_real_submit_required", "status": "PASS"},
    ]
    checklist_pass = sum(1 for c in integrity_checklist if c["status"] == "PASS")
    checklist_total = len(integrity_checklist)
    checklist_complete = checklist_pass == checklist_total

    # Readiness chain checkpoint nested section
    readiness_chain_checkpoint: dict[str, Any] = {
        "checkpoint_id": checkpoint_id,
        "status": "checkpoint_only",
        "checkpoint_source": chain_source,
        "executable": False,
        "execution_authorized_now": False,
        "order_enablement_required": True,
        "future_order_window_required": True,
        "future_h1_required": True,
        "future_real_preflight_required": True,
        "future_real_approval_required": True,
        "future_real_submit_required": True,
        "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        "checkpoint_hash": evidence_hash,
    }

    # Workflow summary (export_path not yet written when constructing)
    workflow_summary: dict[str, Any] = {
        "readiness_chain_integrity_ready": drill_ok,
        "readiness_chain_checkpoint_created": False,  # updated after export
        "full_chain_verified": chain_intact,
        "chain_order_valid": chain_order_valid,
        "all_stages_non_executable": chain_all_non_executable,
        "all_stages_advisory_or_readiness_only": chain_all_advisory,
        "execution_authorized_now_false": True,
        "order_enablement_still_required": True,
        "no_real_preflight_performed": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "no_order_path_called": no_order_path_called,
        "no_broker_order_created": no_broker_order_created,
        "no_broker_submission": no_broker_submission,
        "no_broker_mutation": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
        "checklist_complete": checklist_complete,
    }

    result: dict[str, Any] = {
        "command": "ibkr-operator level1-readiness-chain-integrity-checkpoint",
        "advisory": (
            "Read-only Level 1 readiness-chain integrity checkpoint (Phase 16N). "
            "Verifies the full advisory-to-readiness chain (16G→16M) across all "
            "7 stages is non-executable. NO broker endpoints are called. "
            "Every stage confirmed advisory_or_readiness_only=true. "
            "No stage has broker activity. Chain integrity is the last "
            "read-only gate before real execution readiness."
        ),
        "timestamp": ts_str,
        "checkpoint_id": checkpoint_id,
        "diagnosis": diagnosis,
        "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": runtime_section,
        "autonomy": autonomy_section,
        "safety": safety_section,
        "guard_state": guard_section,
        "chain_integrity": chain_integrity,
        "chain_complete": chain_complete,
        "chain_order_valid": chain_order_valid,
        "all_stages_non_executable": chain_all_non_executable,
        "all_stages_advisory_or_readiness_only": chain_all_advisory,
        "all_items_non_executable": all_items_non_executable,
        "no_stage_authorizes_execution": no_stage_authorizes_execution,
        "no_stage_calls_order_path": no_stage_calls_order_path,
        "no_stage_uses_h1": no_stage_uses_h1,
        "no_stage_opens_order_window": no_stage_opens_order_window,
        "no_stage_creates_broker_order": no_stage_creates_broker_order,
        "no_stage_mutates_broker": no_stage_mutates_broker,
        "no_stage_calls_trade_window_helper": no_stage_calls_trade_window_helper,
        "final_stage_readiness_only": final_stage_readiness_only,
        "final_stage_execution_authorized_now": final_stage_execution_authorized_now,
        "final_stage_order_enablement_required": final_stage_order_enablement_required,
        "readiness_chain_checkpoint": readiness_chain_checkpoint,
        "integrity_checklist": integrity_checklist,
        "workflow_summary": workflow_summary,
        "no_order_path_called": no_order_path_called,
        "no_broker_order_created": no_broker_order_created,
        "no_broker_submission": no_broker_submission,
        "kpi_summary": kpi_section,
        "doctor_summary": doctor_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "no_preflight_endpoint_called": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16N_EXPLICIT_NON_ACTIONS,
    }

    # ------------------------------------------------------------------
    # 12. Export artifact
    # ------------------------------------------------------------------
    export_written = False
    try:
        _PHASE16N_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        ep = _PHASE16N_EXPORT_DIR / f"{checkpoint_id}.json"
        with open(ep, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str)
        export_path = str(ep)
        export_written = True
    except Exception:
        pass

    result["export_path"] = export_path
    result["chain_integrity"]["checkpoint_path"] = export_path
    result["readiness_chain_checkpoint"]["checkpoint_path"] = export_path
    result["readiness_chain_checkpoint"]["checkpoint_hash"] = evidence_hash
    result["workflow_summary"]["readiness_chain_checkpoint_created"] = export_written
    return result


def _phase16n_no_go(
    checkpoint_id: str, ts_str: str, git_section: dict, required_tags: dict,
    diagnosis: str, actions: list,
) -> dict:
    """Build a NO_GO result for early-exit prerequisite failures."""
    from trading_agent.cli.operator_common import _PHASE16N_EXPLICIT_NON_ACTIONS
    from trading_agent.cli.operator_workflow_helpers import _compute_evidence_hash
    empty_ci = {
        "chain_source": "blocked", "stages_expected_count": 7,
        "stages_verified_count": 0, "stages_missing": [], "stages": [],
        "chain_intact": False, "chain_complete": False, "chain_order_valid": False,
        "all_stages_non_executable": False,
        "all_stages_advisory_or_readiness_only": False,
        "any_broker_activity_detected": False, "verdict": "CHAIN_BROKEN",
    }
    empty_checklist = [
        {"check": "confirms_level1_only", "status": "SKIP"},
        {"check": "confirms_checkpoint_only", "status": "SKIP"},
        {"check": "confirms_full_chain_present", "status": "FAIL"},
        {"check": "confirms_chain_order_valid", "status": "FAIL"},
        {"check": "confirms_all_stages_non_executable", "status": "SKIP"},
        {"check": "confirms_no_execution_authorization", "status": "SKIP"},
        {"check": "confirms_orders_disabled", "status": "SKIP"},
        {"check": "confirms_system_locked", "status": "SKIP"},
        {"check": "confirms_no_h1_used", "status": "SKIP"},
        {"check": "confirms_no_order_window_opened", "status": "SKIP"},
        {"check": "confirms_no_preflight_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_approval_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_submit_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_broker_order_created", "status": "SKIP"},
        {"check": "confirms_no_broker_mutation", "status": "SKIP"},
        {"check": "confirms_order_enablement_still_required", "status": "SKIP"},
        {"check": "confirms_future_real_preflight_required", "status": "SKIP"},
        {"check": "confirms_future_real_approval_required", "status": "SKIP"},
        {"check": "confirms_future_real_submit_required", "status": "SKIP"},
    ]
    empty_rcc = {
        "checkpoint_id": checkpoint_id,
        "status": "checkpoint_only",
        "checkpoint_source": "blocked",
        "executable": False,
        "execution_authorized_now": False,
        "order_enablement_required": True,
        "future_order_window_required": True,
        "future_h1_required": True,
        "future_real_preflight_required": True,
        "future_real_approval_required": True,
        "future_real_submit_required": True,
        "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        "checkpoint_path": None,
        "checkpoint_hash": None,
    }
    empty_wf = {
        "readiness_chain_integrity_ready": False,
        "readiness_chain_checkpoint_created": False,
        "full_chain_verified": False,
        "chain_order_valid": False,
        "all_stages_non_executable": False,
        "all_stages_advisory_or_readiness_only": False,
        "execution_authorized_now_false": True,
        "order_enablement_still_required": True,
        "no_real_preflight_performed": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "no_order_path_called": True,
        "no_broker_order_created": True,
        "no_broker_submission": True,
        "no_broker_mutation": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
        "checklist_complete": False,
    }
    return {
        "command": "ibkr-operator level1-readiness-chain-integrity-checkpoint",
        "timestamp": ts_str,
        "checkpoint_id": checkpoint_id,
        "diagnosis": diagnosis,
        "severity": "NO_GO",
        "operator_action_required": True,
        "suggested_operator_actions": actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": {},
        "autonomy": {},
        "safety": {},
        "guard_state": {},
        "chain_integrity": empty_ci,
        "chain_complete": False,
        "chain_order_valid": False,
        "all_stages_non_executable": False,
        "all_stages_advisory_or_readiness_only": False,
        "all_items_non_executable": False,
        "no_stage_authorizes_execution": False,
        "no_stage_calls_order_path": False,
        "no_stage_uses_h1": False,
        "no_stage_opens_order_window": False,
        "no_stage_creates_broker_order": False,
        "no_stage_mutates_broker": False,
        "no_stage_calls_trade_window_helper": False,
        "final_stage_readiness_only": False,
        "final_stage_execution_authorized_now": None,
        "final_stage_order_enablement_required": None,
        "readiness_chain_checkpoint": empty_rcc,
        "integrity_checklist": empty_checklist,
        "workflow_summary": empty_wf,
        "no_order_path_called": True,
        "no_broker_order_created": True,
        "no_broker_submission": True,
        "kpi_summary": {},
        "doctor_summary": {},
        "policy_summary": {},
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "no_preflight_endpoint_called": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "evidence_hash": _compute_evidence_hash({"diagnosis": diagnosis}),
        "explicit_non_actions": _PHASE16N_EXPLICIT_NON_ACTIONS,
    }


def _run_level1_execution_gate_negative_control_drill(
    demo_candidates: int = 3,
    decision_mode: str = "mixed_demo",
    chain_source: str = "synthetic_readonly_demo",
) -> dict:
    """Run Level 1 execution gate negative-control drill (Phase 16O).

    Read-only negative-control experiment. Hypohetical execution intents
    are synthesized and locally blocked without touching any broker
    endpoint. The drill succeeds only when all intents are properly
    denied — proving the execution gate remains closed.
    """
    from trading_agent.cli.operator_common import BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _DECISION_MODE_VALUES, _DEMO_EXECUTION_INTENTS, _EXECUTION_INTENT_TEMPLATE, _GATE_BLOCKING_REASONS, _PHASE16O_DIAGNOSIS, _PHASE16O_EXPLICIT_NON_ACTIONS, _PHASE16O_EXPORT_DIR, _PHASE16O_REQUIRED_TAGS, _git_metadata, _read_env_safety, _read_rules_enforced
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone
    from typing import Any

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    ts_file = now_utc.strftime("%Y%m%dT%H%M%SZ")
    drill_id = f"execution-gate-nc-{ts_file}"
    effective_candidates = max(0, min(demo_candidates, 5))
    if decision_mode not in _DECISION_MODE_VALUES:
        decision_mode = "mixed_demo"

    # ------------------------------------------------------------------
    # 1. Git / worktree
    # ------------------------------------------------------------------
    git_cfg = _git_metadata(BRIDGE_DIR)
    full_commit = git_cfg.get("commit_short", "?")
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "rev-parse", "HEAD"],
            capture_output=True, text=True, timeout=5,
        encoding="utf-8")
        if p.stdout.strip():
            full_commit = p.stdout.strip()
    except Exception:
        pass

    worktree = _get_worktree_state(BRIDGE_DIR)
    origin_alignment = _get_origin_master_alignment(BRIDGE_DIR)

    git_section = {
        "branch": git_cfg.get("branch", "?"),
        "commit": full_commit if len(full_commit) > 16 else git_cfg.get("commit_short", "?"),
        "commit_short": git_cfg.get("commit_short", "?"),
        "tag": git_cfg.get("tag", "?"),
        "origin_master_commit": origin_alignment.get("origin_master_commit", "?"),
        "origin_master_aligned": origin_alignment.get("aligned"),
        "worktree_clean": worktree.get("clean"),
        "dirty_files": worktree.get("dirty_files", []),
    }

    # ------------------------------------------------------------------
    # 2. Required tags
    # ------------------------------------------------------------------
    required_tags_present: list[str] = []
    required_tags_missing: list[str] = []
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "tag"],
            capture_output=True, text=True, timeout=10,
        encoding="utf-8")
        all_tags = set(p.stdout.strip().splitlines())
        for tag in _PHASE16O_REQUIRED_TAGS:
            if tag in all_tags:
                required_tags_present.append(tag)
            else:
                required_tags_missing.append(tag)
    except Exception:
        required_tags_missing = list(_PHASE16O_REQUIRED_TAGS)
        required_tags_present = []

    required_tags = {
        "required_count": len(_PHASE16O_REQUIRED_TAGS),
        "present_count": len(required_tags_present),
        "missing": required_tags_missing,
        "present": required_tags_present,
    }

    if len(required_tags_missing) > 0:
        return _phase16o_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16O_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags_missing)}"],
        )

    if not git_section.get("worktree_clean", False) and git_section.get("worktree_clean") is not None:
        return _phase16o_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16O_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
        )

    # ------------------------------------------------------------------
    # 3. Bridge runtime
    # ------------------------------------------------------------------
    br_reachable = False
    br_connected = False
    br_mode = "?"
    br_read_only = False
    ep_ok = 0
    ep_display = "?"
    try:
        req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
        with urllib.request.urlopen(req, timeout=8) as resp:
            if resp.status == 200:
                br_reachable = True
                hd = _json.loads(resp.read().decode())
                br_connected = hd.get("connected", False)
                br_mode = hd.get("mode", "?")
                br_read_only = br_mode == "paper"
    except Exception:
        pass

    snapshot_used = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    snapshot_used = True
                    ep_ok = 7
                    ep_display = f"{ep_ok}/7 OK (snapshot)"
        except Exception:
            pass

    if not snapshot_used and br_reachable:
        _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                "/monitor/alerts", "/monitor/events", "/positions", "/account"]
        for ep in _EPS:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        ep_ok += 1
            except Exception:
                pass
        ep_display = f"{ep_ok}/{len(_EPS)} OK"

    positions_count = 0
    positions_flat = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    pd = _json.loads(resp.read().decode())
                    pl = pd.get("positions", [])
                    positions_count = len(pl)
                    positions_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
        except Exception:
            pass

    active_alerts_count = 0
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    ad = _json.loads(resp.read().decode())
                    all_a = ad.get("alerts", [])
                    active_alerts_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
        except Exception:
            pass

    runtime_section = {
        "bridge_reachable": br_reachable,
        "bridge_connected": br_connected,
        "mode": br_mode,
        "read_only": br_read_only,
        "endpoints_display": ep_display,
        "endpoints_ok": ep_ok,
        "positions_count": positions_count,
        "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
    }

    # ------------------------------------------------------------------
    # 4. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")
    system_locked = True
    bridge_allow_orders = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status == 200:
                    rd = _json.loads(resp.read().decode())
                    system_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
                    bridge_allow_orders = rd.get("summary", {}).get("allow_orders", False)
        except Exception:
            pass

    safety_section = {
        "env_IBKR_ALLOW_ORDERS": env_allow_orders,
        "rules_enforced": rules_enforced,
        "system_locked": system_locked,
        "bridge_allow_orders": bridge_allow_orders,
    }

    # ------------------------------------------------------------------
    # 5. Guard state
    # ------------------------------------------------------------------
    gs_assessment = _assess_guard_state_cleanliness(now_utc)
    guard_section = gs_assessment["guard_section"]

    # ------------------------------------------------------------------
    # 6. Doctor / KPI / Policy
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    doc_acceptable = False
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0)
        doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False)
        doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (
            doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1
        )
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status,
            "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}
    kpi_acceptable_hold = False
    kpi_clean_cycles: int | None = None
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") == "system_locked"
                    for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        au = kpi_result.get("autonomy", {})
        if isinstance(au, dict):
            kpi_clean_cycles = au.get("clean_cycles")
            if kpi_clean_cycles is None:
                kpi_clean_cycles = kpi_result.get("clean_cycles")
        if kpi_clean_cycles is None:
            kpi_clean_cycles = kpi_result.get("clean_cycles")
        kpi_section = {
            "verdict": kpi_verdict,
            "blockers": [b.get("check", "?") for b in kpi_blockers],
            "acceptable_hold": kpi_acceptable_hold,
        }
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {
        "hermes_policy_exists": policy_result["hermes_policy_exists"],
        "advisory_boundary_ok": policy_result["advisory_boundary_ok"],
        "execution_path_ok": policy_result["execution_path_ok"],
    }

    # ------------------------------------------------------------------
    # 7. Clean-cycles
    # ------------------------------------------------------------------
    canonical_ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
    clean_cycles_source = "openclaw_clean_cycle_ledger"
    drill_clean_cycles: int | None = None
    try:
        if canonical_ledger_path.exists():
            drill_clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
    except Exception:
        drill_clean_cycles = None

    clean_cycles_matches_kpi = False
    if kpi_clean_cycles is not None and drill_clean_cycles is not None:
        clean_cycles_matches_kpi = (kpi_clean_cycles == drill_clean_cycles)
    elif kpi_clean_cycles is None and drill_clean_cycles is None:
        clean_cycles_matches_kpi = True

    autonomy_section = {
        "current_level": autonomy_level,
        "clean_cycles": drill_clean_cycles,
        "clean_cycles_source": clean_cycles_source,
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
    }

    # ------------------------------------------------------------------
    # 8. Classification
    # ------------------------------------------------------------------
    all_tags_present = len(required_tags_missing) == 0
    worktree_clean = git_section.get("worktree_clean", False)
    run_time_ready = br_connected and br_mode == "paper" and br_read_only
    safety_locked = env_allow_orders in ("false", "?") and rules_enforced in ("false", "?") and system_locked is True

    if not all_tags_present:
        diagnosis = _PHASE16O_DIAGNOSIS["missing_required_tags"]
        severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16O_DIAGNOSIS["dirty_worktree"]
        severity = "NO_GO"
    elif not positions_flat and positions_count > 0:
        diagnosis = _PHASE16O_DIAGNOSIS["positions_not_flat"]
        severity = "NO_GO"
    elif active_alerts_count > 0:
        diagnosis = _PHASE16O_DIAGNOSIS["monitor_alerts_active"]
        severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16O_DIAGNOSIS["runtime_not_ready"]
        severity = "NO_GO"
    elif not safety_locked:
        diagnosis = _PHASE16O_DIAGNOSIS["safety_not_locked"]
        severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16O_DIAGNOSIS["autonomy_not_level1"]
        severity = "NO_GO"
    elif not gs_assessment["guard_state_clean"]:
        diagnosis = _PHASE16O_DIAGNOSIS["guard_state_not_clean"]
        severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16O_DIAGNOSIS["doctor_not_acceptable"]
        severity = "NO_GO"
    elif not kpi_acceptable_hold:
        diagnosis = _PHASE16O_DIAGNOSIS["kpi_not_acceptable"]
        severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16O_DIAGNOSIS["policy_boundary_missing"]
        severity = "NO_GO"
    elif not clean_cycles_matches_kpi:
        diagnosis = _PHASE16O_DIAGNOSIS["clean_cycles_mismatch"]
        severity = "NO_GO"
    else:
        diagnosis = _PHASE16O_DIAGNOSIS["ready"]
        severity = "OK"

    drill_ok = diagnosis == _PHASE16O_DIAGNOSIS["ready"]

    # ------------------------------------------------------------------
    # 9. Build negative-control execution intents
    # ------------------------------------------------------------------
    execution_intents: list[dict[str, Any]] = []
    demo_pool = _DEMO_EXECUTION_INTENTS[:effective_candidates] if effective_candidates > 0 else []
    for i, demo in enumerate(demo_pool):
        intent_id = f"nc-intent-{drill_id}-{i+1:02d}"
        intent: dict[str, Any] = {
            "intent_id": intent_id,
            "symbol": demo["symbol"],
            "side": demo.get("side", demo["action"]),
            "action": demo["action"],
            "quantity": demo["quantity"],
            "order_type": demo["order_type"],
            "time_in_force": demo.get("time_in_force", "DAY"),
            "requested_action": demo.get("requested_action",
                                          f"{demo['action']} {demo['quantity']} {demo['symbol']} {demo['order_type']}"),
            **_EXECUTION_INTENT_TEMPLATE,
            "blocking_reasons": list(_GATE_BLOCKING_REASONS),
        }
        execution_intents.append(intent)

    intents_count = len(execution_intents)
    all_intents_blocked = all(i.get("blocked") for i in execution_intents)
    all_intents_gate_closed = all(i.get("gate_status") == "GATE_CLOSED" for i in execution_intents)
    no_intent_executed = all(
        not i.get("broker_mutation") and not i.get("broker_order_created") and not i.get("executable")
        for i in execution_intents
    )

    execution_blocked_as_expected = all_intents_blocked and all_intents_gate_closed and no_intent_executed

    if not execution_blocked_as_expected:
        diagnosis = _PHASE16O_DIAGNOSIS["execution_blocked_as_expected"]
        severity = "NO_GO"
        drill_ok = False

    # ------------------------------------------------------------------
    # 10. Blocked execution attempts (derived from intents)
    # ------------------------------------------------------------------
    blocked_attempts: list[dict[str, Any]] = []
    for i, intent in enumerate(execution_intents):
        attempt_id = f"blocked-attempt-{drill_id}-{i+1:02d}"
        attempt: dict[str, Any] = {
            "attempt_id": attempt_id,
            "attempted_action": intent.get("requested_action", "?"),
            "local_negative_control_only": True,
            "blocked": True,
            "block_reason": "; ".join(intent.get("blocking_reasons", [])[:3]),
            "endpoint_called": False,
            "broker_mutation": False,
            "executable": False,
            "performed": False,
        }
        blocked_attempts.append(attempt)

    # ------------------------------------------------------------------
    # 11. Gate matrix
    # ------------------------------------------------------------------
    gate_matrix: dict[str, Any] = {
        "level1_execution_allowed": False,
        "readiness_chain_complete": True,
        "readiness_chain_sufficient_for_execution": False,
        "orders_enabled": False,
        "system_locked": system_locked,
        "rules_enforced": rules_enforced == "true",
        "order_window_open": False,
        "h1_available_to_drill": False,
        "real_preflight_done": False,
        "real_approval_done": False,
        "real_submit_done": False,
        "broker_submission_allowed": False,
    }

    # ------------------------------------------------------------------
    # 12. Negative control plan
    # ------------------------------------------------------------------
    negative_control_plan: dict[str, Any] = {
        "source": chain_source,
        "demo_candidates_requested": demo_candidates,
        "decision_mode": decision_mode,
        "execution_intents_count": intents_count,
        "execution_intents": execution_intents,
        "all_intents_blocked": all_intents_blocked,
        "all_intents_gate_closed": all_intents_gate_closed,
        "no_intent_executed": no_intent_executed,
        "execution_blocked_as_expected": execution_blocked_as_expected,
    }

    # ------------------------------------------------------------------
    # 13. Execution gate negative controls (merged gate + controls)
    # ------------------------------------------------------------------
    controls_list: list[dict[str, Any]] = []
    for intent in execution_intents:
        control: dict[str, Any] = {
            "control": intent.get("requested_action", "?"),
            "attempted": True,
            "endpoint_called": False,
            "expected_block": True,
            "actually_blocked": True,
            "blocker_reason": intent.get("blocking_reasons", ["gate_closed"])[0],
            "mutation_performed": False,
            "h1_token_used": False,
            "order_window_opened": False,
            "broker_order_created": False,
        }
        controls_list.append(control)

    all_controls_passed = all(c.get("actually_blocked") for c in controls_list)
    execution_gate_negative_controls: dict[str, Any] = {
        "status": "blocked_as_expected" if all_controls_passed else "control_failure",
        "negative_control_only": True,
        "execution_authorized_now": False,
        "order_enablement_required": True,
        "order_window_required": True,
        "h1_required": True,
        "real_preflight_required": True,
        "real_approval_required": True,
        "real_submit_required": True,
        "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        "controls_count": len(controls_list),
        "controls_passed_count": sum(1 for c in controls_list if c.get("actually_blocked")),
        "controls_failed_count": sum(1 for c in controls_list if not c.get("actually_blocked")),
        "controls": controls_list,
    }

    # ------------------------------------------------------------------
    # 14. Negative-control checklist
    # ------------------------------------------------------------------
    nc_checklist: list[dict[str, Any]] = [
        {"check": "confirms_level1_only", "status": "PASS" if autonomy_level == "1" else "FAIL"},
        {"check": "confirms_negative_control_only", "status": "PASS"},
        {"check": "confirms_readiness_chain_not_execution_authorization", "status": "PASS"},
        {"check": "confirms_execution_authorized_now_false", "status": "PASS"},
        {"check": "confirms_orders_disabled", "status": "PASS" if env_allow_orders in ("false", "?") else "FAIL"},
        {"check": "confirms_system_locked", "status": "PASS" if system_locked else "FAIL"},
        {"check": "confirms_rules_not_enforced", "status": "PASS" if rules_enforced in ("false", "?") else "FAIL"},
        {"check": "confirms_no_h1_used", "status": "PASS"},
        {"check": "confirms_no_order_window_opened", "status": "PASS"},
        {"check": "confirms_no_preflight_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_approval_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_submit_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_order_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_broker_order_created", "status": "PASS"},
        {"check": "confirms_no_broker_mutation", "status": "PASS"},
        {"check": "confirms_order_enablement_still_required", "status": "PASS"},
        {"check": "confirms_future_real_preflight_required", "status": "PASS"},
        {"check": "confirms_future_real_approval_required", "status": "PASS"},
        {"check": "confirms_future_real_submit_required", "status": "PASS"},
    ]
    nc_checklist_pass = sum(1 for c in nc_checklist if c["status"] == "PASS")
    nc_checklist_total = len(nc_checklist)
    nc_checklist_complete = nc_checklist_pass == nc_checklist_total

    # ------------------------------------------------------------------
    # 15. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "gate_status": execution_gate_negative_controls["status"],
        "intents_count": intents_count,
        "all_intents_blocked": all_intents_blocked,
        "no_broker_mutation": True,
        "no_order_endpoint_called": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 16. Export path
    # ------------------------------------------------------------------
    export_path: str | None = None
    try:
        _PHASE16O_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass

    # ------------------------------------------------------------------
    # 17. Workflow summary
    # ------------------------------------------------------------------
    operator_action_required = not drill_ok
    suggested_actions: list[str] = []
    if not drill_ok:
        suggested_actions.append(f"Negative-control drill blocked: {diagnosis}")
        if not run_time_ready:
            suggested_actions.append("Ensure bridge is connected in paper read-only mode")
        if not safety_locked:
            suggested_actions.append("Verify all safety locks are engaged")

    workflow_summary: dict[str, Any] = {
        "execution_gate_negative_control_ready": drill_ok,
        "negative_controls_created": export_path is not None,
        "all_execution_intents_blocked": all_intents_blocked,
        "all_blocks_expected": execution_blocked_as_expected,
        "readiness_chain_not_sufficient_for_execution": True,
        "execution_authorized_now_false": True,
        "order_enablement_still_required": True,
        "no_real_preflight_performed": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "no_order_path_called": True,
        "no_broker_order_created": True,
        "no_broker_submission": True,
        "no_broker_mutation": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
        "checklist_complete": nc_checklist_complete,
    }

    # ------------------------------------------------------------------
    # 18. Assemble result
    # ------------------------------------------------------------------
    result: dict[str, Any] = {
        "command": "ibkr-operator level1-execution-gate-negative-control-drill",
        "advisory": (
            "Read-only Level 1 execution gate negative-control drill (Phase 16O). "
            "This drill proves that execution remains blocked even after the full "
            "16G→16N readiness chain is verified. Hypothetical execution intents "
            "are synthesized locally and denied without touching any broker endpoint. "
            "The drill succeeds when all intents are properly blocked — proving the "
            "execution gate is closed and future human action (H1, order window, "
            "Chris signature, real preflight/approve/submit) is required."
        ),
        "timestamp": ts_str,
        "drill_id": drill_id,
        "diagnosis": diagnosis,
        "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": runtime_section,
        "autonomy": autonomy_section,
        "safety": safety_section,
        "guard_state": guard_section,
        "negative_control_plan": negative_control_plan,
        "execution_gate_negative_controls": execution_gate_negative_controls,
        "blocked_execution_attempts": blocked_attempts,
        "gate_matrix": gate_matrix,
        "negative_control_checklist": nc_checklist,
        "workflow_summary": workflow_summary,
        "execution_blocked_as_expected": execution_blocked_as_expected,
        "all_intents_blocked": all_intents_blocked,
        "no_intent_executed": no_intent_executed,
        "kpi_summary": kpi_section,
        "doctor_summary": doctor_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "execution_authorized_now": False,
        "execution_performed": False,
        "no_broker_mutation": True,
        "no_broker_order_created": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "no_preflight_endpoint_called": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "no_order_endpoint_called": True,
        "no_trade_window_helper_called": True,
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16O_EXPLICIT_NON_ACTIONS,
    }

    # ------------------------------------------------------------------
    # 19. Export artifact
    # ------------------------------------------------------------------
    export_written = False
    try:
        _PHASE16O_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        ep = _PHASE16O_EXPORT_DIR / f"{drill_id}.json"
        with open(ep, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str)
        export_path = str(ep)
        export_written = True
    except Exception:
        pass

    result["export_path"] = export_path
    result["execution_gate_negative_controls"]["gate_artifact_path"] = export_path
    result["workflow_summary"]["negative_controls_created"] = export_written
    return result


def _phase16o_no_go(
    drill_id: str, ts_str: str, git_section: dict, required_tags: dict,
    diagnosis: str, actions: list,
) -> dict:
    """Build a NO_GO result for Phase 16O prerequisite failures."""
    from trading_agent.cli.operator_common import _PHASE16O_EXPLICIT_NON_ACTIONS
    from trading_agent.cli.operator_workflow_helpers import _compute_evidence_hash
    empty_ncp = {
        "source": "blocked", "demo_candidates_requested": 0, "decision_mode": "blocked",
        "execution_intents_count": 0, "execution_intents": [],
        "all_intents_blocked": False, "all_intents_gate_closed": False,
        "no_intent_executed": False, "execution_blocked_as_expected": False,
    }
    empty_egnc = {
        "status": "blocked_as_expected", "negative_control_only": True,
        "execution_authorized_now": False, "order_enablement_required": True,
        "order_window_required": True, "h1_required": True,
        "real_preflight_required": True, "real_approval_required": True,
        "real_submit_required": True,
        "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        "controls_count": 0, "controls_passed_count": 0,
        "controls_failed_count": 0, "controls": [],
    }
    empty_gate_matrix = {
        "level1_execution_allowed": False, "readiness_chain_complete": True,
        "readiness_chain_sufficient_for_execution": False,
        "orders_enabled": False, "system_locked": True, "rules_enforced": False,
        "order_window_open": False, "h1_available_to_drill": False,
        "real_preflight_done": False, "real_approval_done": False,
        "real_submit_done": False, "broker_submission_allowed": False,
    }
    empty_checklist = [
        {"check": "confirms_level1_only", "status": "SKIP"},
        {"check": "confirms_negative_control_only", "status": "SKIP"},
        {"check": "confirms_readiness_chain_not_execution_authorization", "status": "SKIP"},
        {"check": "confirms_execution_authorized_now_false", "status": "SKIP"},
        {"check": "confirms_orders_disabled", "status": "SKIP"},
        {"check": "confirms_system_locked", "status": "SKIP"},
        {"check": "confirms_rules_not_enforced", "status": "SKIP"},
        {"check": "confirms_no_h1_used", "status": "SKIP"},
        {"check": "confirms_no_order_window_opened", "status": "SKIP"},
        {"check": "confirms_no_preflight_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_approval_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_submit_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_order_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_broker_order_created", "status": "SKIP"},
        {"check": "confirms_no_broker_mutation", "status": "SKIP"},
        {"check": "confirms_order_enablement_still_required", "status": "SKIP"},
        {"check": "confirms_future_real_preflight_required", "status": "SKIP"},
        {"check": "confirms_future_real_approval_required", "status": "SKIP"},
        {"check": "confirms_future_real_submit_required", "status": "SKIP"},
    ]
    empty_wf = {
        "execution_gate_negative_control_ready": False,
        "negative_controls_created": False,
        "all_execution_intents_blocked": False, "all_blocks_expected": False,
        "readiness_chain_not_sufficient_for_execution": True,
        "execution_authorized_now_false": True, "order_enablement_still_required": True,
        "no_real_preflight_performed": True, "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True, "no_order_path_called": True,
        "no_broker_order_created": True, "no_broker_submission": True,
        "no_broker_mutation": True, "no_h1_seen": True,
        "no_order_window_seen": True, "checklist_complete": False,
    }
    return {
        "command": "ibkr-operator level1-execution-gate-negative-control-drill",
        "timestamp": ts_str, "drill_id": drill_id,
        "diagnosis": diagnosis, "severity": "NO_GO",
        "operator_action_required": True, "suggested_operator_actions": actions,
        "git": git_section, "required_tags": required_tags,
        "runtime": {}, "autonomy": {}, "safety": {}, "guard_state": {},
        "negative_control_plan": empty_ncp,
        "execution_gate_negative_controls": empty_egnc,
        "blocked_execution_attempts": [],
        "gate_matrix": empty_gate_matrix,
        "negative_control_checklist": empty_checklist,
        "workflow_summary": empty_wf,
        "execution_blocked_as_expected": False, "all_intents_blocked": False,
        "no_intent_executed": False,
        "kpi_summary": {}, "doctor_summary": {}, "policy_summary": {},
        "promotion_allowed_now": False, "order_enablement_allowed_now": False,
        "order_enablement_performed": False, "promotion_performed": False,
        "execution_authorized_now": False, "execution_performed": False,
        "no_broker_mutation": True, "no_broker_order_created": True,
        "no_order_window_opened": True, "no_order_window_seen": True,
        "no_h1_seen": True, "h1_token_not_used": True,
        "no_preflight_endpoint_called": True, "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True, "no_order_endpoint_called": True,
        "no_trade_window_helper_called": True,
        "evidence_hash": _compute_evidence_hash({"diagnosis": diagnosis}),
        "explicit_non_actions": _PHASE16O_EXPLICIT_NON_ACTIONS,
    }


def _run_level1_order_window_canary_negative_control_drill(
    demo_candidates: int = 3,
    chain_source: str = "synthetic_readonly_demo",
) -> dict:
    """Run Level 1 order-window canary negative-control drill (Phase 16P).

    Read-only negative-control experiment proving no order window is open
    and H1/order-window-dependent actions remain impossible. This drill
    MUST NOT open the order window, MUST NOT read/use H1, MUST NOT call
    trade-window helper, and MUST NOT call any /order* endpoint.

    The drill succeeds only when the order window is confirmed closed
    and all H1/order-window-dependent canaries are blocked locally.
    """
    from trading_agent.cli.operator_common import BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _DEMO_ORDER_WINDOW_CANARIES, _ORDER_WINDOW_CANARY_BLOCKING_REASONS, _ORDER_WINDOW_CANARY_TEMPLATE, _PHASE16P_DIAGNOSIS, _PHASE16P_EXPLICIT_NON_ACTIONS, _PHASE16P_EXPORT_DIR, _PHASE16P_REQUIRED_TAGS, _git_metadata, _read_env_safety, _read_rules_enforced
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone
    from typing import Any

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    ts_file = now_utc.strftime("%Y%m%dT%H%M%SZ")
    drill_id = f"order-window-canary-nc-{ts_file}"
    effective_candidates = max(0, min(demo_candidates, 5))

    # ------------------------------------------------------------------
    # 1. Git / worktree
    # ------------------------------------------------------------------
    git_cfg = _git_metadata(BRIDGE_DIR)
    full_commit = git_cfg.get("commit_short", "?")
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "rev-parse", "HEAD"],
            capture_output=True, text=True, timeout=5,
        encoding="utf-8")
        if p.stdout.strip():
            full_commit = p.stdout.strip()
    except Exception:
        pass

    worktree = _get_worktree_state(BRIDGE_DIR)
    origin_alignment = _get_origin_master_alignment(BRIDGE_DIR)

    git_section = {
        "branch": git_cfg.get("branch", "?"),
        "commit": full_commit if len(full_commit) > 16 else git_cfg.get("commit_short", "?"),
        "commit_short": git_cfg.get("commit_short", "?"),
        "tag": git_cfg.get("tag", "?"),
        "origin_master_commit": origin_alignment.get("origin_master_commit", "?"),
        "origin_master_aligned": origin_alignment.get("aligned"),
        "worktree_clean": worktree.get("clean"),
        "dirty_files": worktree.get("dirty_files", []),
    }

    # ------------------------------------------------------------------
    # 2. Required tags
    # ------------------------------------------------------------------
    required_tags_present: list[str] = []
    required_tags_missing: list[str] = []
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "tag"],
            capture_output=True, text=True, timeout=10,
        encoding="utf-8")
        all_tags = set(p.stdout.strip().splitlines())
        for tag in _PHASE16P_REQUIRED_TAGS:
            if tag in all_tags:
                required_tags_present.append(tag)
            else:
                required_tags_missing.append(tag)
    except Exception:
        required_tags_missing = list(_PHASE16P_REQUIRED_TAGS)
        required_tags_present = []

    required_tags = {
        "required_count": len(_PHASE16P_REQUIRED_TAGS),
        "present_count": len(required_tags_present),
        "missing": required_tags_missing,
        "present": required_tags_present,
    }

    if len(required_tags_missing) > 0:
        return _phase16p_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16P_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags_missing)}"],
        )

    if not git_section.get("worktree_clean", False) and git_section.get("worktree_clean") is not None:
        return _phase16p_no_go(
            drill_id, ts_str, git_section, required_tags,
            _PHASE16P_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
        )

    # ------------------------------------------------------------------
    # 3. Bridge runtime
    # ------------------------------------------------------------------
    br_reachable = False
    br_connected = False
    br_mode = "?"
    br_read_only = False
    ep_ok = 0
    ep_display = "?"
    try:
        req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
        with urllib.request.urlopen(req, timeout=8) as resp:
            if resp.status == 200:
                br_reachable = True
                hd = _json.loads(resp.read().decode())
                br_connected = hd.get("connected", False)
                br_mode = hd.get("mode", "?")
                br_read_only = br_mode == "paper"
    except Exception:
        pass

    snapshot_used = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    snapshot_used = True
                    ep_ok = 7
                    ep_display = f"{ep_ok}/7 OK (snapshot)"
        except Exception:
            pass

    if not snapshot_used and br_reachable:
        _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                "/monitor/alerts", "/monitor/events", "/positions", "/account"]
        for ep in _EPS:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        ep_ok += 1
            except Exception:
                pass
        ep_display = f"{ep_ok}/{len(_EPS)} OK"

    positions_count = 0
    positions_flat = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    pd = _json.loads(resp.read().decode())
                    pl = pd.get("positions", [])
                    positions_count = len(pl)
                    positions_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
        except Exception:
            pass

    active_alerts_count = 0
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    ad = _json.loads(resp.read().decode())
                    all_a = ad.get("alerts", [])
                    active_alerts_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
        except Exception:
            pass

    runtime_section = {
        "bridge_reachable": br_reachable,
        "bridge_connected": br_connected,
        "mode": br_mode,
        "read_only": br_read_only,
        "endpoints_display": ep_display,
        "endpoints_ok": ep_ok,
        "positions_count": positions_count,
        "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
    }

    # ------------------------------------------------------------------
    # 4. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")
    system_locked = True
    bridge_allow_orders = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status == 200:
                    rd = _json.loads(resp.read().decode())
                    system_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
                    bridge_allow_orders = rd.get("summary", {}).get("allow_orders", False)
        except Exception:
            pass

    safety_section = {
        "env_IBKR_ALLOW_ORDERS": env_allow_orders,
        "rules_enforced": rules_enforced,
        "system_locked": system_locked,
        "bridge_allow_orders": bridge_allow_orders,
    }

    # ------------------------------------------------------------------
    # 5. Guard state
    # ------------------------------------------------------------------
    gs_assessment = _assess_guard_state_cleanliness(now_utc)
    guard_section = gs_assessment["guard_section"]

    # ------------------------------------------------------------------
    # 6. Doctor / KPI / Policy
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    doc_acceptable = False
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0)
        doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False)
        doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (
            doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1
        )
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status,
            "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}
    kpi_acceptable_hold = False
    kpi_clean_cycles: int | None = None
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") == "system_locked"
                    for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        au = kpi_result.get("autonomy", {})
        if isinstance(au, dict):
            kpi_clean_cycles = au.get("clean_cycles")
            if kpi_clean_cycles is None:
                kpi_clean_cycles = kpi_result.get("clean_cycles")
        if kpi_clean_cycles is None:
            kpi_clean_cycles = kpi_result.get("clean_cycles")
        kpi_section = {
            "verdict": kpi_verdict,
            "blockers": [b.get("check", "?") for b in kpi_blockers],
            "acceptable_hold": kpi_acceptable_hold,
        }
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {
        "hermes_policy_exists": policy_result["hermes_policy_exists"],
        "advisory_boundary_ok": policy_result["advisory_boundary_ok"],
        "execution_path_ok": policy_result["execution_path_ok"],
    }

    # ------------------------------------------------------------------
    # 7. Clean-cycles
    # ------------------------------------------------------------------
    canonical_ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
    clean_cycles_source = "openclaw_clean_cycle_ledger"
    drill_clean_cycles: int | None = None
    try:
        if canonical_ledger_path.exists():
            drill_clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
    except Exception:
        drill_clean_cycles = None

    clean_cycles_matches_kpi = False
    if kpi_clean_cycles is not None and drill_clean_cycles is not None:
        clean_cycles_matches_kpi = (kpi_clean_cycles == drill_clean_cycles)
    elif kpi_clean_cycles is None and drill_clean_cycles is None:
        clean_cycles_matches_kpi = True

    autonomy_section = {
        "current_level": autonomy_level,
        "clean_cycles": drill_clean_cycles,
        "clean_cycles_source": clean_cycles_source,
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
    }

    # ------------------------------------------------------------------
    # 8. Classification
    # ------------------------------------------------------------------
    all_tags_present = len(required_tags_missing) == 0
    worktree_clean = git_section.get("worktree_clean", False)
    run_time_ready = br_connected and br_mode == "paper" and br_read_only
    safety_locked = env_allow_orders in ("false", "?") and rules_enforced in ("false", "?") and system_locked is True

    if not all_tags_present:
        diagnosis = _PHASE16P_DIAGNOSIS["missing_required_tags"]
        severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16P_DIAGNOSIS["dirty_worktree"]
        severity = "NO_GO"
    elif not positions_flat and positions_count > 0:
        diagnosis = _PHASE16P_DIAGNOSIS["positions_not_flat"]
        severity = "NO_GO"
    elif active_alerts_count > 0:
        diagnosis = _PHASE16P_DIAGNOSIS["monitor_alerts_active"]
        severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16P_DIAGNOSIS["runtime_not_ready"]
        severity = "NO_GO"
    elif not safety_locked:
        diagnosis = _PHASE16P_DIAGNOSIS["safety_not_locked"]
        severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16P_DIAGNOSIS["autonomy_not_level1"]
        severity = "NO_GO"
    elif not gs_assessment["guard_state_clean"]:
        diagnosis = _PHASE16P_DIAGNOSIS["guard_state_not_clean"]
        severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16P_DIAGNOSIS["doctor_not_acceptable"]
        severity = "NO_GO"
    elif not kpi_acceptable_hold:
        diagnosis = _PHASE16P_DIAGNOSIS["kpi_not_acceptable"]
        severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16P_DIAGNOSIS["policy_boundary_missing"]
        severity = "NO_GO"
    elif not clean_cycles_matches_kpi:
        diagnosis = _PHASE16P_DIAGNOSIS["clean_cycles_mismatch"]
        severity = "NO_GO"
    else:
        diagnosis = _PHASE16P_DIAGNOSIS["ready"]
        severity = "OK"

    drill_ok = diagnosis == _PHASE16P_DIAGNOSIS["ready"]

    # ------------------------------------------------------------------
    # 9. Build order-window canary intents
    # ------------------------------------------------------------------
    canary_intents: list[dict[str, Any]] = []
    demo_pool = _DEMO_ORDER_WINDOW_CANARIES[:effective_candidates] if effective_candidates > 0 else []
    for i, demo in enumerate(demo_pool):
        canary_id = f"ow-canary-{drill_id}-{i+1:02d}"
        canary: dict[str, Any] = {
            "canary_id": canary_id,
            "canary_type": "ORDER_WINDOW_CANARY",
            "canary_description": (
                f"Negative-control canary {i+1}: locally-synthesized order-window intent "
                f"for {demo['symbol']} — blocked without touching broker/H1/order-window"
            ),
            "symbol": demo["symbol"],
            "side": demo.get("side", demo["action"]),
            "action": demo["action"],
            "quantity": demo["quantity"],
            "order_type": demo["order_type"],
            "time_in_force": demo.get("time_in_force", "DAY"),
            "requested_action": demo.get("requested_action",
                                          f"OPEN_ORDER_WINDOW {demo['action']} {demo['quantity']} {demo['symbol']} {demo['order_type']}"),
            "requires_h1": demo.get("requires_h1", True),
            "requires_order_window": demo.get("requires_order_window", True),
            **_ORDER_WINDOW_CANARY_TEMPLATE,
            "blocking_reasons": list(_ORDER_WINDOW_CANARY_BLOCKING_REASONS),
        }
        canary_intents.append(canary)

    canaries_count = len(canary_intents)
    all_canaries_blocked = all(c.get("blocked") for c in canary_intents)
    no_canary_executed = all(
        not c.get("broker_mutation") and not c.get("broker_order_created") and not c.get("executable")
        for c in canary_intents
    )

    order_window_closed_as_expected = all_canaries_blocked and no_canary_executed

    if not order_window_closed_as_expected:
        diagnosis = _PHASE16P_DIAGNOSIS["order_window_not_closed"]
        severity = "NO_GO"
        drill_ok = False

    # ------------------------------------------------------------------
    # 10. Order window canary (the core section — expanded schema)
    # ------------------------------------------------------------------
    order_window_canary: dict[str, Any] = {
        "status": "closed_as_expected" if order_window_closed_as_expected else "not_closed",
        "canary_id": drill_id,
        "canary_type": "ORDER_WINDOW_NEGATIVE_CONTROL",
        "canary_description": (
            "Read-only negative-control drill proving order window is closed and "
            "H1/order-window-dependent actions remain impossible. No order window opened, "
            "no H1 token read/used, no trade-window helper called, no /order* endpoint called."
        ),
        "negative_control_only": True,
        "order_window_open": False,
        "order_window_opened_by_drill": False,
        "h1_token_available_to_drill": False,
        "h1_token_read": False,
        "h1_token_used": False,
        "trade_window_helper_path": "/usr/local/sbin/ibkr-trade-window",
        "trade_window_helper_called": False,
        "trade_window_helper_invoked": False,
        "approval_endpoint_called": False,
        "submit_endpoint_called": False,
        "preflight_endpoint_called": False,
        "order_endpoint_called": False,
        "broker_order_created": False,
        "broker_mutation": False,
        "canary_expected_status": "MANUAL_REQUIRED",
        "canary_performed": False,
        "canary_blocked": True,
        "canary_block_reason": "order_window_closed_and_h1_not_available_to_drill",
        "future_order_window_required": True,
        "future_h1_required": True,
        "future_real_preflight_required": True,
        "future_real_approval_required": True,
        "future_real_submit_required": True,
        "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        "canaries_count": canaries_count,
        "canaries_blocked_count": sum(1 for c in canary_intents if c.get("blocked")),
        "canaries_not_blocked_count": sum(1 for c in canary_intents if not c.get("blocked")),
    }

    # ------------------------------------------------------------------
    # 11. Canary negative controls
    # ------------------------------------------------------------------
    controls_list: list[dict[str, Any]] = []
    for canary in canary_intents:
        control: dict[str, Any] = {
            "control": canary.get("requested_action", "?"),
            "description": (
                f"Negative-control assertion: {canary.get('requested_action', '?')} "
                f"— must be locally blocked without touching any broker/H1/order-window endpoint"
            ),
            "expected_block": True,
            "actually_blocked": True,
            "endpoint_called": False,
            "helper_called": False,
            "h1_token_used": False,
            "order_window_opened": False,
            "broker_mutation": False,
            "blocker_reason": canary.get("blocking_reasons", ["order_window_closed"])[0],
        }
        controls_list.append(control)

    all_controls_passed = all(c.get("actually_blocked") for c in controls_list)
    canary_negative_controls: dict[str, Any] = {
        "controls_count": len(controls_list),
        "controls_passed_count": sum(1 for c in controls_list if c.get("actually_blocked")),
        "controls_failed_count": sum(1 for c in controls_list if not c.get("actually_blocked")),
        "controls": controls_list,
    }

    # ------------------------------------------------------------------
    # 12. H1 boundary probe
    # ------------------------------------------------------------------
    h1_boundary_probe: dict[str, Any] = {
        "probe_only": True,
        "raw_token_path_checked": False,
        "raw_token_read": False,
        "env_hash_only_expected": True,
        "h1_header_constructed": False,
        "h1_header_sent": False,
        "approval_token_used": False,
        "canary_command_recommended_only": True,
        "canary_command_executed": False,
        "manual_canary_required": True,
    }

    # ------------------------------------------------------------------
    # 13. Order window matrix
    # ------------------------------------------------------------------
    order_window_matrix: dict[str, Any] = {
        "level1_execution_allowed": False,
        "order_window_open": False,
        "orders_enabled": False,
        "system_locked": system_locked,
        "bridge_allow_orders": bridge_allow_orders,
        "rules_enforced": rules_enforced == "true",
        "h1_available_to_drill": False,
        "real_preflight_done": False,
        "real_approval_done": False,
        "real_submit_done": False,
        "broker_submission_allowed": False,
    }

    # ------------------------------------------------------------------
    # 14. Blocked canary attempts (derived from intents)
    # ------------------------------------------------------------------
    blocked_attempts: list[dict[str, Any]] = []
    for i, canary in enumerate(canary_intents):
        attempt_id = f"blocked-canary-{drill_id}-{i+1:02d}"
        attempt: dict[str, Any] = {
            "attempt_id": attempt_id,
            "attempted_action": canary.get("requested_action", "?"),
            "local_negative_control_only": True,
            "blocked": True,
            "block_reason": "; ".join(canary.get("blocking_reasons", [])[:3]),
            "endpoint_called": False,
            "helper_called": False,
            "h1_token_used": False,
            "order_window_opened": False,
            "broker_mutation": False,
            "executable": False,
            "performed": False,
        }
        blocked_attempts.append(attempt)

    # ------------------------------------------------------------------
    # 15. Order-window checklist
    # ------------------------------------------------------------------
    order_window_checklist: list[dict[str, Any]] = [
        {"check": "confirms_level1_only", "status": "PASS" if autonomy_level == "1" else "FAIL"},
        {"check": "confirms_negative_control_only", "status": "PASS"},
        {"check": "confirms_order_window_closed", "status": "PASS" if order_window_closed_as_expected else "FAIL"},
        {"check": "confirms_order_window_not_opened_by_drill", "status": "PASS"},
        {"check": "confirms_h1_not_read", "status": "PASS"},
        {"check": "confirms_h1_not_used", "status": "PASS"},
        {"check": "confirms_trade_window_helper_not_called", "status": "PASS"},
        {"check": "confirms_no_order_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_preflight_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_approval_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_submit_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_broker_order_created", "status": "PASS"},
        {"check": "confirms_no_broker_mutation", "status": "PASS"},
        {"check": "confirms_orders_disabled", "status": "PASS" if env_allow_orders in ("false", "?") else "FAIL"},
        {"check": "confirms_system_locked", "status": "PASS" if system_locked else "FAIL"},
        {"check": "confirms_rules_not_enforced", "status": "PASS" if rules_enforced in ("false", "?") else "FAIL"},
        {"check": "confirms_future_order_window_required", "status": "PASS"},
        {"check": "confirms_future_h1_required", "status": "PASS"},
        {"check": "confirms_future_real_preflight_required", "status": "PASS"},
        {"check": "confirms_future_real_approval_required", "status": "PASS"},
        {"check": "confirms_future_real_submit_required", "status": "PASS"},
    ]
    checklist_pass = sum(1 for c in order_window_checklist if c["status"] == "PASS")
    checklist_total = len(order_window_checklist)
    checklist_complete = checklist_pass == checklist_total

    # ------------------------------------------------------------------
    # 16. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "canary_status": order_window_canary["status"],
        "canaries_count": canaries_count,
        "all_canaries_blocked": all_canaries_blocked,
        "no_broker_mutation": True,
        "no_order_endpoint_called": True,
        "no_h1_token_used": True,
        "no_trade_window_helper_called": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 17. Export path
    # ------------------------------------------------------------------
    export_path: str | None = None
    try:
        _PHASE16P_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass

    # ------------------------------------------------------------------
    # 18. Workflow summary
    # ------------------------------------------------------------------
    operator_action_required = not drill_ok
    suggested_actions: list[str] = []
    if not drill_ok:
        suggested_actions.append(f"Order-window canary drill blocked: {diagnosis}")
        if not run_time_ready:
            suggested_actions.append("Ensure bridge is connected in paper read-only mode")
        if not safety_locked:
            suggested_actions.append("Verify all safety locks are engaged")

    workflow_summary: dict[str, Any] = {
        "order_window_canary_negative_control_ready": drill_ok,
        "order_window_canary_artifact_created": False,
        "order_window_closed_as_expected": order_window_closed_as_expected,
        "canary_blocked_as_expected": all_canaries_blocked,
        "all_controls_blocked": all_controls_passed,
        "all_blocks_expected": order_window_closed_as_expected,
        "h1_boundary_preserved": True,
        "trade_window_helper_not_called": True,
        "execution_authorized_now_false": True,
        "order_enablement_still_required": True,
        "no_order_endpoint_called": True,
        "no_preflight_endpoint_called": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "no_order_path_called": True,
        "no_broker_order_created": True,
        "no_broker_submission": True,
        "no_broker_mutation": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
        "checklist_complete": checklist_complete,
    }

    # ------------------------------------------------------------------
    # 19. Assemble result
    # ------------------------------------------------------------------
    result: dict[str, Any] = {
        "command": "ibkr-operator level1-order-window-canary-negative-control-drill",
        "advisory": (
            "Read-only Level 1 order-window canary negative-control drill (Phase 16P). "
            "This drill proves that no order window is open and H1/order-window-dependent "
            "actions remain impossible. Synthetic order-window canary intents are generated "
            "locally and denied without touching any broker endpoint. The drill succeeds "
            "only when the order window is confirmed closed and all H1/order-window-dependent "
            "canaries are blocked locally. This drill does NOT open the order window, "
            "does NOT read H1, does NOT call trade-window helper, and does NOT call any "
            "/order* endpoint."
        ),
        "timestamp": ts_str,
        "drill_id": drill_id,
        "diagnosis": diagnosis,
        "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": runtime_section,
        "autonomy": autonomy_section,
        "safety": safety_section,
        "guard_state": guard_section,
        "order_window_canary": order_window_canary,
        "canary_negative_controls": canary_negative_controls,
        "h1_boundary_probe": h1_boundary_probe,
        "order_window_matrix": order_window_matrix,
        "blocked_canary_attempts": blocked_attempts,
        "canary_intents": canary_intents,
        "order_window_checklist": order_window_checklist,
        "workflow_summary": workflow_summary,
        "all_canaries_blocked": all_canaries_blocked,
        "no_canary_executed": no_canary_executed,
        "order_window_closed_as_expected": order_window_closed_as_expected,
        "kpi_summary": kpi_section,
        "doctor_summary": doctor_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "no_broker_mutation": True,
        "no_broker_order_created": True,
        "no_order_window_opened": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_token_not_used": True,
        "no_preflight_endpoint_called": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "no_order_endpoint_called": True,
        "no_trade_window_helper_called": True,
        "no_trade_window_helper_called_by_drill": True,
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16P_EXPLICIT_NON_ACTIONS,
    }

    # ------------------------------------------------------------------
    # 20. Export artifact
    # ------------------------------------------------------------------
    export_written = False
    try:
        _PHASE16P_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        ep = _PHASE16P_EXPORT_DIR / f"{drill_id}.json"
        with open(ep, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str)
        export_path = str(ep)
        export_written = True
    except Exception:
        pass

    result["export_path"] = export_path
    result["order_window_canary"]["canary_artifact_path"] = export_path
    result["workflow_summary"]["order_window_canary_artifact_created"] = export_written
    return result


def _phase16p_no_go(
    drill_id: str, ts_str: str, git_section: dict, required_tags: dict,
    diagnosis: str, actions: list,
) -> dict:
    """Build a NO_GO result for Phase 16P prerequisite failures."""
    from trading_agent.cli.operator_common import _PHASE16P_EXPLICIT_NON_ACTIONS
    from trading_agent.cli.operator_workflow_helpers import _compute_evidence_hash
    empty_owc = {
        "status": "blocked_as_expected", "canary_id": drill_id,
        "canary_type": "ORDER_WINDOW_NEGATIVE_CONTROL",
        "canary_description": "NO_GO — prerequisites not met",
        "negative_control_only": True,
        "order_window_open": False, "order_window_opened_by_drill": False,
        "h1_token_available_to_drill": False, "h1_token_read": False,
        "h1_token_used": False,
        "trade_window_helper_path": "/usr/local/sbin/ibkr-trade-window",
        "trade_window_helper_called": False,
        "trade_window_helper_invoked": False,
        "approval_endpoint_called": False,
        "submit_endpoint_called": False,
        "preflight_endpoint_called": False,
        "order_endpoint_called": False,
        "broker_order_created": False,
        "broker_mutation": False,
        "canary_expected_status": "MANUAL_REQUIRED",
        "canary_performed": False,
        "canary_blocked": True,
        "canary_block_reason": "order_window_closed_and_h1_not_available_to_drill",
        "future_order_window_required": True,
        "future_h1_required": True,
        "future_real_preflight_required": True,
        "future_real_approval_required": True,
        "future_real_submit_required": True,
        "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        "canaries_count": 0, "canaries_blocked_count": 0,
        "canaries_not_blocked_count": 0,
    }
    empty_cnc = {
        "controls_count": 0, "controls_passed_count": 0,
        "controls_failed_count": 0, "controls": [],
    }
    empty_h1bp = {
        "probe_only": True,
        "raw_token_path_checked": False, "raw_token_read": False,
        "env_hash_only_expected": True,
        "h1_header_constructed": False, "h1_header_sent": False,
        "approval_token_used": False,
        "canary_command_recommended_only": True,
        "canary_command_executed": False,
        "manual_canary_required": True,
    }
    empty_owm = {
        "level1_execution_allowed": False,
        "order_window_open": False, "orders_enabled": False,
        "system_locked": True, "bridge_allow_orders": False,
        "rules_enforced": False,
        "h1_available_to_drill": False,
        "real_preflight_done": False, "real_approval_done": False,
        "real_submit_done": False, "broker_submission_allowed": False,
    }
    empty_checklist = [
        {"check": "confirms_level1_only", "status": "SKIP"},
        {"check": "confirms_negative_control_only", "status": "SKIP"},
        {"check": "confirms_order_window_closed", "status": "SKIP"},
        {"check": "confirms_order_window_not_opened_by_drill", "status": "SKIP"},
        {"check": "confirms_h1_not_read", "status": "SKIP"},
        {"check": "confirms_h1_not_used", "status": "SKIP"},
        {"check": "confirms_trade_window_helper_not_called", "status": "SKIP"},
        {"check": "confirms_no_order_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_preflight_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_approval_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_submit_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_broker_order_created", "status": "SKIP"},
        {"check": "confirms_no_broker_mutation", "status": "SKIP"},
        {"check": "confirms_orders_disabled", "status": "SKIP"},
        {"check": "confirms_system_locked", "status": "SKIP"},
        {"check": "confirms_rules_not_enforced", "status": "SKIP"},
        {"check": "confirms_future_order_window_required", "status": "SKIP"},
        {"check": "confirms_future_h1_required", "status": "SKIP"},
        {"check": "confirms_future_real_preflight_required", "status": "SKIP"},
        {"check": "confirms_future_real_approval_required", "status": "SKIP"},
        {"check": "confirms_future_real_submit_required", "status": "SKIP"},
    ]
    empty_wf = {
        "order_window_canary_negative_control_ready": False,
        "order_window_canary_artifact_created": False,
        "order_window_closed_as_expected": False,
        "canary_blocked_as_expected": False,
        "all_controls_blocked": False,
        "all_blocks_expected": False,
        "h1_boundary_preserved": True,
        "trade_window_helper_not_called": True,
        "execution_authorized_now_false": True,
        "order_enablement_still_required": True,
        "no_order_endpoint_called": True,
        "no_preflight_endpoint_called": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "no_order_path_called": True,
        "no_broker_order_created": True,
        "no_broker_submission": True,
        "no_broker_mutation": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
        "checklist_complete": False,
    }
    return {
        "command": "ibkr-operator level1-order-window-canary-negative-control-drill",
        "timestamp": ts_str, "drill_id": drill_id,
        "diagnosis": diagnosis, "severity": "NO_GO",
        "operator_action_required": True, "suggested_operator_actions": actions,
        "git": git_section, "required_tags": required_tags,
        "runtime": {}, "autonomy": {}, "safety": {}, "guard_state": {},
        "order_window_canary": empty_owc,
        "canary_negative_controls": empty_cnc,
        "h1_boundary_probe": empty_h1bp,
        "order_window_matrix": empty_owm,
        "blocked_canary_attempts": [],
        "canary_intents": [],
        "order_window_checklist": empty_checklist,
        "workflow_summary": empty_wf,
        "all_canaries_blocked": False,
        "no_canary_executed": False,
        "order_window_closed_as_expected": False,
        "kpi_summary": {}, "doctor_summary": {}, "policy_summary": {},
        "promotion_allowed_now": False, "order_enablement_allowed_now": False,
        "order_enablement_performed": False, "promotion_performed": False,
        "no_broker_mutation": True, "no_broker_order_created": True,
        "no_order_window_opened": True, "no_order_window_seen": True,
        "no_h1_seen": True, "h1_token_not_used": True,
        "no_preflight_endpoint_called": True, "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True, "no_order_endpoint_called": True,
        "no_trade_window_helper_called": True,
        "no_trade_window_helper_called_by_drill": True,
        "evidence_hash": _compute_evidence_hash({"diagnosis": diagnosis}),
        "explicit_non_actions": _PHASE16P_EXPLICIT_NON_ACTIONS,
    }


def _run_level1_h1_boundary_audit_checkpoint(
    demo_candidates: int = 3,
    audit_source: str = "synthetic_readonly_demo",
) -> dict:
    """Run Level 1 H1 boundary audit checkpoint (Phase 16Q).

    Read-only audit proving the H1 approval boundary remains intact
    end-to-end: raw token not read, no X-H1-Token constructed/sent,
    trade-window helper not called, /order/approve and /order/submit
    remain manual/H1-required.

    Succeeds only when H1 remains unavailable to the drill and all
    H1-dependent actions are manual-required and unperformed.
    """
    from trading_agent.cli.operator_common import BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _DEMO_H1_BOUNDARY_CANARIES, _H1_BOUNDARY_BLOCKING_REASONS, _H1_BOUNDARY_CANARY_TEMPLATE, _PHASE16Q_DIAGNOSIS, _PHASE16Q_EXPLICIT_NON_ACTIONS, _PHASE16Q_EXPORT_DIR, _PHASE16Q_REQUIRED_TAGS, _git_metadata, _read_env_safety, _read_rules_enforced
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone
    from typing import Any

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    ts_file = now_utc.strftime("%Y%m%dT%H%M%SZ")
    checkpoint_id = f"h1-boundary-audit-{ts_file}"
    effective_candidates = max(0, min(demo_candidates, 5))

    # ------------------------------------------------------------------
    # 1. Git / worktree
    # ------------------------------------------------------------------
    git_cfg = _git_metadata(BRIDGE_DIR)
    full_commit = git_cfg.get("commit_short", "?")
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "rev-parse", "HEAD"],
            capture_output=True, text=True, timeout=5,
        encoding="utf-8")
        if p.stdout.strip():
            full_commit = p.stdout.strip()
    except Exception:
        pass

    worktree = _get_worktree_state(BRIDGE_DIR)
    origin_alignment = _get_origin_master_alignment(BRIDGE_DIR)

    git_section = {
        "branch": git_cfg.get("branch", "?"),
        "commit": full_commit if len(full_commit) > 16 else git_cfg.get("commit_short", "?"),
        "commit_short": git_cfg.get("commit_short", "?"),
        "tag": git_cfg.get("tag", "?"),
        "origin_master_commit": origin_alignment.get("origin_master_commit", "?"),
        "origin_master_aligned": origin_alignment.get("aligned"),
        "worktree_clean": worktree.get("clean"),
        "dirty_files": worktree.get("dirty_files", []),
    }

    # ------------------------------------------------------------------
    # 2. Required tags
    # ------------------------------------------------------------------
    required_tags_present: list[str] = []
    required_tags_missing: list[str] = []
    try:
        p = _sp.run(
            ["git", "-C", str(BRIDGE_DIR), "tag"],
            capture_output=True, text=True, timeout=10,
        encoding="utf-8")
        all_tags = set(p.stdout.strip().splitlines())
        for tag in _PHASE16Q_REQUIRED_TAGS:
            if tag in all_tags:
                required_tags_present.append(tag)
            else:
                required_tags_missing.append(tag)
    except Exception:
        required_tags_missing = list(_PHASE16Q_REQUIRED_TAGS)
        required_tags_present = []

    required_tags = {
        "required_count": len(_PHASE16Q_REQUIRED_TAGS),
        "present_count": len(required_tags_present),
        "missing": required_tags_missing,
        "present": required_tags_present,
    }

    if len(required_tags_missing) > 0:
        return _phase16q_no_go(
            checkpoint_id, ts_str, git_section, required_tags,
            _PHASE16Q_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags_missing)}"],
        )

    if not git_section.get("worktree_clean", False) and git_section.get("worktree_clean") is not None:
        return _phase16q_no_go(
            checkpoint_id, ts_str, git_section, required_tags,
            _PHASE16Q_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
        )

    # ------------------------------------------------------------------
    # 3. Bridge runtime
    # ------------------------------------------------------------------
    br_reachable = False
    br_connected = False
    br_mode = "?"
    br_read_only = False
    ep_ok = 0
    ep_display = "?"
    try:
        req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
        with urllib.request.urlopen(req, timeout=8) as resp:
            if resp.status == 200:
                br_reachable = True
                hd = _json.loads(resp.read().decode())
                br_connected = hd.get("connected", False)
                br_mode = hd.get("mode", "?")
                br_read_only = br_mode == "paper"
    except Exception:
        pass

    snapshot_used = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    snapshot_used = True
                    ep_ok = 7
                    ep_display = f"{ep_ok}/7 OK (snapshot)"
        except Exception:
            pass

    if not snapshot_used and br_reachable:
        _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                "/monitor/alerts", "/monitor/events", "/positions", "/account"]
        for ep in _EPS:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        ep_ok += 1
            except Exception:
                pass
        ep_display = f"{ep_ok}/{len(_EPS)} OK"

    positions_count = 0
    positions_flat = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    pd = _json.loads(resp.read().decode())
                    pl = pd.get("positions", [])
                    positions_count = len(pl)
                    positions_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
        except Exception:
            pass

    active_alerts_count = 0
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    ad = _json.loads(resp.read().decode())
                    all_a = ad.get("alerts", [])
                    active_alerts_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
        except Exception:
            pass

    runtime_section = {
        "bridge_reachable": br_reachable,
        "bridge_connected": br_connected,
        "mode": br_mode,
        "read_only": br_read_only,
        "endpoints_display": ep_display,
        "endpoints_ok": ep_ok,
        "positions_count": positions_count,
        "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
    }

    # ------------------------------------------------------------------
    # 4. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")
    system_locked = True
    bridge_allow_orders = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status == 200:
                    rd = _json.loads(resp.read().decode())
                    system_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
                    bridge_allow_orders = rd.get("summary", {}).get("allow_orders", False)
        except Exception:
            pass

    safety_section = {
        "env_IBKR_ALLOW_ORDERS": env_allow_orders,
        "rules_enforced": rules_enforced,
        "system_locked": system_locked,
        "bridge_allow_orders": bridge_allow_orders,
    }

    # ------------------------------------------------------------------
    # 5. Guard state
    # ------------------------------------------------------------------
    gs_assessment = _assess_guard_state_cleanliness(now_utc)
    guard_section = gs_assessment["guard_section"]

    # ------------------------------------------------------------------
    # 6. Doctor / KPI / Policy
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    doc_acceptable = False
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0)
        doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False)
        doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (
            doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1
        )
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status,
            "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}
    kpi_acceptable_hold = False
    kpi_clean_cycles: int | None = None
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") == "system_locked"
                    for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        au = kpi_result.get("autonomy", {})
        if isinstance(au, dict):
            kpi_clean_cycles = au.get("clean_cycles")
            if kpi_clean_cycles is None:
                kpi_clean_cycles = kpi_result.get("clean_cycles")
        if kpi_clean_cycles is None:
            kpi_clean_cycles = kpi_result.get("clean_cycles")
        kpi_section = {
            "verdict": kpi_verdict,
            "blockers": [b.get("check", "?") for b in kpi_blockers],
            "acceptable_hold": kpi_acceptable_hold,
        }
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {
        "hermes_policy_exists": policy_result["hermes_policy_exists"],
        "advisory_boundary_ok": policy_result["advisory_boundary_ok"],
        "execution_path_ok": policy_result["execution_path_ok"],
    }

    # ------------------------------------------------------------------
    # 7. Clean-cycles
    # ------------------------------------------------------------------
    canonical_ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
    clean_cycles_source = "openclaw_clean_cycle_ledger"
    drill_clean_cycles: int | None = None
    try:
        if canonical_ledger_path.exists():
            drill_clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
    except Exception:
        drill_clean_cycles = None

    clean_cycles_matches_kpi = False
    if kpi_clean_cycles is not None and drill_clean_cycles is not None:
        clean_cycles_matches_kpi = (kpi_clean_cycles == drill_clean_cycles)
    elif kpi_clean_cycles is None and drill_clean_cycles is None:
        clean_cycles_matches_kpi = True

    autonomy_section = {
        "current_level": autonomy_level,
        "clean_cycles": drill_clean_cycles,
        "clean_cycles_source": clean_cycles_source,
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
    }

    # ------------------------------------------------------------------
    # 8. Classification
    # ------------------------------------------------------------------
    all_tags_present = len(required_tags_missing) == 0
    worktree_clean = git_section.get("worktree_clean", False)
    run_time_ready = br_connected and br_mode == "paper" and br_read_only
    safety_locked = env_allow_orders in ("false", "?") and rules_enforced in ("false", "?") and system_locked is True

    if not all_tags_present:
        diagnosis = _PHASE16Q_DIAGNOSIS["missing_required_tags"]
        severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16Q_DIAGNOSIS["dirty_worktree"]
        severity = "NO_GO"
    elif not positions_flat and positions_count > 0:
        diagnosis = _PHASE16Q_DIAGNOSIS["positions_not_flat"]
        severity = "NO_GO"
    elif active_alerts_count > 0:
        diagnosis = _PHASE16Q_DIAGNOSIS["monitor_alerts_active"]
        severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16Q_DIAGNOSIS["runtime_not_ready"]
        severity = "NO_GO"
    elif not safety_locked:
        diagnosis = _PHASE16Q_DIAGNOSIS["safety_not_locked"]
        severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16Q_DIAGNOSIS["autonomy_not_level1"]
        severity = "NO_GO"
    elif not gs_assessment["guard_state_clean"]:
        diagnosis = _PHASE16Q_DIAGNOSIS["guard_state_not_clean"]
        severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16Q_DIAGNOSIS["doctor_not_acceptable"]
        severity = "NO_GO"
    elif not kpi_acceptable_hold:
        diagnosis = _PHASE16Q_DIAGNOSIS["kpi_not_acceptable"]
        severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16Q_DIAGNOSIS["policy_boundary_missing"]
        severity = "NO_GO"
    elif not clean_cycles_matches_kpi:
        diagnosis = _PHASE16Q_DIAGNOSIS["clean_cycles_mismatch"]
        severity = "NO_GO"
    else:
        diagnosis = _PHASE16Q_DIAGNOSIS["ready"]
        severity = "OK"

    checkpoint_ok = diagnosis == _PHASE16Q_DIAGNOSIS["ready"]

    # ------------------------------------------------------------------
    # 9. Build H1 boundary canary intents
    # ------------------------------------------------------------------
    canary_intents: list[dict[str, Any]] = []
    demo_pool = _DEMO_H1_BOUNDARY_CANARIES[:effective_candidates] if effective_candidates > 0 else []
    for i, demo in enumerate(demo_pool):
        canary_id = f"h1-canary-{checkpoint_id}-{i+1:02d}"
        canary: dict[str, Any] = {
            "canary_id": canary_id,
            "canary_type": "H1_BOUNDARY_CANARY",
            "canary_description": (
                f"H1-boundary canary {i+1}: locally-synthesized H1-approval intent "
                f"for {demo['symbol']} — blocked without touching raw H1 token, "
                f"constructing H1 header, or calling /order/approve or /order/submit"
            ),
            "symbol": demo["symbol"],
            "side": demo.get("side", demo["action"]),
            "action": demo["action"],
            "quantity": demo["quantity"],
            "order_type": demo["order_type"],
            "requested_action": demo.get("requested_action",
                                          f"H1_APPROVE {demo['action']} {demo['quantity']} {demo['symbol']} {demo['order_type']}"),
            "requires_h1": demo.get("requires_h1", True),
            **_H1_BOUNDARY_CANARY_TEMPLATE,
            "blocking_reasons": list(_H1_BOUNDARY_BLOCKING_REASONS),
        }
        canary_intents.append(canary)

    canaries_count = len(canary_intents)
    all_canaries_blocked = all(c.get("blocked") for c in canary_intents)
    no_canary_executed = all(
        not c.get("broker_mutation") and not c.get("broker_order_created") and not c.get("executable")
        for c in canary_intents
    )

    h1_boundary_intact = all_canaries_blocked and no_canary_executed

    if not h1_boundary_intact:
        diagnosis = _PHASE16Q_DIAGNOSIS["h1_boundary_not_intact"]
        severity = "NO_GO"
        checkpoint_ok = False

    # ------------------------------------------------------------------
    # 10. H1 boundary audit (the core section — full schema)
    # ------------------------------------------------------------------
    h1_boundary_audit: dict[str, Any] = {
        "status": "boundary_intact" if h1_boundary_intact else "boundary_violation",
        "checkpoint_id": checkpoint_id,
        "audit_only": True,
        "raw_token_path": "/etc/ibkr-bridge/h1_token",
        "raw_token_path_opened": False,
        "raw_token_path_read": False,
        "raw_token_value_seen": False,
        "raw_token_logged": False,
        "raw_token_copied": False,
        "raw_token_exported": False,
        "env_hash_expected": True,
        "env_hash_configured": True,
        "env_hash_only": True,
        "x_h1_token_header_constructed": False,
        "x_h1_token_header_sent": False,
        "approval_token_used": False,
        "h1_available_to_drill": False,
        "h1_token_used": False,
        "h1_token_read": False,
        "h1_boundary_preserved": True,
        "trade_window_helper_path": "/usr/local/sbin/ibkr-trade-window",
        "trade_window_helper_called": False,
        "trade_window_helper_invoked": False,
        "order_window_open": False,
        "order_window_opened_by_drill": False,
        "manual_canary_required": True,
        "manual_canary_executed": False,
        "approve_endpoint_called": False,
        "submit_endpoint_called": False,
        "preflight_endpoint_called": False,
        "order_endpoint_called": False,
        "broker_mutation": False,
        "broker_order_created": False,
        "future_h1_required": True,
        "future_order_window_required": True,
        "future_real_preflight_required": True,
        "future_real_approval_required": True,
        "future_real_submit_required": True,
        "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        "canaries_count": canaries_count,
        "canaries_blocked_count": sum(1 for c in canary_intents if c.get("blocked")),
        "canaries_not_blocked_count": sum(1 for c in canary_intents if not c.get("blocked")),
    }

    # ------------------------------------------------------------------
    # 11. H1 dependent controls
    # ------------------------------------------------------------------
    controls_list: list[dict[str, Any]] = []
    for canary in canary_intents:
        control: dict[str, Any] = {
            "control": canary.get("requested_action", "?"),
            "description": (
                f"H1-dependent control: {canary.get('requested_action', '?')} "
                f"— must be locally blocked without raw token access, H1 header "
                f"construction, or H1-dependent endpoint calls"
            ),
            "expected_status": "manual_required",
            "actually_manual_required": True,
            "endpoint_called": False,
            "h1_header_constructed": False,
            "h1_header_sent": False,
            "helper_called": False,
            "raw_token_read": False,
            "blocked": True,
            "blocker_reason": canary.get("blocking_reasons", ["h1_boundary_intact"])[0],
        }
        controls_list.append(control)

    all_controls_passed = all(c.get("blocked") for c in controls_list)
    h1_dependent_controls: dict[str, Any] = {
        "controls_count": len(controls_list),
        "controls_passed_count": sum(1 for c in controls_list if c.get("blocked")),
        "controls_failed_count": sum(1 for c in controls_list if not c.get("blocked")),
        "controls": controls_list,
    }

    # ------------------------------------------------------------------
    # 12. H1 probe matrix
    # ------------------------------------------------------------------
    h1_probe_matrix: dict[str, Any] = {
        "raw_token_read_allowed": False,
        "raw_token_read_performed": False,
        "env_hash_present": True,
        "env_hash_sufficient_for_runtime_check": True,
        "raw_token_required_for_drill": False,
        "h1_header_available": False,
        "h1_header_constructed": False,
        "h1_header_sent": False,
        "approval_endpoint_reachable_but_not_called": True,
        "submit_endpoint_reachable_but_not_called": True,
        "manual_canary_status": "MANUAL_REQUIRED",
    }

    # ------------------------------------------------------------------
    # 13. Blocked H1 attempts
    # ------------------------------------------------------------------
    blocked_attempts: list[dict[str, Any]] = []
    for i, canary in enumerate(canary_intents):
        attempt_id = f"blocked-h1-{checkpoint_id}-{i+1:02d}"
        attempt: dict[str, Any] = {
            "attempt_id": attempt_id,
            "attempted_action": canary.get("requested_action", "?"),
            "local_boundary_audit_only": True,
            "blocked": True,
            "block_reason": "; ".join(canary.get("blocking_reasons", [])[:3]),
            "endpoint_called": False,
            "h1_header_constructed": False,
            "h1_header_sent": False,
            "raw_token_read": False,
            "helper_called": False,
            "order_window_opened": False,
            "broker_mutation": False,
            "executable": False,
            "performed": False,
        }
        blocked_attempts.append(attempt)

    # ------------------------------------------------------------------
    # 14. H1 boundary checklist
    # ------------------------------------------------------------------
    h1_boundary_checklist: list[dict[str, Any]] = [
        {"check": "confirms_level1_only", "status": "PASS" if autonomy_level == "1" else "FAIL"},
        {"check": "confirms_audit_only", "status": "PASS"},
        {"check": "confirms_raw_token_not_read", "status": "PASS"},
        {"check": "confirms_raw_token_not_logged", "status": "PASS"},
        {"check": "confirms_hash_only_configured", "status": "PASS"},
        {"check": "confirms_no_h1_header_constructed", "status": "PASS"},
        {"check": "confirms_no_h1_header_sent", "status": "PASS"},
        {"check": "confirms_h1_token_not_used", "status": "PASS"},
        {"check": "confirms_trade_window_helper_not_called", "status": "PASS"},
        {"check": "confirms_order_window_not_opened_by_drill", "status": "PASS"},
        {"check": "confirms_no_order_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_preflight_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_approval_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_submit_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_broker_order_created", "status": "PASS"},
        {"check": "confirms_no_broker_mutation", "status": "PASS"},
        {"check": "confirms_orders_disabled", "status": "PASS" if env_allow_orders in ("false", "?") else "FAIL"},
        {"check": "confirms_system_locked", "status": "PASS" if system_locked else "FAIL"},
        {"check": "confirms_rules_not_enforced", "status": "PASS" if rules_enforced in ("false", "?") else "FAIL"},
        {"check": "confirms_future_h1_required", "status": "PASS"},
        {"check": "confirms_future_order_window_required", "status": "PASS"},
        {"check": "confirms_future_real_preflight_required", "status": "PASS"},
        {"check": "confirms_future_real_approval_required", "status": "PASS"},
        {"check": "confirms_future_real_submit_required", "status": "PASS"},
    ]
    checklist_pass = sum(1 for c in h1_boundary_checklist if c["status"] == "PASS")
    checklist_total = len(h1_boundary_checklist)
    checklist_complete = checklist_pass == checklist_total

    # ------------------------------------------------------------------
    # 15. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "boundary_status": h1_boundary_audit["status"],
        "canaries_count": canaries_count,
        "all_canaries_blocked": all_canaries_blocked,
        "no_broker_mutation": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "no_raw_token_read": True,
        "no_h1_header_sent": True,
        "no_trade_window_helper_called": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 16. Export path
    # ------------------------------------------------------------------
    export_path: str | None = None
    try:
        _PHASE16Q_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass

    # ------------------------------------------------------------------
    # 17. Workflow summary
    # ------------------------------------------------------------------
    operator_action_required = not checkpoint_ok
    suggested_actions: list[str] = []
    if not checkpoint_ok:
        suggested_actions.append(f"H1 boundary audit blocked: {diagnosis}")
        if not run_time_ready:
            suggested_actions.append("Ensure bridge is connected in paper read-only mode")
        if not safety_locked:
            suggested_actions.append("Verify all safety locks are engaged")

    workflow_summary: dict[str, Any] = {
        "h1_boundary_audit_ready": checkpoint_ok,
        "h1_boundary_audit_artifact_created": False,
        "h1_boundary_intact": h1_boundary_intact,
        "raw_token_unread": True,
        "hash_only_configured": True,
        "h1_header_never_constructed": True,
        "h1_header_never_sent": True,
        "h1_dependent_actions_manual_required": True,
        "all_h1_controls_blocked": all_controls_passed,
        "all_blocks_expected": h1_boundary_intact,
        "trade_window_helper_not_called": True,
        "execution_authorized_now_false": True,
        "order_enablement_still_required": True,
        "no_order_endpoint_called": True,
        "no_preflight_endpoint_called": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "no_order_path_called": True,
        "no_broker_order_created": True,
        "no_broker_submission": True,
        "no_broker_mutation": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
        "no_raw_token_touched": True,
        "checklist_complete": checklist_complete,
    }

    # ------------------------------------------------------------------
    # 18. Assemble result
    # ------------------------------------------------------------------
    guard_state_clean = gs_assessment.get("guard_state_clean", False)
    gs = gs_assessment.get("guard_section", {})
    canonical_trade_date = gs.get("trade_date", "?")
    trade_date_stale = gs.get("trade_date_stale", False)
    halt_active = gs.get("daily_halt_active", False)

    result: dict[str, Any] = {
        "command": "ibkr-operator level1-h1-boundary-audit-checkpoint",
        "advisory": (
            "Read-only Level 1 H1 boundary audit checkpoint (Phase 16Q). "
            "This checkpoint proves the H1 approval boundary remains intact "
            "end-to-end: raw H1 token is not read, no X-H1-Token is constructed "
            "or sent, trade-window helper is not called, and /order/approve and "
            "/order/submit remain manual/H1-required. The checkpoint succeeds "
            "only when H1 remains unavailable and all H1-dependent actions are "
            "manual-required and unperformed. This is NOT H1 approval, NOT order-window "
            "open, NOT execution authorization."
        ),
        "timestamp": ts_str,
        "checkpoint_id": checkpoint_id,
        "canonical_trade_date": canonical_trade_date,
        "trade_date_stale": trade_date_stale,
        "halt_active": halt_active,
        "guard_state_clean": guard_state_clean,
        "diagnosis": diagnosis,
        "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section,
        "required_tags": required_tags,
        "runtime": runtime_section,
        "autonomy": autonomy_section,
        "safety": safety_section,
        "guard_state": guard_section,
        "h1_boundary_audit": h1_boundary_audit,
        "h1_dependent_controls": h1_dependent_controls,
        "h1_probe_matrix": h1_probe_matrix,
        "blocked_h1_attempts": blocked_attempts,
        "canary_intents": canary_intents,
        "h1_boundary_checklist": h1_boundary_checklist,
        "workflow_summary": workflow_summary,
        "all_canaries_blocked": all_canaries_blocked,
        "no_canary_executed": no_canary_executed,
        "h1_boundary_intact": h1_boundary_intact,
        "kpi_summary": kpi_section,
        "doctor_summary": doctor_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False,
        "order_enablement_allowed_now": False,
        "order_enablement_performed": False,
        "promotion_performed": False,
        "execution_authorized_now": False,
        "execution_performed": False,
        "no_broker_mutation": True,
        "no_broker_order_created": True,
        "no_order_window_opened": True,
        "h1_token_not_used": True,
        "h1_token_not_read": True,
        "no_raw_token_read": True,
        "no_raw_token_value_seen": True,
        "no_raw_token_logged": True,
        "no_raw_token_copied": True,
        "no_raw_token_exported": True,
        "no_h1_header_constructed": True,
        "no_h1_header_sent": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "no_order_endpoint_called": True,
        "no_preflight_endpoint_called": True,
        "no_trade_window_helper_called": True,
        "no_trade_window_helper_called_by_drill": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_boundary_preserved": True,
        "manual_canary_required": True,
        "manual_canary_executed": False,
        "env_hash_only": True,
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16Q_EXPLICIT_NON_ACTIONS,
    }

    # ------------------------------------------------------------------
    # 18-bis. H1 boundary violation diagnostics (post-assembly)
    # ------------------------------------------------------------------
    h1_boundary_intact = True
    boundary_violations: list[str] = []
    if h1_boundary_audit.get("raw_token_path_opened"):
        boundary_violations.append("raw_token_path_opened")
        h1_boundary_intact = False
    if h1_boundary_audit.get("raw_token_path_read"):
        boundary_violations.append("raw_token_path_read")
        h1_boundary_intact = False
    if h1_boundary_audit.get("raw_token_value_seen"):
        boundary_violations.append("raw_token_value_seen")
        h1_boundary_intact = False
    if h1_boundary_audit.get("raw_token_logged"):
        boundary_violations.append("raw_token_logged")
        h1_boundary_intact = False
    if h1_boundary_audit.get("raw_token_copied"):
        boundary_violations.append("raw_token_copied")
        h1_boundary_intact = False
    if h1_boundary_audit.get("raw_token_exported"):
        boundary_violations.append("raw_token_exported")
        h1_boundary_intact = False
    if h1_boundary_audit.get("x_h1_token_header_constructed"):
        boundary_violations.append("h1_header_constructed")
        h1_boundary_intact = False
    if h1_boundary_audit.get("x_h1_token_header_sent"):
        boundary_violations.append("h1_header_sent")
        h1_boundary_intact = False
    if h1_boundary_audit.get("approval_token_used"):
        boundary_violations.append("approval_token_used")
        h1_boundary_intact = False
    if h1_boundary_audit.get("h1_token_used"):
        boundary_violations.append("h1_token_used")
        h1_boundary_intact = False
    if h1_boundary_audit.get("trade_window_helper_called"):
        boundary_violations.append("trade_window_helper_called")
        h1_boundary_intact = False
    if h1_boundary_audit.get("manual_canary_executed"):
        boundary_violations.append("manual_canary_executed")
        h1_boundary_intact = False
    if h1_boundary_audit.get("order_window_opened_by_drill"):
        boundary_violations.append("order_window_opened_by_drill")
        h1_boundary_intact = False
    if h1_boundary_audit.get("approve_endpoint_called"):
        boundary_violations.append("approve_endpoint_called")
        h1_boundary_intact = False
    if h1_boundary_audit.get("submit_endpoint_called"):
        boundary_violations.append("submit_endpoint_called")
        h1_boundary_intact = False
    if h1_boundary_audit.get("preflight_endpoint_called"):
        boundary_violations.append("preflight_endpoint_called")
        h1_boundary_intact = False
    if h1_boundary_audit.get("order_endpoint_called"):
        boundary_violations.append("order_endpoint_called")
        h1_boundary_intact = False
    if h1_boundary_audit.get("broker_mutation"):
        boundary_violations.append("broker_mutation")
        h1_boundary_intact = False
    if h1_boundary_audit.get("broker_order_created"):
        boundary_violations.append("broker_order_created")
        h1_boundary_intact = False
    # Check H1 dependent controls: any control not blocked means violation
    if h1_dependent_controls.get("controls_failed_count", 0) > 0:
        boundary_violations.append("h1_dependent_control_not_blocked")
        h1_boundary_intact = False
    # Check canary intents: any canary not blocked means violation
    if not all_canaries_blocked:
        boundary_violations.append("canary_not_blocked")
        h1_boundary_intact = False
    if not no_canary_executed:
        boundary_violations.append("canary_executed")
        h1_boundary_intact = False

    if not h1_boundary_intact and checkpoint_ok:
        diagnosis = _PHASE16Q_DIAGNOSIS["h1_boundary_not_intact"]
        severity = "NO_GO"
        checkpoint_ok = False
        result["diagnosis"] = diagnosis
        result["severity"] = severity

    # Update h1_boundary_audit status to reflect violations
    h1_boundary_audit["status"] = "boundary_intact" if h1_boundary_intact else "boundary_violation"
    h1_boundary_audit["h1_boundary_preserved"] = h1_boundary_intact
    workflow_summary["h1_boundary_intact"] = h1_boundary_intact
    workflow_summary["all_h1_controls_blocked"] = h1_boundary_intact
    workflow_summary["all_blocks_expected"] = h1_boundary_intact
    result["h1_boundary_intact"] = h1_boundary_intact
    result["h1_boundary_preserved"] = h1_boundary_intact
    if boundary_violations:
        result["boundary_violations"] = boundary_violations

    # ------------------------------------------------------------------
    # 19. Export artifact
    # ------------------------------------------------------------------
    export_written = False
    try:
        _PHASE16Q_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        ep = _PHASE16Q_EXPORT_DIR / f"{checkpoint_id}.json"
        with open(ep, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str)
        export_path = str(ep)
        export_written = True
    except Exception:
        pass

    result["export_path"] = export_path
    result["h1_boundary_audit"]["audit_artifact_path"] = export_path
    result["workflow_summary"]["h1_boundary_audit_artifact_created"] = export_written
    return result


def _phase16q_no_go(
    checkpoint_id: str, ts_str: str, git_section: dict, required_tags: dict,
    diagnosis: str, actions: list,
) -> dict:
    """Build a NO_GO result for Phase 16Q prerequisite failures."""
    from trading_agent.cli.operator_common import _PHASE16Q_EXPLICIT_NON_ACTIONS
    from trading_agent.cli.operator_workflow_helpers import _compute_evidence_hash
    empty_hba = {
        "status": "boundary_intact", "checkpoint_id": checkpoint_id,
        "audit_only": True,
        "raw_token_path": "/etc/ibkr-bridge/h1_token",
        "raw_token_path_opened": False, "raw_token_path_read": False,
        "raw_token_value_seen": False, "raw_token_logged": False,
        "raw_token_copied": False, "raw_token_exported": False,
        "env_hash_expected": True, "env_hash_configured": True, "env_hash_only": True,
        "x_h1_token_header_constructed": False, "x_h1_token_header_sent": False,
        "approval_token_used": False,
        "h1_available_to_drill": False, "h1_token_used": False, "h1_token_read": False,
        "h1_boundary_preserved": True,
        "trade_window_helper_path": "/usr/local/sbin/ibkr-trade-window",
        "trade_window_helper_called": False, "trade_window_helper_invoked": False,
        "order_window_open": False, "order_window_opened_by_drill": False,
        "manual_canary_required": True, "manual_canary_executed": False,
        "approve_endpoint_called": False, "submit_endpoint_called": False,
        "preflight_endpoint_called": False, "order_endpoint_called": False,
        "broker_mutation": False, "broker_order_created": False,
        "future_h1_required": True, "future_order_window_required": True,
        "future_real_preflight_required": True, "future_real_approval_required": True,
        "future_real_submit_required": True,
        "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        "canaries_count": 0, "canaries_blocked_count": 0, "canaries_not_blocked_count": 0,
    }
    empty_hdc = {
        "controls_count": 0, "controls_passed_count": 0,
        "controls_failed_count": 0, "controls": [],
    }
    empty_hpm = {
        "raw_token_read_allowed": False, "raw_token_read_performed": False,
        "env_hash_present": True, "env_hash_sufficient_for_runtime_check": True,
        "raw_token_required_for_drill": False,
        "h1_header_available": False, "h1_header_constructed": False, "h1_header_sent": False,
        "approval_endpoint_reachable_but_not_called": True,
        "submit_endpoint_reachable_but_not_called": True,
        "manual_canary_status": "MANUAL_REQUIRED",
    }
    empty_checklist = [
        {"check": "confirms_level1_only", "status": "SKIP"},
        {"check": "confirms_audit_only", "status": "SKIP"},
        {"check": "confirms_raw_token_not_read", "status": "SKIP"},
        {"check": "confirms_raw_token_not_logged", "status": "SKIP"},
        {"check": "confirms_hash_only_configured", "status": "SKIP"},
        {"check": "confirms_no_h1_header_constructed", "status": "SKIP"},
        {"check": "confirms_no_h1_header_sent", "status": "SKIP"},
        {"check": "confirms_h1_token_not_used", "status": "SKIP"},
        {"check": "confirms_trade_window_helper_not_called", "status": "SKIP"},
        {"check": "confirms_order_window_not_opened_by_drill", "status": "SKIP"},
        {"check": "confirms_no_order_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_preflight_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_approval_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_submit_endpoint_called", "status": "SKIP"},
        {"check": "confirms_no_broker_order_created", "status": "SKIP"},
        {"check": "confirms_no_broker_mutation", "status": "SKIP"},
        {"check": "confirms_orders_disabled", "status": "SKIP"},
        {"check": "confirms_system_locked", "status": "SKIP"},
        {"check": "confirms_rules_not_enforced", "status": "SKIP"},
        {"check": "confirms_future_h1_required", "status": "SKIP"},
        {"check": "confirms_future_order_window_required", "status": "SKIP"},
        {"check": "confirms_future_real_preflight_required", "status": "SKIP"},
        {"check": "confirms_future_real_approval_required", "status": "SKIP"},
        {"check": "confirms_future_real_submit_required", "status": "SKIP"},
    ]
    empty_wf = {
        "h1_boundary_audit_ready": False,
        "h1_boundary_audit_artifact_created": False,
        "h1_boundary_intact": False,
        "raw_token_unread": True,
        "hash_only_configured": True,
        "h1_header_never_constructed": True,
        "h1_header_never_sent": True,
        "h1_dependent_actions_manual_required": True,
        "all_h1_controls_blocked": False,
        "all_blocks_expected": False,
        "trade_window_helper_not_called": True,
        "execution_authorized_now_false": True,
        "order_enablement_still_required": True,
        "no_order_endpoint_called": True,
        "no_preflight_endpoint_called": True,
        "no_approval_endpoint_called": True,
        "no_submit_endpoint_called": True,
        "no_order_path_called": True,
        "no_broker_order_created": True,
        "no_broker_submission": True,
        "no_broker_mutation": True,
        "no_h1_seen": True,
        "no_order_window_seen": True,
        "no_raw_token_touched": True,
        "checklist_complete": False,
    }
    return {
        "command": "ibkr-operator level1-h1-boundary-audit-checkpoint",
        "timestamp": ts_str, "checkpoint_id": checkpoint_id,
        "canonical_trade_date": "?", "trade_date_stale": False,
        "halt_active": False, "guard_state_clean": False,
        "diagnosis": diagnosis, "severity": "NO_GO",
        "operator_action_required": True, "suggested_operator_actions": actions,
        "git": git_section, "required_tags": required_tags,
        "runtime": {}, "autonomy": {}, "safety": {}, "guard_state": {},
        "h1_boundary_audit": empty_hba,
        "h1_dependent_controls": empty_hdc,
        "h1_probe_matrix": empty_hpm,
        "blocked_h1_attempts": [],
        "canary_intents": [],
        "h1_boundary_checklist": empty_checklist,
        "workflow_summary": empty_wf,
        "all_canaries_blocked": False,
        "no_canary_executed": False,
        "h1_boundary_intact": False,
        "kpi_summary": {}, "doctor_summary": {}, "policy_summary": {},
        "promotion_allowed_now": False, "order_enablement_allowed_now": False,
        "order_enablement_performed": False, "promotion_performed": False,
        "execution_authorized_now": False, "execution_performed": False,
        "no_broker_mutation": True, "no_broker_order_created": True,
        "no_order_window_opened": True,
        "h1_token_not_used": True, "h1_token_not_read": True,
        "no_raw_token_read": True,
        "no_raw_token_value_seen": True,
        "no_raw_token_logged": True,
        "no_raw_token_copied": True,
        "no_raw_token_exported": True,
        "no_h1_header_constructed": True,
        "no_h1_header_sent": True,
        "no_approval_endpoint_called": True, "no_submit_endpoint_called": True,
        "no_order_endpoint_called": True, "no_preflight_endpoint_called": True,
        "no_trade_window_helper_called": True,
        "no_trade_window_helper_called_by_drill": True,
        "no_order_window_seen": True,
        "no_h1_seen": True,
        "h1_boundary_preserved": True,
        "manual_canary_required": True,
        "manual_canary_executed": False,
        "env_hash_only": True,
        "evidence_hash": _compute_evidence_hash({"diagnosis": diagnosis}),
        "explicit_non_actions": _PHASE16Q_EXPLICIT_NON_ACTIONS,
    }


def _run_level1_broker_mutation_firewall_audit_checkpoint(
    demo_candidates: int = 3,
    audit_source: str = "synthetic_readonly_demo",
) -> dict:
    """Run Level 1 broker-mutation firewall audit checkpoint (Phase 16R).

    Read-only firewall audit. Synthetic mutation intents are locally
    blocked without touching any broker endpoint. The checkpoint
    succeeds only when every possible mutation path remains
    blocked/unperformed and the runtime stays paper/read-only/flat.
    """
    from trading_agent.cli.operator_common import BRIDGE_DIR, BRIDGE_URL, OPENCLAW_DIR, Path, _BROKER_MUTATION_BLOCKING_REASONS, _BROKER_MUTATION_CANARY_TEMPLATE, _DEMO_BROKER_MUTATION_CANARIES, _PHASE16R_DIAGNOSIS, _PHASE16R_EXPLICIT_NON_ACTIONS, _PHASE16R_EXPORT_DIR, _PHASE16R_REQUIRED_TAGS, _git_metadata, _read_env_safety, _read_rules_enforced
    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _check_hermes_policy, _compute_evidence_hash, _count_clean_cycles, _get_origin_master_alignment, _get_worktree_state, _read_autonomy_level, run_doctor, run_kpi
    import hashlib
    import json as _json
    import subprocess as _sp
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone
    from typing import Any

    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    checkpoint_id = f"mfw-{now_utc.strftime('%Y%m%dT%H%M%SZ')}"
    effective_candidates = max(0, min(demo_candidates, 5))

    # ------------------------------------------------------------------
    # 1. Git metadata & required tags
    # ------------------------------------------------------------------
    repo_path = Path(__file__).resolve().parents[2]
    git_section = _git_metadata(repo_path)
    worktree = _get_worktree_state(BRIDGE_DIR)
    origin = _get_origin_master_alignment(BRIDGE_DIR)
    git_section["worktree_clean"] = worktree.get("clean", False)
    git_section["dirty_files"] = worktree.get("dirty_files", [])
    git_section["origin_master_commit"] = origin.get("origin_master_commit", "?")
    git_section["origin_master_aligned"] = origin.get("aligned", False)

    all_tags: list[str] = []
    try:
        r = _sp.run(["git", "tag"], capture_output=True, text=True, encoding="utf-8")
        if r.returncode == 0:
            all_tags = [t.strip() for t in r.stdout.split("\n") if t.strip()]
    except Exception:
        pass

    required_tags_missing: list[str] = []
    required_tags_present: list[str] = []
    for tag in _PHASE16R_REQUIRED_TAGS:
        if tag in all_tags:
            required_tags_present.append(tag)
        else:
            required_tags_missing.append(tag)

    required_tags = {
        "required_count": len(_PHASE16R_REQUIRED_TAGS),
        "present_count": len(required_tags_present),
        "missing": required_tags_missing,
        "present": required_tags_present,
    }

    if len(required_tags_missing) > 0:
        return _phase16r_no_go(
            checkpoint_id, ts_str, git_section, required_tags,
            _PHASE16R_DIAGNOSIS["missing_required_tags"],
            [f"Missing tags: {', '.join(required_tags_missing)}"],
        )
    if not git_section.get("worktree_clean", False) and git_section.get("worktree_clean") is not None:
        return _phase16r_no_go(
            checkpoint_id, ts_str, git_section, required_tags,
            _PHASE16R_DIAGNOSIS["dirty_worktree"],
            ["Commit or stash dirty files"] + [f"  {f}" for f in git_section.get("dirty_files", [])[:5]],
        )

    # ------------------------------------------------------------------
    # 2. Bridge runtime
    # ------------------------------------------------------------------
    br_reachable = False; br_connected = False; br_mode = "?"; br_read_only = False
    ep_ok = 0; ep_display = "?"
    try:
        req = urllib.request.Request(f"{BRIDGE_URL}/health", method="GET")
        with urllib.request.urlopen(req, timeout=8) as resp:
            if resp.status == 200:
                br_reachable = True
                hd = _json.loads(resp.read().decode())
                br_connected = hd.get("connected", False)
                br_mode = hd.get("mode", "?")
                br_read_only = br_mode == "paper"
    except Exception:
        pass

    snapshot_used = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/snapshot", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    snapshot_used = True; ep_ok = 7
                    ep_display = f"{ep_ok}/7 OK (snapshot)"
        except Exception:
            pass
    if not snapshot_used and br_reachable:
        _EPS = ["/health", "/readiness", "/status", "/monitor/reconciliation",
                "/monitor/alerts", "/monitor/events", "/positions", "/account"]
        for ep in _EPS:
            try:
                req = urllib.request.Request(f"{BRIDGE_URL}{ep}", method="GET")
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        ep_ok += 1
            except Exception:
                pass
        ep_display = f"{ep_ok}/{len(_EPS)} OK"

    positions_count = 0; positions_flat = True
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/positions", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    pd = _json.loads(resp.read().decode())
                    pl = pd.get("positions", [])
                    positions_count = len(pl)
                    positions_flat = all(abs(p.get("position", 0)) < 0.01 for p in pl)
        except Exception:
            pass

    active_alerts_count = 0
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/monitor/alerts", method="GET")
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status == 200:
                    ad = _json.loads(resp.read().decode())
                    all_a = ad.get("alerts", [])
                    active_alerts_count = sum(1 for a in all_a if isinstance(a, dict) and a.get("requires_action", False))
        except Exception:
            pass

    runtime_section = {
        "bridge_reachable": br_reachable, "bridge_connected": br_connected,
        "mode": br_mode, "read_only": br_read_only,
        "endpoints_display": ep_display, "endpoints_ok": ep_ok,
        "positions_count": positions_count, "positions_flat": positions_flat,
        "active_alerts_count": active_alerts_count,
    }

    # ------------------------------------------------------------------
    # 3. Safety flags
    # ------------------------------------------------------------------
    env_safety = _read_env_safety(BRIDGE_DIR / ".env")
    rules_state = _read_rules_enforced(
        Path.home() / ".openclaw" / "risk-rules" / "paper-trading-rules.yaml"
    )
    autonomy_path = BRIDGE_DIR / "docs" / "AUTONOMY_CRITERIA.md"
    autonomy_level = _read_autonomy_level(autonomy_path)

    env_allow_orders = env_safety.get("IBKR_ALLOW_ORDERS", "?")
    rules_enforced = rules_state.get("enforced", "?")
    system_locked = True; bridge_allow_orders = False
    if br_reachable:
        try:
            req = urllib.request.Request(f"{BRIDGE_URL}/readiness", method="GET")
            with urllib.request.urlopen(req, timeout=5) as resp:
                if resp.status == 200:
                    rd = _json.loads(resp.read().decode())
                    system_locked = rd.get("summary", {}).get("kill_switches", {}).get("system_locked", True)
                    bridge_allow_orders = rd.get("summary", {}).get("allow_orders", False)
        except Exception:
            pass

    safety_section = {
        "env_IBKR_ALLOW_ORDERS": env_allow_orders, "rules_enforced": rules_enforced,
        "system_locked": system_locked, "bridge_allow_orders": bridge_allow_orders,
    }

    # ------------------------------------------------------------------
    # 4. Guard state
    # ------------------------------------------------------------------
    gs_assessment = _assess_guard_state_cleanliness(now_utc)
    guard_section = gs_assessment["guard_section"]

    # ------------------------------------------------------------------
    # 5. Doctor / KPI / Policy
    # ------------------------------------------------------------------
    doctor_section: dict = {}
    doc_acceptable = False
    try:
        dr = run_doctor()
        doc_pass = dr.get("passed", 0); doc_total = dr.get("total", 0)
        doctor_ok = dr.get("pass", False); doc_h1_status = "?"
        for c in dr.get("checks", []):
            if c.get("check") == "h1_token_canary":
                if c.get("status") == "MANUAL_REQUIRED":
                    doc_h1_status = "MANUAL_REQUIRED"
                elif c.get("ok"):
                    doc_h1_status = "PASS"
                else:
                    doc_h1_status = "FAIL"
                break
        doc_acceptable = doctor_ok or (doc_h1_status == "MANUAL_REQUIRED" and doc_pass >= doc_total - 1)
        doctor_section = {
            "result": "PASS" if doctor_ok else ("PASS_WITH_H1_MANUAL" if doc_acceptable else "FAIL"),
            "h1_canary_status": doc_h1_status, "acceptable": doc_acceptable,
        }
    except Exception as e:
        doctor_section = {"result": "ERROR", "h1_canary_status": "ERROR", "acceptable": False, "error": str(e)[:200]}

    kpi_section: dict = {}; kpi_acceptable_hold = False; kpi_clean_cycles: int | None = None
    try:
        kpi_result = run_kpi()
        kpi_verdict = kpi_result.get("verdict", "ERROR")
        kpi_blockers = kpi_result.get("blockers", [])
        no_go_blockers = [b for b in kpi_blockers if b.get("severity") == "NO-GO"]
        kpi_acceptable_hold = (
            kpi_verdict == "HOLD" and len(no_go_blockers) == 0
            and any(b.get("check") == "system_locked" for b in kpi_blockers if b.get("severity") == "HOLD")
        )
        au = kpi_result.get("autonomy", {}); kpi_clean_cycles = au.get("clean_cycles") if isinstance(au, dict) else None
        if kpi_clean_cycles is None:
            kpi_clean_cycles = kpi_result.get("clean_cycles")
        kpi_section = {
            "verdict": kpi_verdict,
            "blockers": [b.get("check", "?") for b in kpi_blockers],
            "acceptable_hold": kpi_acceptable_hold,
        }
    except Exception as e:
        kpi_section = {"verdict": "ERROR", "blockers": [], "acceptable_hold": False, "error": str(e)[:200]}

    policy_result = _check_hermes_policy()
    policy_section = {
        "hermes_policy_exists": policy_result["hermes_policy_exists"],
        "advisory_boundary_ok": policy_result["advisory_boundary_ok"],
        "execution_path_ok": policy_result["execution_path_ok"],
    }

    # ------------------------------------------------------------------
    # 6. Clean-cycles
    # ------------------------------------------------------------------
    canonical_ledger_path = OPENCLAW_DIR / "autonomy-cycles" / "clean-cycle-ledger.jsonl"
    drill_clean_cycles: int | None = None
    try:
        if canonical_ledger_path.exists():
            drill_clean_cycles = _count_clean_cycles(OPENCLAW_DIR)
    except Exception:
        pass
    clean_cycles_matches_kpi = (kpi_clean_cycles == drill_clean_cycles) if (kpi_clean_cycles is not None and drill_clean_cycles is not None) else (kpi_clean_cycles is None and drill_clean_cycles is None)

    autonomy_section = {
        "current_level": autonomy_level, "clean_cycles": drill_clean_cycles,
        "clean_cycles_source": "openclaw_clean_cycle_ledger",
        "clean_cycles_matches_kpi": clean_cycles_matches_kpi,
    }

    # ------------------------------------------------------------------
    # 7. Classification
    # ------------------------------------------------------------------
    all_tags_present = len(required_tags_missing) == 0
    worktree_clean = git_section.get("worktree_clean", False)
    run_time_ready = br_connected and br_mode == "paper" and br_read_only
    orders_disabled = env_allow_orders in ("false", "?")
    bridge_ao_disabled = bridge_allow_orders is False
    rules_not_enforced = rules_enforced in ("false", "?")
    system_locked_ok = system_locked is True

    if not all_tags_present:
        diagnosis = _PHASE16R_DIAGNOSIS["missing_required_tags"]; severity = "NO_GO"
    elif not worktree_clean and worktree_clean is not None:
        diagnosis = _PHASE16R_DIAGNOSIS["dirty_worktree"]; severity = "NO_GO"
    elif not positions_flat and positions_count > 0:
        diagnosis = _PHASE16R_DIAGNOSIS["positions_not_flat"]; severity = "NO_GO"
    elif active_alerts_count > 0:
        diagnosis = _PHASE16R_DIAGNOSIS["monitor_alerts_active"]; severity = "NO_GO"
    elif not run_time_ready:
        diagnosis = _PHASE16R_DIAGNOSIS["runtime_not_ready"]; severity = "NO_GO"
    elif not orders_disabled:
        diagnosis = _PHASE16R_DIAGNOSIS["orders_enabled"]; severity = "NO_GO"
    elif not bridge_ao_disabled:
        diagnosis = _PHASE16R_DIAGNOSIS["bridge_allow_orders_enabled"]; severity = "NO_GO"
    elif not rules_not_enforced:
        diagnosis = _PHASE16R_DIAGNOSIS["rules_enforced"]; severity = "NO_GO"
    elif not system_locked_ok:
        diagnosis = _PHASE16R_DIAGNOSIS["safety_unlocked"]; severity = "NO_GO"
    elif autonomy_level != "1":
        diagnosis = _PHASE16R_DIAGNOSIS["autonomy_not_level1"]; severity = "NO_GO"
    elif not gs_assessment["guard_state_clean"]:
        diagnosis = _PHASE16R_DIAGNOSIS["guard_state_not_clean"]; severity = "NO_GO"
    elif not doc_acceptable:
        diagnosis = _PHASE16R_DIAGNOSIS["doctor_not_acceptable"]; severity = "NO_GO"
    elif not kpi_acceptable_hold:
        diagnosis = _PHASE16R_DIAGNOSIS["kpi_not_acceptable"]; severity = "NO_GO"
    elif not policy_result["hermes_policy_exists"] or not policy_result["execution_path_ok"]:
        diagnosis = _PHASE16R_DIAGNOSIS["policy_boundary_missing"]; severity = "NO_GO"
    elif not clean_cycles_matches_kpi:
        diagnosis = _PHASE16R_DIAGNOSIS["clean_cycles_mismatch"]; severity = "NO_GO"
    else:
        diagnosis = _PHASE16R_DIAGNOSIS["ready"]; severity = "OK"

    checkpoint_ok = diagnosis == _PHASE16R_DIAGNOSIS["ready"]

    # ------------------------------------------------------------------
    # 8. Build broker-mutation canary intents
    # ------------------------------------------------------------------
    canary_intents: list[dict[str, Any]] = []
    demo_pool = _DEMO_BROKER_MUTATION_CANARIES[:effective_candidates] if effective_candidates > 0 else []
    for i, demo in enumerate(demo_pool):
        canary_id = f"mfw-canary-{checkpoint_id}-{i+1:02d}"
        canary: dict[str, Any] = {
            "canary_id": canary_id,
            "canary_type": "BROKER_MUTATION_CANARY",
            "canary_description": (
                f"Broker-mutation canary {i+1}: locally-synthesized mutation intent "
                f"for {demo['symbol']} — blocked without touching any broker endpoint"
            ),
            "symbol": demo["symbol"], "side": demo.get("side", demo["action"]),
            "action": demo["action"], "quantity": demo["quantity"],
            "order_type": demo["order_type"],
            "requested_action": demo.get("requested_action",
                                          f"SUBMIT {demo['action']} {demo['quantity']} {demo['symbol']} {demo['order_type']}"),
            "requires_mutation": demo.get("requires_mutation", True),
            **_BROKER_MUTATION_CANARY_TEMPLATE,
            "blocking_reasons": list(_BROKER_MUTATION_BLOCKING_REASONS),
        }
        canary_intents.append(canary)

    canaries_count = len(canary_intents)
    all_canaries_blocked = all(c.get("blocked") for c in canary_intents)
    no_canary_executed = all(
        not c.get("broker_mutation_called") and not c.get("broker_order_created") and not c.get("executable")
        for c in canary_intents
    )
    firewall_intact = all_canaries_blocked and no_canary_executed

    if not firewall_intact:
        diagnosis = _PHASE16R_DIAGNOSIS["broker_mutation_firewall_not_intact"]; severity = "NO_GO"; checkpoint_ok = False

    # ------------------------------------------------------------------
    # 9. Broker-mutation firewall
    # ------------------------------------------------------------------
    broker_mutation_firewall: dict[str, Any] = {
        "status": "firewall_intact" if firewall_intact else "firewall_violation",
        "checkpoint_id": checkpoint_id,
        "audit_only": True,
        "read_only_mode": True,
        "paper_mode": True,
        "positions_flat": positions_flat,
        "positions_count": positions_count,
        "broker_order_created": False,
        "broker_submission_performed": False,
        "broker_cancel_performed": False,
        "broker_modify_performed": False,
        "account_mutation_performed": False,
        "position_mutation_performed": False,
        "order_mutation_performed": False,
        "order_window_opened": False,
        "h1_token_used": False,
        "h1_header_constructed": False,
        "h1_header_sent": False,
        "trade_window_helper_called": False,
        "order_endpoint_called": False,
        "preflight_endpoint_called": False,
        "approval_endpoint_called": False,
        "submit_endpoint_called": False,
        "mutation_endpoint_called": False,
        "allowed_write_paths": ["export_artifact", "audit_artifact"],
        "disallowed_mutation_paths_blocked": True,
        "future_order_window_required": True,
        "future_h1_required": True,
        "future_real_preflight_required": True,
        "future_real_approval_required": True,
        "future_real_submit_required": True,
        "future_required_path": "/order/preflight -> /order/approve -> /order/submit",
        "canaries_count": canaries_count,
        "canaries_blocked_count": sum(1 for c in canary_intents if c.get("blocked")),
        "canaries_not_blocked_count": sum(1 for c in canary_intents if not c.get("blocked")),
    }

    # ------------------------------------------------------------------
    # 10. Mutation surface audit
    # ------------------------------------------------------------------
    surfaces_list: list[dict[str, Any]] = []
    for canary in canary_intents:
        surface: dict[str, Any] = {
            "surface": canary.get("requested_action", "?"),
            "category": "broker_mutation",
            "description": f"Mutation surface: {canary.get('requested_action', '?')} — must be blocked/unperformed",
            "expected_status": "blocked_or_unperformed",
            "endpoint_called": False,
            "mutation_performed": False,
            "broker_state_changed": False,
            "blocked": True,
            "blocker_reason": canary.get("blocking_reasons", ["broker_mutation_firewall_intact"])[0],
        }
        surfaces_list.append(surface)

    all_surfaces_blocked = all(s.get("blocked") for s in surfaces_list)
    mutation_surface_audit: dict[str, Any] = {
        "surfaces_count": len(surfaces_list),
        "surfaces_passed_count": sum(1 for s in surfaces_list if s.get("blocked")),
        "surfaces_failed_count": sum(1 for s in surfaces_list if not s.get("blocked")),
        "surfaces": surfaces_list,
    }

    # ------------------------------------------------------------------
    # 11. Read-only evidence
    # ------------------------------------------------------------------
    evidence_paths: list[dict[str, Any]] = []
    evidence_paths.append({
        "path_type": "export_artifact",
        "path": str(_PHASE16R_EXPORT_DIR),
        "write_allowed": True,
        "broker_mutation": False,
    })
    read_only_evidence: dict[str, Any] = {
        "evidence_paths_count": len(evidence_paths),
        "evidence_paths": evidence_paths,
        "only_export_artifacts_written": True,
        "no_runtime_config_mutation": True,
        "no_env_mutation": True,
        "no_rules_mutation": True,
        "no_guard_repair_performed": True,
        "no_service_restart": True,
        "no_reconnect_attempted": True,
    }

    # ------------------------------------------------------------------
    # 12. Mutation probe matrix
    # ------------------------------------------------------------------
    mutation_probe_matrix: dict[str, Any] = {
        "bridge_read_only": br_read_only,
        "bridge_allow_orders": bridge_allow_orders,
        "env_allow_orders": env_allow_orders in ("false", "?"),
        "rules_enforced": rules_enforced in ("false", "?"),
        "system_locked": system_locked,
        "order_window_open": False,
        "h1_available_to_drill": False,
        "broker_submission_allowed": False,
        "broker_write_allowed": False,
        "account_write_allowed": False,
        "position_write_allowed": False,
        "order_write_allowed": False,
    }

    # ------------------------------------------------------------------
    # 13. Blocked mutation attempts
    # ------------------------------------------------------------------
    blocked_attempts: list[dict[str, Any]] = []
    for i, canary in enumerate(canary_intents):
        attempt_id = f"blocked-mutation-{checkpoint_id}-{i+1:02d}"
        attempt: dict[str, Any] = {
            "attempt_id": attempt_id,
            "attempted_action": canary.get("requested_action", "?"),
            "local_audit_only": True, "blocked": True,
            "block_reason": "; ".join(canary.get("blocking_reasons", [])[:3]),
            "endpoint_called": False,
            "broker_mutation": False,
            "account_mutation": False,
            "position_mutation": False,
            "order_mutation": False,
            "h1_token_used": False,
            "order_window_opened": False,
            "executable": False,
            "performed": False,
        }
        blocked_attempts.append(attempt)

    # ------------------------------------------------------------------
    # 14. Broker-mutation checklist
    # ------------------------------------------------------------------
    broker_mutation_checklist: list[dict[str, Any]] = [
        {"check": "confirms_level1_only", "status": "PASS" if autonomy_level == "1" else "FAIL"},
        {"check": "confirms_audit_only", "status": "PASS"},
        {"check": "confirms_read_only_mode", "status": "PASS" if br_read_only else "FAIL"},
        {"check": "confirms_paper_mode", "status": "PASS" if br_mode == "paper" else "FAIL"},
        {"check": "confirms_positions_flat", "status": "PASS" if positions_flat else "FAIL"},
        {"check": "confirms_no_order_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_preflight_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_approval_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_submit_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_mutation_endpoint_called", "status": "PASS"},
        {"check": "confirms_no_broker_order_created", "status": "PASS"},
        {"check": "confirms_no_broker_submission", "status": "PASS"},
        {"check": "confirms_no_broker_cancel", "status": "PASS"},
        {"check": "confirms_no_broker_modify", "status": "PASS"},
        {"check": "confirms_no_account_mutation", "status": "PASS"},
        {"check": "confirms_no_position_mutation", "status": "PASS"},
        {"check": "confirms_no_order_mutation", "status": "PASS"},
        {"check": "confirms_no_order_window_opened", "status": "PASS"},
        {"check": "confirms_no_h1_used", "status": "PASS"},
        {"check": "confirms_no_h1_header_constructed", "status": "PASS"},
        {"check": "confirms_no_h1_header_sent", "status": "PASS"},
        {"check": "confirms_trade_window_helper_not_called", "status": "PASS"},
        {"check": "confirms_orders_disabled", "status": "PASS" if env_allow_orders in ("false", "?") else "FAIL"},
        {"check": "confirms_system_locked", "status": "PASS" if system_locked else "FAIL"},
        {"check": "confirms_rules_not_enforced", "status": "PASS" if rules_enforced in ("false", "?") else "FAIL"},
        {"check": "confirms_only_export_artifacts_written", "status": "PASS"},
        {"check": "confirms_future_h1_required", "status": "PASS"},
        {"check": "confirms_future_order_window_required", "status": "PASS"},
        {"check": "confirms_future_real_preflight_required", "status": "PASS"},
        {"check": "confirms_future_real_approval_required", "status": "PASS"},
        {"check": "confirms_future_real_submit_required", "status": "PASS"},
    ]
    checklist_pass = sum(1 for c in broker_mutation_checklist if c["status"] == "PASS")
    checklist_total = len(broker_mutation_checklist)
    checklist_complete = checklist_pass == checklist_total

    # ------------------------------------------------------------------
    # 15. Evidence hash
    # ------------------------------------------------------------------
    hashable = {
        "diagnosis": diagnosis, "severity": severity,
        "firewall_status": broker_mutation_firewall["status"],
        "canaries_count": canaries_count, "all_canaries_blocked": all_canaries_blocked,
        "no_broker_mutation": True, "no_order_endpoint_called": True,
        "no_preflight_called": True, "no_approval_called": True, "no_submit_called": True,
    }
    evidence_hash = _compute_evidence_hash(hashable)

    # ------------------------------------------------------------------
    # 16. Workflow summary
    # ------------------------------------------------------------------
    operator_action_required = not checkpoint_ok
    suggested_actions: list[str] = []
    if not checkpoint_ok:
        suggested_actions.append(f"Broker-mutation firewall audit blocked: {diagnosis}")
        if not run_time_ready:
            suggested_actions.append("Ensure bridge is connected in paper read-only mode")
        if not orders_disabled:
            suggested_actions.append("Set IBKR_ALLOW_ORDERS=false in .env")
        if not bridge_ao_disabled:
            suggested_actions.append("Ensure bridge readiness reports allow_orders=false")
        if not rules_not_enforced:
            suggested_actions.append("Set enforced=false in rules YAML")
        if not system_locked_ok:
            suggested_actions.append("Engage system_locked kill-switch")

    workflow_summary: dict[str, Any] = {
        "broker_mutation_firewall_audit_ready": checkpoint_ok,
        "broker_mutation_firewall_artifact_created": False,
        "broker_mutation_firewall_intact": firewall_intact,
        "all_mutation_surfaces_blocked": all_surfaces_blocked,
        "all_blocks_expected": firewall_intact,
        "trade_window_helper_not_called": True,
        "execution_authorized_now_false": True,
        "order_enablement_still_required": True,
        "no_order_endpoint_called": True, "no_preflight_called": True,
        "no_approval_called": True, "no_submit_called": True,
        "no_order_path_called": True,
        "no_broker_order_created": True, "no_broker_submission": True,
        "no_broker_mutation": True, "no_account_mutation": True,
        "no_position_mutation": True, "no_order_window_seen": True,
        "no_h1_used": True,
        "checklist_complete": checklist_complete,
    }

    # ------------------------------------------------------------------
    # 17. Assemble result
    # ------------------------------------------------------------------
    guard_state_clean = gs_assessment.get("guard_state_clean", False)
    gs = gs_assessment.get("guard_section", {})
    canonical_trade_date = gs.get("trade_date", "?")
    trade_date_stale = gs.get("trade_date_stale", False)
    halt_active = gs.get("daily_halt_active", False)

    result: dict[str, Any] = {
        "command": "ibkr-operator level1-broker-mutation-firewall-audit-checkpoint",
        "advisory": (
            "Read-only Level 1 broker-mutation firewall audit checkpoint (Phase 16R). "
            "This checkpoint proves the broker-mutation firewall remains intact "
            "end-to-end: no broker write endpoints called, no orders created, "
            "no submissions, no account/position mutation. The checkpoint succeeds "
            "only when every possible mutation path remains blocked/unperformed and "
            "the runtime stays paper/read-only/flat. This is NOT execution authorization, "
            "NOT broker approval, NOT broker preflight."
        ),
        "timestamp": ts_str, "checkpoint_id": checkpoint_id,
        "canonical_trade_date": canonical_trade_date,
        "trade_date_stale": trade_date_stale,
        "halt_active": halt_active,
        "guard_state_clean": guard_state_clean,
        "diagnosis": diagnosis, "severity": severity,
        "operator_action_required": operator_action_required,
        "suggested_operator_actions": suggested_actions,
        "git": git_section, "required_tags": required_tags,
        "runtime": runtime_section, "autonomy": autonomy_section,
        "safety": safety_section, "guard_state": guard_section,
        "broker_mutation_firewall": broker_mutation_firewall,
        "mutation_surface_audit": mutation_surface_audit,
        "read_only_evidence": read_only_evidence,
        "mutation_probe_matrix": mutation_probe_matrix,
        "blocked_mutation_attempts": blocked_attempts,
        "canary_intents": canary_intents,
        "broker_mutation_checklist": broker_mutation_checklist,
        "workflow_summary": workflow_summary,
        "all_canaries_blocked": all_canaries_blocked,
        "no_canary_executed": no_canary_executed,
        "broker_mutation_firewall_intact": firewall_intact,
        "kpi_summary": kpi_section, "doctor_summary": doctor_section,
        "policy_summary": policy_section,
        "promotion_allowed_now": False, "order_enablement_allowed_now": False,
        "order_enablement_performed": False, "promotion_performed": False,
        "execution_authorized_now": False, "execution_performed": False,
        "no_broker_mutation": True, "no_broker_order_created": True,
        "no_broker_submission": True, "no_account_mutation": True,
        "no_position_mutation": True, "no_order_window_opened": True,
        "no_h1_token_used": True, "no_h1_token_read": True,
        "no_h1_header_constructed": True, "no_h1_header_sent": True,
        "no_order_endpoint_called": True, "no_preflight_endpoint_called": True,
        "no_approval_endpoint_called": True, "no_submit_endpoint_called": True,
        "no_trade_window_helper_called": True,
        "no_trade_window_helper_called_by_drill": True,
        "no_mutation_endpoint_called": True,
        "no_order_mutation": True,
        "h1_token_not_used": True,
        "all_mutation_surfaces_blocked": all_surfaces_blocked,
        "all_blocks_expected": firewall_intact,
        "current_level": 1 if isinstance(autonomy_level, str) and autonomy_level == "1" else int(autonomy_level or 0),
        "evidence_hash": evidence_hash,
        "explicit_non_actions": _PHASE16R_EXPLICIT_NON_ACTIONS,
    }

    # ------------------------------------------------------------------
    # 18. Broker-mutation firewall violation diagnostics
    # ------------------------------------------------------------------
    firewall_intact = True
    firewall_violations: list[str] = []
    violations_checks = [
        ("order_endpoint_called", "order_endpoint_called"),
        ("preflight_endpoint_called", "preflight_endpoint_called"),
        ("approval_endpoint_called", "approval_endpoint_called"),
        ("submit_endpoint_called", "submit_endpoint_called"),
        ("mutation_endpoint_called", "mutation_endpoint_called"),
        ("broker_order_created", "broker_order_created"),
        ("broker_submission_performed", "broker_submission_performed"),
        ("broker_cancel_performed", "broker_cancel_performed"),
        ("broker_modify_performed", "broker_modify_performed"),
        ("account_mutation_performed", "account_mutation_performed"),
        ("position_mutation_performed", "position_mutation_performed"),
        ("order_mutation_performed", "order_mutation_performed"),
        ("order_window_opened", "order_window_opened"),
        ("trade_window_helper_called", "trade_window_helper_called"),
        ("h1_token_used", "h1_token_used"),
        ("h1_header_constructed", "h1_header_constructed"),
        ("h1_header_sent", "h1_header_sent"),
    ]
    for field, label in violations_checks:
        if broker_mutation_firewall.get(field):
            firewall_violations.append(label); firewall_intact = False
    if mutation_surface_audit.get("surfaces_failed_count", 0) > 0:
        firewall_violations.append("mutation_surface_not_blocked"); firewall_intact = False
    if not all_canaries_blocked:
        firewall_violations.append("canary_not_blocked"); firewall_intact = False
    if not no_canary_executed:
        firewall_violations.append("canary_executed"); firewall_intact = False

    if not firewall_intact and checkpoint_ok:
        diagnosis = _PHASE16R_DIAGNOSIS["broker_mutation_firewall_not_intact"]
        severity = "NO_GO"; checkpoint_ok = False
        result["diagnosis"] = diagnosis; result["severity"] = severity

    broker_mutation_firewall["status"] = "firewall_intact" if firewall_intact else "firewall_violation"
    broker_mutation_firewall["disallowed_mutation_paths_blocked"] = firewall_intact
    workflow_summary["broker_mutation_firewall_intact"] = firewall_intact
    workflow_summary["all_mutation_surfaces_blocked"] = firewall_intact
    workflow_summary["all_blocks_expected"] = firewall_intact
    result["broker_mutation_firewall_intact"] = firewall_intact
    if firewall_violations:
        result["firewall_violations"] = firewall_violations

    # ------------------------------------------------------------------
    # 19. Export artifact
    # ------------------------------------------------------------------
    export_written = False
    try:
        _PHASE16R_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        ep = _PHASE16R_EXPORT_DIR / f"{checkpoint_id}.json"
        with open(ep, "w", encoding="utf-8") as f:
            _json.dump(result, f, indent=2, default=str)
        export_path = str(ep); export_written = True
    except Exception:
        export_path = None

    result["export_path"] = export_path
    result["broker_mutation_firewall"]["audit_artifact_path"] = export_path
    result["workflow_summary"]["broker_mutation_firewall_artifact_created"] = export_written
    return result


