    from trading_agent.cli.operator_workflow_helpers import _assess_guard_state_cleanliness, _assess_kpi_hold_only_system_locked, _compute_evidence_hash, _get_worktree_state
    import json as _json
    from datetime import datetime, timezone
    now_utc = datetime.now(timezone.utc)
    ts_str = now_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    checkpoint_id = f"17i-{now_utc.strftime('%Y%m%dT%H%M%SZ')}"
    repo_path = Path(__file__).resolve().parents[2]
    git_section = _git_metadata(repo_path)
